import com.google.gson.JsonObject;
import net.minecraft.advancements.PlayerAdvancements;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.GsonHelper;

import java.util.ArrayList;
import java.util.List;

public interface ICriterionTrigger {
    ResourceLocation getId();

    void addListener(Listener listener);

    void removeListener(Listener listener);

    void removeAllListeners();

    default Listener deserializeInstance(JsonObject jsonObject, PlayerAdvancements playerAdvancements, DeserializationContext deserializationContext) {
        ResourceLocation resourceLocation = new ResourceLocation(GsonHelper.getAsString(jsonObject, "criterion"));
        CriterionInstance criterionInstance = playerAdvancements.getCriterion(resourceLocation);
        if (criterionInstance != null) {
            return new Listener(criterionInstance, GsonHelper.getAsJsonObject(jsonObject, "trigger"), resourceLocation.toString());
        } else {
            throw new JsonSyntaxException("Unknown criterion: " + resourceLocation);
        }
    }

    class Listener {
        private final CriterionInstance criterionInstance;
        private final JsonObject advancement;
        private final String criterionName;

        public Listener(CriterionInstance criterionInstance, JsonObject advancement, String criterionName) {
            this.criterionInstance = criterionInstance;
            this.advancement = advancement;
            this.criterionName = criterionName;
        }

        public CriterionInstance getCriterionInstance() {
            return criterionInstance;
        }

        public JsonObject getAdvancement() {
            return advancement;
        }

        public String getCriterionName() {
            return criterionName;
        }
    }

    class DeserializationContext {
        private final List<Listener> listeners = new ArrayList<>();

        public void addListener(Listener listener) {
            listeners.add(listener);
        }

        public void removeListener(Listener listener) {
            listeners.remove(listener);
        }

        public void removeAllListeners() {
            listeners.clear();
        }
    }
}

