public class ImagePagerActivity extends FragmentActivity {

    private static final String STATE_POSITION = "STATE_POSITION";
    public static final String EXTRA_IMAGE_INDEX = "image_index";
    public static final String EXTRA_IMAGE_URLS = "image_urls";

    private HackyViewPager mPager;
    private int pagerPosition;
    private ArrayList<String> urls;
    private LinearLayout indicator;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        requestWindowFeature(Window.FEATURE_NO_TITLE);
        getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN, WindowManager.LayoutParams.FLAG_FULLSCREEN);

        setContentView(R.layout.activity_image_pager);

        urls = getIntent().getStringArrayListExtra(EXTRA_IMAGE_URLS);
        pagerPosition = getIntent().getIntExtra(EXTRA_IMAGE_INDEX, 0);

        mPager = findViewById(R.id.pager);
        indicator = findViewById(R.id.indicator);

        ImagePagerAdapter adapter = new ImagePagerAdapter(getSupportFragmentManager(), urls);
        mPager.setAdapter(adapter);
        mPager.setCurrentItem(pagerPosition);

        mPager.setOnPageChangeListener(new ViewPager.SimpleOnPageChangeListener() {
            @Override
            public void onPageSelected(int position) {
                pagerPosition = position;
                updateIndicator();
            }
        });

        updateIndicator();
    }

    private void updateIndicator() {
        for (int i = 0; i < indicator.getChildCount(); i++) {
            ImageView imageView = (ImageView) indicator.getChildAt(i);
            imageView.setImageResource(i == pagerPosition ? R.drawable.dot_selected : R.drawable.dot_unselected);
        }
    }

    @Override
    protected void onSaveInstanceState(Bundle outState) {
        super.onSaveInstanceState(outState);
        outState.putInt(STATE_POSITION, pagerPosition);
    }

    @Override
    protected void onRestoreInstanceState(Bundle savedInstanceState) {
        super.onRestoreInstanceState(savedInstanceState);
        pagerPosition = savedInstanceState.getInt(STATE_POSITION);

