class CalcRSI {

    public static double getCurrentRSI(MarketDay marketDay) {
        List<MarketCandle> candles = marketDay.getMarketCandles();
        if (candles.size() <= 14) {
            return 0; // Not enough data for RSI calculation
        }

        List<Double> priceChanges = new ArrayList<>();
        for (int i = 1; i < candles.size(); i++) {
            priceChanges.add(candles.get(i).getClosePrice() - candles.get(i - 1).getClosePrice());
        }

        double[] firstAverages = getFirstAverages(priceChanges);
        double avgGain = firstAverages[0];
        double avgLoss = firstAverages[1];

        if (priceChanges.size() > 14) {
            double[] smoothAverages = getSmoothAverages(priceChanges, avgGain, avgLoss);
            avgGain = smoothAverages[0];
            avgLoss = smoothAverages[1];
        }

        return getRSI(avgGain, avgLoss);
    }

    private static double[] getFirstAverages(List<Double> priceChanges) {
        double gainSum = 0;
        double lossSum = 0;
        for (int i = 0; i < 14; i++) {
            if (priceChanges.get(i) > 0) {
                gainSum += priceChanges.get(i);
            } else if (priceChanges.get(i) < 0) {
                lossSum += Math.abs(priceChanges.get(i));
            }
        }
        double avgGain = gainSum / 14.0;
        double avgLoss = lossSum / 14.0;
        return new double[] {avgGain, avgLoss};
    }

    private static double[] getSmoothAverages(List<Double> priceChanges, double initialAvgGain, double initialAvgLoss) {
        double avgGain = initialAvgGain;
        double avgLoss = initialAvgLoss;

        for (int i = 14; i < priceChanges.size(); i++) {
            double change = priceChanges.get(i);
            double currentGain = 0;
            double currentLoss = 0;

            if (change > 0) {
                currentGain = change;
            } else if (change < 0) {
                currentLoss = Math.abs(change);
            }

import org.apache.hadoop.hbase.HConstants;

/**
 * Exception thrown when an operation failed due to an unknown row lock.
 *
 * <p>This can happen if the lock expired or was otherwise invalidated
 * on the server side. In this case, the operation cannot be retried with
 * the same {@link RowLock}. You will need to re-acquire a new lock and
 * retry the whole process from scratch.
 * </p>
 * <p>
 * This exception is non-recoverable.
 * </p>
 */
public final class UnknownRowLockException
  extends NonRecoverableException
  implements HasFailedRpcException {

  private static final long serialVersionUID = 1548521568457895123L;

  /**
   * Used to serialize exceptions remotely.
   * @see #REMOTE_CLASS_NAME
   */
  private static final byte REMOTE_CLASS = 10;

  /** The RPC that failed because of this exception.  */
  private final HBaseRpc failed_rpc;

  /**
   * Constructor.
   * @param rpc The RPC that failed.
   * @param msg The message of the exception.
   */
  public UnknownRowLockException(final HBaseRpc rpc, final String msg) {
    super(msg);
    this.failed_rpc = rpc;
  }

  /**
   * Returns the RPC that failed because of this exception.
   * @return The failed RPC.
   */
  @Override
  public HBaseRpc getFailedRpc() {
    return failed_rpc;
  }

  /**
   * Create a new {@code UnknownRowLockException} with a cause.
   * @param rpc The RPC that failed.
   * @param cause The exception that caused this exception.
   * @return A new {@code UnknownRowLockException} with the given cause.
   */
  public static UnknownRowLockException make(final HBaseRpc rpc,
                                               final Throwable cause) {
    final UnknownRowLockException e =
      new UnknownRowLockException(rpc, cause.getMessage());
    e.initCause(cause);
    return e;
  }
}

