import java.util.Map;

/**
 * Class CartController
 */
@WebServlet(urlPatterns="/orders/view/*")
public class ViewController extends BaseOrderController {
    @Override
    protected void processRequest(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        UserUtil userUtil = new UserUtil(request.getSession());

        Order order = findResource(request);
        if (order == null) {
            forward404(request, response);
            return;
        }

        // Check permission
        if (!userUtil.isAdmin() && order.getUserId() != userUtil.getUser().getId()) {
            forward403(request, response);
            return;
        }

        OrderBookDAO orderBookDAO = DbUtil.getDAO(OrderBookDAO.class);
        BookDAO bookDAO = DbUtil.getDAO(BookDAO.class);
        UserDAO userDAO = DbUtil.getDAO(UserDAO.class);

        double orderAmount = 0d;

        // Set order books and book detail
        List<OrderBook> orderBookList = orderBookDAO.findAllByOrder(order.getId());
        for (OrderBook book : orderBookList) {
            Book bookDetail;
            if ((bookDetail = bookDAO.find(book.getBookId())) != null) {
                book.setBook(bookDetail);
            } else {
                book.setBook(new Book(0, 0, "Removed Book", "", "", 0, 0, "", ""));
            }
            orderAmount += book.getCount() * book.getBook().getPrice();
        }
        order.setBookList(orderBookList);

        User orderUser = userDAO.find(order.getUserId());

        request.setAttribute("order", order);
        request.setAttribute("orderBookList", orderBookList);
        request.setAttribute("orderAmount", orderAmount);
        request.setAttribute("orderUser", orderUser);
        forward(request, response, "/orders/view.jsp");
    }
}

import java.util.Scanner;

public class RectangleOverlapExample {

    public static void main(String[] args) {
        // create a scanner to read user input
        Scanner scanner = new Scanner(System.in);

        // prompt the user to enter the first rectangle's center coordinates, width, and height
        System.out.println("Enter the center x-coordinate, center y-coordinate, width, and height of the first rectangle (separated by spaces):");
        double x1 = scanner.nextDouble();
        double y1 = scanner.nextDouble();
        double w1 = scanner.nextDouble();
        double h1 = scanner.nextDouble();

        // prompt the user to enter the second rectangle's center coordinates, width, and height
        System.out.println("Enter the center x-coordinate, center y-coordinate, width, and height of the second rectangle (separated by spaces):");
        double x2 = scanner.nextDouble();
        double y2 = scanner.nextDouble();
        double w2 = scanner.nextDouble();
        double h2 = scanner.nextDouble();

        // calculate the coordinates of the top-left and bottom-right corners of the rectangles
        double x1Min = x1 - w1 / 2;
        double y1Min = y1 - h1 / 2;
        double x1Max = x1 + w1 / 2;
        double y1Max = y1 + h1 / 2;
        double x2Min = x2 - w2 / 2;
        double y2Min = y2 - h2 / 2;
        double x2Max = x2 + w2 / 2;
        double y2Max = y2 + h2 / 2;

        // check if the rectangles overlap or one is contained in the other
        String overlapStatus;
        if (x1Min <= x2Max && x1Max >= x2Min && y1Min <= y2Max && y1Max >= y2Min) {
            // rectangles overlap
            overlapStatus = "Overlap";
        } else if (x1Min >= x2Min && x1Max <= x2Max && y1Min >= y2Min && y1Max <= y2Max) {
            // rectangle 1 is contained in rectangle 2
            overlapStatus = "Rectangle 1 is contained in Rectangle 2";
        } else if (x2Min >= x1Min && x2Max <= x1Max && y2Min >= y1Min && y2Max <= y1Max) {
            // rectangle 2 is contained in rectangle 1
            overlapStatus = "Rectangle 2 is contained in Rectangle 1";
        } else {
            // rectangles don't overlap
            overlapStatus = "No overlap";
        }

        // display the rectangles and overlap status
        System.out.println("Rectangle 1: (" + x1 + ", " + y1 + "), width=" + w1 + ", height=" + h1);
        System.out.println("Rectangle 2: (" + x2 + ", " + y2 + "), width=" + w2 + ", height=" + h2);
        System.out.println("Overlap status: " + overlapStatus);
    }
}

import java.util.ArrayList;
import java.util.List;

public class HashTable<K, V> {
    private static final int DEFAULT_CAPACITY = 16;
    private static final double LOAD_FACTOR = 0.75;

    private int size;
    private int capacity;
    private List<Entry<K, V>>[] table;

    public HashTable() {
        this(DEFAULT_CAPACITY);
    }

    public HashTable(int capacity) {
        this.size = 0;
        this.capacity = capacity;
        this.table = new ArrayList[capacity];
    }

    public void put(K key, V value) {
        if (size >= capacity * LOAD_FACTOR) {
            resize();
        }

        int index = getIndex(key);

        if (table[index] == null) {
            table[index] = new ArrayList<>();
        }

        for (Entry<K, V> entry : table[index]) {
            if (entry.getKey().equals(key)) {
                entry.setValue(value);
                return;
            }
        }

        table[index].add(new Entry<>(key, value));
        size++;
    }

    public V get(K key) {
        int index = getIndex(key);

        if (table[index] != null) {
            for (Entry<K, V> entry : table[index]) {
                if (entry.getKey().equals(key)) {
                    return entry.getValue();
                }
            }
        }

        return null;
    }

    public void remove(K key) {
        int index = getIndex(key);

        if (table[index] != null) {
            for (Entry<K, V> entry : table[index]) {
                if (entry.getKey().equals(key)) {
                    table[index].remove(entry);
                    size--;
                    return;
                }
            }
        }
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    private int getIndex(K key) {
        return key.hashCode() % capacity;
    }

    private void resize() {
        capacity *= 2;
        List<Entry<K, V>>[] newTable = new ArrayList[capacity];

        for (int i = 0; i < table.length; i++) {
            if (table[i] != null) {
                for (Entry<K, V> entry : table[i]) {
                    int index = getIndex(entry.getKey());

                    if (newTable[index] == null) {
                        newTable[index] = new ArrayList<>();
                    }

                    newTable[index].add(entry);
                }
            }
        }

        table = newTable;
    }

    private static class Entry<K, V> {
        private K key;
        private V value;

        public Entry(K key, V value) {
            this.key = key;

/**
