import java.util.Properties;

import se.mah.elis.services.users.PlatformUser;
import se.mah.elis.services.users.User;
import se.mah.elis.services.users.exceptions.UserInitalizationException;

/**
 * The UserFactory builds users. A UserProvider can register with a UserFactory
 * so that the factory can produce the user types provided by the UserProvider.
 *
 */
public interface UserFactory {

    /**
     * Registers a user provider with this factory.
     *
     * @param provider The UserProvider to register.
     */
    public void registerProvider(UserProvider provider);

    /**
     * Unregisters a user provider from this factory.
     *
     * @param provider The UserProvider to unregister.
     */
    public void unregisterProvider(UserProvider provider);

    /**
     * Builds a user. As a user type can be provided by several different
     * supporting services, we must also provide the name of the service that
     * the user should target.
     *
     * @param userType The user type that we want to build. This should match
     *        the name of the implemented User interface.
     * @param serviceName The name of the service that we want to target.
     * @param properties The properties of the new user, as specified by its
     *        UserRecipe.
     * @return The newly built User object.
     * @throws UserInitalizationException if the user couldn't be built for
     *         whatever reason.
     */
    public User build(String userType, String serviceName, Properties properties)
            throws UserInitalizationException;

    /**
     * Builds a platform user.
     *
     * @param properties The properties of the new platform user, as specified
     *        by its UserRecipe.
     * @return The newly built PlatformUser object.
     * @throws UserInitalizationException if the user couldn't be built for
     *         whatever reason.
     */
    public PlatformUser build(Properties properties)
            throws UserInitalizationException;

    /**
     * Returns a list of all available user recipes.
     *
     * @return An array of user recipes. If no user recipes are available, the
     *         method returns an empty array.
     */
    public UserRecipe[] getAvailableUserRecipes();

    /**
     * Returns a user recipe.
     *
     * @param userType The user type that we want a recipe for.
     * @param systemName The name of the system providing the user.
     * @return A user recipe.
     */
    public UserRecipe getRecipe(String userType, String systemName);
}

import org.deeplearning4j.nn.api.OptimizationAlgorithm;
import org.deeplearning4j.nn.conf.MultiLayerConfiguration;
import org.deeplearning4j.nn.conf.NeuralNetConfiguration;
import org.deeplearning4j.nn.conf.inputs.InputType;
import org.deeplearning4j.nn.conf.layers.ConvolutionLayer;
import org.deeplearning4j.nn.conf.layers.DenseLayer;
import org.deeplearning4j.nn.conf.layers.OutputLayer;
import org.deeplearning4j.nn.multilayer.MultiLayerNetwork;
import org.deeplearning4j.nn.weights.WeightInit;
import org.nd4j.linalg.activations.Activation;
import org.nd4j.linalg.learning.config.Nesterovs;
import org.nd4j.linalg.lossfunctions.LossFunctions;

public class CNN {

    public MultiLayerNetwork buildNetwork(int height, int width, int channels, int numLabels) {
        MultiLayerConfiguration conf = new NeuralNetConfiguration.Builder()
            .seed(123)
            .optimizationAlgo(OptimizationAlgorithm.STOCHASTIC_GRADIENT_DESCENT)
            .weightInit(WeightInit.XAVIER)
            .updater(new Nesterovs(0.01, 0.9))
            .list()
            .layer(0, new ConvolutionLayer.Builder(5, 5)
                .nIn(channels)
                .stride(1, 1)
                .nOut(20)
                .activation(Activation.IDENTITY)
                .build())
            .layer(1, new DenseLayer.Builder().activation(Activation.RELU)
                .nOut(50).build())
            .layer(2, new OutputLayer.Builder(LossFunctions.LossFunction.NEGATIVELOGLIKELIHOOD)
                .nOut(numLabels)
                .activation(Activation.SOFTMAX)
                .build())
            .setInputType(InputType.convolutional(height, width, channels))
            .build();

        MultiLayerNetwork model = new MultiLayerNetwork(conf);
        model.init();

        return model;
    }
}

import com.intellij.psi.PsiExpression;
import com.intellij.psi.PsiMethodCallExpression;
import com.intellij.psi.PsiNewExpression;
import com.intellij.psi.PsiReferenceExpression;
import com.siyeh.InspectionGadgetsBundle;
import com.siyeh.ig.psiutils.TypeUtils;
import org.jetbrains.annotations.NonNls;
import org.jetbrains.annotations.NotNull;

public class JNDIResourceInspection extends ResourceInspection {

  @Override
  @NotNull
  public String getID() {
    return "JNDIResourceOpenedButNotSafelyClosed";
  }

  @Override
  @NotNull
  public String getDisplayName() {
    return InspectionGadgetsBundle.message("jndi.resource.opened.not.closed.display.name");
  }

  protected boolean isResourceCreation(PsiExpression expression) {
    if (expression instanceof PsiMethodCallExpression) {
      final PsiMethodCallExpression methodCallExpression = (PsiMethodCallExpression)expression;
      final PsiReferenceExpression methodExpression = methodCallExpression.getMethodExpression();
      @NonNls final String methodName = methodExpression.getReferenceName();
      if ("list".equals(methodName) || "listBindings".equals(methodName)) {
        final PsiExpression qualifier = methodExpression.getQualifierExpression();
        if (qualifier == null) {
          return false;
        }
        return TypeUtils.expressionHasTypeOrSubtype(qualifier, "javax.naming.Context");
      }
      else if ("getAll".equals(methodName)) {
        final PsiExpression qualifier = methodExpression.getQualifierExpression();
        if (qualifier == null) {
          return false;
        }
        return TypeUtils.expressionHasTypeOrSubtype(qualifier, "javax.naming.directory.Attribute", "javax.naming.directory.Attributes") !=
               null;
      }
      else {
        return false;
      }
    }
    else if (expression instanceof PsiNewExpression) {
      return TypeUtils.expressionHasTypeOrSubtype(expression, "javax.naming.InitialContext");
    }
    return false;
  }
}

import java.io.IOException;
import java.util.*;
import si.mazi.rescu.RestProxyFactory;
import com.xeiam.xchange.*;
import com.xeiam.xchange.justcoin.*;
import com.xeiam.xchange.utils.AuthUtils;

/**
 *  Base polling service for Justcoin exchange.
 */
public class JustcoinBasePollingService<T extends Justcoin> extends BaseExchangeService {

    private final T justcoin;
    private Set<CurrencyPair> currencyPairs;
    private final ExchangeSpecification exchangeSpecification;

    /**
     * Constructor
     *
     * @param exchangeSpecification The exchange specification.
     * @param justcoinInterface The Justcoin API interface class.
     */
    public JustcoinBasePollingService(ExchangeSpecification exchangeSpecification, Class<T> justcoinInterface) {
        super(exchangeSpecification);
        this.exchangeSpecification = exchangeSpecification;
        this.justcoin = RestProxyFactory.createProxy(justcoinInterface, exchangeSpecification.getSslUri());
    }

    /**
     *  Gets the exchange symbols. Fetches from API on first call and caches.
     *
     * @return Set of CurrencyPair supported by exchange
     * @throws IOException If fetching tickers fails.
     */
    public Set<CurrencyPair> getExchangeSymbols() throws IOException {
        if (currencyPairs == null) {
            currencyPairs = new HashSet<>();
            JustcoinTicker[] tickers = justcoin.getTickers(); // Fetch ticker data
            for (JustcoinTicker ticker : tickers) { // Iterate over tickers
                currencyPairs.add(JustcoinAdapters.adaptCurrencyPair(ticker.getPair())); // Adapt and add
            }
        }
        return currencyPairs; // Return cached currency pairs
    }

    /**
     *  Generates basic authentication string.
     *
     * @return Basic authentication string.
     */
    public String getBasicAuthentication() {
        String userName = exchangeSpecification.getUserName(); // Get username
        String password = exchangeSpecification.getPassword(); // Get password
        return AuthUtils.basicAuth(userName, password); // Create and return auth string
    }
}

