public class KMPAlgorithm {
    public static int[] computeLPS(String pattern) {
        int[] lps = new int[pattern.length()];
        int j = 0;
        for (int i = 1; i < pattern.length(); i++) {
            while (j > 0 && pattern.charAt(j) != pattern.charAt(i)) {
                j = lps[j - 1];
            }
            if (pattern.charAt(j) == pattern.charAt(i)) {
                j++;
            }
            lps[i] = j;
        }
        return lps;
    }

    public static List<Integer> search(String text, String pattern) {
        List<Integer> matches = new ArrayList<>();
        int[] lps = computeLPS(pattern);
        int i = 0, j = 0;
        while (i < text.length()) {
            if (text.charAt(i) == pattern.charAt(j)) {
                i++;
                j++;
                if (j == pattern.length()) {
                    matches.add(i - j);
                    j = lps[j - 1];
                }
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return matches;
    }
}

public class KMPExample {
    public static void main(String[] args) {
        String text = "ABCABCABCABDABCABCDABCABCABCABCD";
        String pattern = "ABCABCABCD";
        List<Integer> matches = KMPAlgorithm.search(text, pattern);
        System.out.println("Matches found at positions: " + matches);
    }
}

import com.googlecode.pongo.runtime.querying.NumericalQueryProducer;
import com.googlecode.pongo.runtime.querying.StringQueryProducer;

public class DatetimeMeasurement extends Measurement {

    public DatetimeMeasurement() {
        super();
        super.setSuperTypes("org.ossmeter.metricprovider.rascal.trans.model.Measurement");
        URI.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
        VALUE.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
        TIME_ZONE_HOURS.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
        TIME_ZONE_MINS.setOwningType("org.ossmeter.metricprovider.rascal.trans.model.DatetimeMeasurement");
    }

    private static final String VALUE_KEY = "value";
    private static final String TIME_ZONE_HOURS_KEY = "tz_hours";
    private static final String TIME_ZONE_MINS_KEY = "tz_mins";

    public static StringQueryProducer URI = new StringQueryProducer("uri");
    public static NumericalQueryProducer VALUE = new NumericalQueryProducer(VALUE_KEY);
    public static NumericalQueryProducer TIME_ZONE_HOURS = new NumericalQueryProducer(TIME_ZONE_HOURS_KEY);
    public static NumericalQueryProducer TIME_ZONE_MINS = new NumericalQueryProducer(TIME_ZONE_MINS_KEY);

    public long getValue() {
        return parseLong(dbObject.get(VALUE_KEY)+"", 0);
    }

    public int getTimezoneHours() {
        if (dbObject.containsField(TIME_ZONE_HOURS_KEY)) {
            return parseInteger(dbObject.get(TIME_ZONE_HOURS_KEY) + "", 0);
        }
        else {
            return 0;
        }
    }

    public int getTimezoneMinutes() {
        if (dbObject.containsField(TIME_ZONE_MINS_KEY)) {
            return parseInteger(dbObject.get(TIME_ZONE_MINS_KEY) + "", 0);
        }
        else {
            return 0;
        }
    }

    public DatetimeMeasurement setValue(long value, int timezoneHours, int timezoneMinutes) {
        dbObject.put(VALUE_KEY, value);
        dbObject.put(TIME_ZONE_HOURS_KEY, timezoneHours);
        dbObject.put(TIME_ZONE_MINS_KEY, timezoneMinutes);
        notifyChanged();
        return this;
    }
}

import java.util.HashMap;
import java.util.Map;

public class RecommenderSystem {

    private Map<String, Map<String, Double>> userRatings;

    public RecommenderSystem() {
        userRatings = new HashMap<>();
    }

    public void addRating(String user, String item, double rating) {
        if (!userRatings.containsKey(user)) {
            userRatings.put(user, new HashMap<>());
        }
        userRatings.get(user).put(item, rating);
    }

    public double getSimilarity(String user1, String user2) {
        Map<String, Double> ratings1 = userRatings.get(user1);
        Map<String, Double> ratings2 = userRatings.get(user2);
        double dotProduct = 0;
        double magnitude1 = 0;
        double magnitude2 = 0;
        for (String item : ratings1.keySet()) {
            if (ratings2.containsKey(item)) {
                dotProduct += ratings1.get(item) * ratings2.get(item);
                magnitude1 += Math.pow(ratings1.get(item), 2);
                magnitude2 += Math.pow(ratings2.get(item), 2);
            }
        }
        return dotProduct / (Math.sqrt(magnitude1) * Math.sqrt(magnitude2));
    }

    public double predictRating(String user, String item) {
        double weightedSum = 0;
        double similaritySum = 0;
        for (String otherUser : userRatings.keySet()) {
            if (!otherUser.equals(user) && userRatings.get(otherUser).containsKey(item)) {
                double similarity = getSimilarity(user, otherUser);
                weightedSum += similarity * userRatings.get(otherUser).get(item);
                similaritySum += similarity;
            }
        }
        return weightedSum / similaritySum;
    }

    public static void main(String[] args) {
        RecommenderSystem system = new RecommenderSystem();
        system.addRating("user1", "item1", 5);
        system.addRating("user1", "item2", 3);
        system.addRating("user1", "item3", 4);
        system.addRating("user2", "item1", 3);
        system.addRating("user2", "item2", 4);
        system.addRating("user2", "item3", 5);
        system.addRating("user3", "item1", 2);
        system.addRating("user3", "item2", 3);
        System.out.println(system.predictRating("user1", "item3")); // should return 4
    }
}

import java.util.HashMap;
import java.util.Map;

public class StringPool {
    private Map<String, Integer> internedItems;
    private int nextIndex;

    public StringPool() {
        this.internedItems = new HashMap<>();
        this.nextIndex = 1; // Start from 1 as 0 is often reserved
    }

    public int intern(String item) {
        if (item == null) {
            throw new NullPointerException("Cannot intern null string");
        }
        return internNullable(item);
    }

    public int internNullable(String item) {
        if (item == null) {
            return -1; // or any other value to indicate null
        }
        if (internedItems.containsKey(item)) {
            return internedItems.get(item);
        } else {
            int index = nextIndex++;
            internedItems.put(item, index);
            return index;
        }
    }

    public int getItemIndex(String item) {
        if (item == null) {
            return -1; // or any other value to indicate null
        }
        return internedItems.getOrDefault(item, -1);
    }

    public boolean hasJumboIndexes() {
        return nextIndex > 65536;
    }
}

import android.support.annotation.NonNull;
import android.support.annotation.Nullable;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.ParameterizedRobolectricTestRunner;
import org.robolectric.ParameterizedRobolectricTestRunner.Parameters;
import org.wikipedia.page.Namespace;

import java.util.Arrays;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import static org.wikipedia.json.GsonMarshaller.marshal;
import static org.wikipedia.json.GsonUnmarshaller.unmarshal;

@RunWith(ParameterizedRobolectricTestRunner.class) public class NamespaceTypeAdapterTest {
    @Parameters(name = "{0}") public static Iterable<Object[]> data() {
        return Arrays.asList(new Object[][] {{DeferredParam.NULL}, {DeferredParam.SPECIAL},
                {DeferredParam.MAIN}, {DeferredParam.TALK}});
    }

    @Nullable private final Namespace namespace;

    public NamespaceTypeAdapterTest(@NonNull DeferredParam param) {
        this.namespace = param.val();
    }

    @Test public void testWriteRead() {
        Namespace result = unmarshal(Namespace.class, marshal(namespace));
        assertThat(result, is(namespace));
    }

    @Test public void testReadOldData() throws Throwable {
        // Prior to 3210ce44, we marshaled Namespace as the name string of the enum, instead of
        // the code number, and when we switched to using the code number, we didn't introduce
        // backwards-compatible checks for the old-style strings that may still be present in
        // some local serialized data.
        // TODO: remove after April 2017?
        String marshaledStr = namespace == null ? "null" : "\"" + namespace.name() + "\"";
        Namespace ns = unmarshal(Namespace.class, marshaledStr);
        assertThat(ns, is(namespace));
    }

    // SparseArray is a Roboelectric mocked class which is unavailable at static time; defer
    // evaluation until TestRunner is executed
    private enum DeferredParam {
        NULL() {
            @Nullable @Override
            Namespace val() {
                return null;
            }
        },
        SPECIAL() {
            @Nullable @Override Namespace val() {
                return Namespace.SPECIAL;
            }
        },
        MAIN() {
            @Nullable @Override Namespace val() {
                return Namespace.MAIN;
            }
        },
        TALK() {
            @Nullable @Override Namespace val() {
                return Namespace.TALK;
            }
        };

        @Nullable abstract Namespace val();
    }
}

import simulation.data.PetrolStation;
import simulation.data.Road;

/**
 */

public class PetrolStationGenerator {
    private Road road;
    private int minimalDistanceBetweenStations = 50;
    private int maximumDistanceBetweenStations = 200;
    private float minimalFuelPrice = 3.5f;
    private float maximumFuelPrice = 4f;

    public PetrolStationGenerator(Road road) {
        this.road = road;
    }

    public void generateStationsOnTheRoad(){
        RandomIntegerGenerator generator = new RandomIntegerGenerator();
        int lastStationPosition = 0;
        road.addPetrolStation(generateStation(lastStationPosition));

        while (lastStationPosition < road.getDistance()){
           int nextStationDistance = generator.generateNumberFromRange(minimalDistanceBetweenStations,maximumDistanceBetweenStations);

           if(lastStationPosition+nextStationDistance <= road.getDistance()){
                road.addPetrolStation(generateStation(lastStationPosition+nextStationDistance));
                lastStationPosition += nextStationDistance;
           }else{
               break;
           }

        }
    }

    private PetrolStation generateStation(int positionOnRoad){
        float fuelPrice = new RandomFloatGenerator().generateNumberFromRange(minimalFuelPrice,maximumFuelPrice);

        return new PetrolStation(positionOnRoad,fuelPrice);
    }

    public Road getRoad() {
        return road;
    }

    public void setRoad(Road road) {
        this.road = road;
    }

    public int getMinimalDistanceBetweenStations() {
        return minimalDistanceBetweenStations;
    }

    public void setMinimalDistanceBetweenStations(int minimalDistanceBetweenStations) {
        this.minimalDistanceBetweenStations = minimalDistanceBetweenStations;
    }

    public int getMaximumDistanceBetweenStations() {
        return maximumDistanceBetweenStations;
    }

    public void setMaximumDistanceBetweenStations(int maximumDistanceBetweenStations) {
        this.maximumDistanceBetweenStations = maximumDistanceBetweenStations;
    }

    public float getMinimalFuelPrice() {
        return minimalFuelPrice;
    }

    public void setMinimalFuelPrice(float minimalFuelPrice) {
        this.minimalFuelPrice = minimalFuelPrice;
    }

    public float getMaximumFuelPrice() {
        return maximumFuelPrice;
    }

    public void setMaximumFuelPrice(float maximumFuelPrice) {
        this.maximumFuelPrice = maximumFuelPrice;
    }
}

import java.sql.Connection;
import java.sql.SQLException;

/**
 * Interface defining the contract for managing application component instances
 * within a user space.
 * It handles the creation and removal of component instances.
 */
public interface ComponentsInstanciatorIntf {

    /**
     * Constant for referencing the component descriptor parameter related to a process file.
     */
    String PROCESS_XML_FILE_NAME = "process_xml_file_name";

    /**
     * Creates a new instance of the specified component within the given space for the designated user.
     *
     * @param connection    Database connection details.
     * @param spaceId       Identifier of the space.
     * @param componentId   Identifier of the component.
     * @param userId        Identifier of the user.
     * @throws InstanciationException If component instantiation fails.
     * @throws SQLException           If a database error occurs.
     */
    void create(Connection connection, String spaceId, String componentId, String userId)
            throws InstanciationException, SQLException;

    /**
     * Removes the instance of the specified component from the given space associated with the designated user.
     *
     * @param connection    Database connection details.
     * @param spaceId       Identifier of the space.
     * @param componentId   Identifier of the component.
     * @param userId        Identifier of the user.
     * @throws InstanciationException If component deletion fails.
     * @throws SQLException           If a database error occurs.
     */
    void delete(Connection connection, String spaceId, String componentId, String userId)
            throws InstanciationException, SQLException;
}

/**
 * Custom exception class for handling component instantiation failures.
 */
class InstanciationException extends Exception {

    public InstanciationException(String message) {
        super(message);
    }

    public InstanciationException(String message, Throwable cause) {
        super(message, cause);
    }
}

import android.annotation.TargetApi;
import android.app.ActionBar;
import android.app.Activity;
import android.os.Build;
import android.view.View;
import android.view.WindowManager;

@TargetApi(Build.VERSION_CODES.HONEYCOMB)
class SystemUiHelperImplHC extends SystemUiHelper.SystemUiHelperImpl
        implements View.OnSystemUiVisibilityChangeListener {

    final View mDecorView;

    SystemUiHelperImplHC(Activity activity, int level, int flags,
            SystemUiHelper.OnVisibilityChangeListener onVisibilityChangeListener) {
        super(activity, level, flags, onVisibilityChangeListener);

        mDecorView = activity.getWindow().getDecorView();
        mDecorView.setOnSystemUiVisibilityChangeListener(this);
    }

    @Override
    void show() {
        mDecorView.setSystemUiVisibility(createShowFlags());
    }

    @Override
    void hide() {
        mDecorView.setSystemUiVisibility(createHideFlags());
    }

    @Override
    public final void onSystemUiVisibilityChange(int visibility) {
        if ((visibility & createTestFlags()) != 0) {
            onSystemUiHidden();
        } else {
            onSystemUiShown();
        }
    }

    protected void onSystemUiShown() {
        ActionBar ab = mActivity.getActionBar();
        if (ab != null) {
            ab.show();
        }

        mActivity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);

        setIsShowing(true);
    }

    protected void onSystemUiHidden() {
        ActionBar ab = mActivity.getActionBar();
        if (ab != null) {
            ab.hide();
        }

        mActivity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);

        setIsShowing(false);
    }

    protected int createShowFlags() {
       return View.STATUS_BAR_VISIBLE;
    }

    protected int createHideFlags() {
        return View.STATUS_BAR_HIDDEN;
    }

    protected int createTestFlags() {
        return View.STATUS_BAR_HIDDEN;
    }
}

