import java.util.HashMap;
import java.util.Map;

import org.eclipse.debug.core.ILaunch;
import org.eclipse.debug.core.ILaunchesListener;

public class ResolveBlackList implements ILaunchesListener {
    private static ResolveBlackList instance;
    private Map<ILaunch, Map<String, Type>> blackListMap;

    private enum Type {
        FILE, FOLDER, RECURSIVE
    }

    private ResolveBlackList() {
        blackListMap = new HashMap<>();
    }

    public static ResolveBlackList getInstance() {
        if (instance == null) {
            instance = new ResolveBlackList();
        }
        return instance;
    }

    public void add(ILaunch launch, String path, Type type) {
        if (!blackListMap.containsKey(launch)) {
            blackListMap.put(launch, new HashMap<>());
        }
        blackListMap.get(launch).put(path, type);
    }

    public boolean containsEntry(ILaunch launch, String path) {
        if (!blackListMap.containsKey(launch)) {
            return false;
        }
        Map<String, Type> paths = blackListMap.get(launch);
        for (Map.Entry<String, Type> entry : paths.entrySet()) {
            String blacklistedPath = entry.getKey();
            Type type = entry.getValue();
            if (type == Type.FILE && path.equals(blacklistedPath)) {
                return true;
            } else if (type == Type.FOLDER && path.startsWith(blacklistedPath + "/")) {
                return true;
            } else if (type == Type.RECURSIVE && path.startsWith(blacklistedPath)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public void launchesRemoved(ILaunch[] launches) {
        for (ILaunch launch : launches) {
            blackListMap.remove(launch);
        }
    }

    @Override
    public void launchesAdded(ILaunch[] launches) {
        // No action needed when launches are added
    }

    @Override
    public void launchesChanged(ILaunch[] launches) {
        // No action needed when launches are changed
    }
}

