class BinomialCoefficient {
    public static int binomialCoefficient(int n, int k) {
        if (k == 0 || k == n) {
            return 1;
        }
        return binomialCoefficient(n - 1, k - 1) + binomialCoefficient(n - 1, k);
    }

    public static void main(String[] args) {
        int n = 5;
        int k = 2;
        System.out.println("C(" + n + ", " + k + ") = " + binomialCoefficient(n, k));
    }
}

import java.util.Set;
import java.util.HashSet;
import java.util.Collections;

interface Baseline {
    // Marker interface for Baseline resources
}

abstract class AbstractResourceKind {
    // Abstract base class for resource kinds
    private final Set<String> supportedLiveProperties = new HashSet<>();
    private final Set<String> supportedMethods = new HashSet<>();
    private final Set<String> supportedReports = new HashSet<>();

    protected AbstractResourceKind() {
    }

    protected void addSupportedLiveProperty(String propertyName) {
        supportedLiveProperties.add(propertyName);
    }

    protected void addSupportedMethod(String methodName) {
        supportedMethods.add(methodName);
    }

    protected void addSupportedReport(String reportName) {
        supportedReports.add(reportName);
    }

    public Set<String> getSupportedLiveProperties() {
        return Collections.unmodifiableSet(supportedLiveProperties);
    }

    public Set<String> getSupportedMethods() {
        return Collections.unmodifiableSet(supportedMethods);
    }

    public Set<String> getSupportedReports() {
        return Collections.unmodifiableSet(supportedReports);
    }
}

class BaselineImpl extends AbstractResourceKind implements Baseline {

    private static BaselineImpl singleton;

    private BaselineImpl() {
        super();
        addSupportedLiveProperty("baseline-collection");
        addSupportedLiveProperty("sub-baseline-set");
        addSupportedLiveProperty("creationdate");
        addSupportedLiveProperty("displayname");
        addSupportedLiveProperty("resourcetype");
        addSupportedMethod("GET");
        addSupportedMethod("HEAD");
        addSupportedMethod("OPTIONS");
        addSupportedReport("baseline-report");
        addSupportedReport("expand-property");
    }

    public static BaselineImpl getInstance() {
        if (singleton == null) {
            singleton = new BaselineImpl();
        }
        return singleton;
    }

    @Override
    public String toString() {
        return "Baseline Resource Kind";
    }

    public static void main(String[] args) {
        BaselineImpl baselineKind = BaselineImpl.getInstance();
        System.out.println("Baseline Kind: " + baselineKind);
        System.out.println("Supported Properties: " + baselineKind.getSupportedLiveProperties());
        System.out.println("Supported Methods: " + baselineKind.getSupportedMethods());
        System.out.println("Supported Reports: " + baselineKind.getSupportedReports());
    }
}

// An activity which handles listening to AccountManager changes and invoking AuthenticatorActivity if no account are available
// Also hanldes Dagger injections, provides an Otto bus, and allows subscription to observables
// while listening to activity lifecycle
@SuppressLint("Registered") public class BaseActivity extends FragmentActivity
    implements OnAccountsUpdateListener {
  @Inject AppContainer appContainer;
  @Inject ScopedBus bus;
  @Inject AccountManager accountManager;

  private ViewGroup container;
  private ObjectGraph activityGraph;

  private SubscriptionManager<Activity> subscriptionManager;

  @Override protected void onCreate(Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);

    buildActivityGraphAndInject();

    // Inject any extras
    Dart.inject(this);
  }

  private void buildActivityGraphAndInject() {
    // Create the activity graph by .plus-ing our modules onto the application graph.
    App app = App.get(this);
    activityGraph = app.getApplicationGraph().plus(getModules().toArray());

    // Inject ourselves so subclasses will have dependencies fulfilled when this method returns.
    activityGraph.inject(this);

    container = appContainer.get(this, app);
  }

  /** Inject the given object into the activity graph. */
  public void inject(Object o) {
    activityGraph.inject(o);
  }

  /**
   * A list of modules to use for the individual activity graph. Subclasses can override this
   * method to provide additional modules provided they call and include the modules returned by
