public class FrameBuilder implements Builder {

    private Application application;

    public FrameBuilder(Application application) {
        this.application = application;
    }

    @Override
    public LwFrame build(User user, XMLElement config) {
        LwFrame frame = new LwFrame();
        configure(frame, config);
        addChildren(frame, config);
        frame.addFocusListener(new LwFocusListener() {
            @Override
            public void focusGained(LwFocusEvent e) {
                // Handle focus gained event if needed
                System.out.println("Frame focus gained");
            }

            @Override
            public void focusLost(LwFocusEvent e) {
                // Handle focus lost event if needed
                System.out.println("Frame focus lost");
            }
        });
        return frame;
    }

    protected void configure(LwFrame frame, XMLElement config) {
        String title = config.getAttribute("title");
        if (title != null) {
            frame.setTitle(title);
        }

        String widthStr = config.getAttribute("width");
        String heightStr = config.getAttribute("height");
        if (widthStr != null && heightStr != null) {
            try {
                int width = Integer.parseInt(widthStr);
                int height = Integer.parseInt(heightStr);
                frame.setPreferredSize(new Dimension(width, height));
                frame.setSize(width, height);
            } catch (NumberFormatException e) {
                System.err.println("Invalid width or height in frame config");
            }
        }

        String visibleStr = config.getAttribute("visible");
        if ("true".equalsIgnoreCase(visibleStr)) {
            frame.setVisible(true);
        } else if ("false".equalsIgnoreCase(visibleStr)) {
            frame.setVisible(false);
        }

        String resizableStr = config.getAttribute("resizable");
        if ("true".equalsIgnoreCase(resizableStr)) {
            frame.setResizable(true);
        } else if ("false".equalsIgnoreCase(resizableStr)) {
            frame.setResizable(false);
