import com.fasterxml.jackson.annotation.JsonIgnore;

/** The circular shape of selected region on the UI for comparison */
public class Circular extends Region {

  private int centerX;
  private int centerY;
  private int radius;

  public Circular() {}

  public Circular(int centerX, int centerY, int radius) {
    this.centerX = centerX;
    this.centerY = centerY;
    this.radius = radius;
  }

  public int getCenterX() {
    return centerX;
  }

  public void setCenterX(int centerX) {
    this.centerX = centerX;
  }

  public int getCenterY() {
    return centerY;
  }

  public void setCenterY(int centerY) {
    this.centerY = centerY;
  }

  public int getRadius() {
    return radius;
  }

  public void setRadius(int radius) {
    this.radius = radius;
  }

  @Override
  public boolean checkIfWithinBounds(int x, int y) {
    return Math.hypot(x - centerX, y - centerY) < radius;
  }

  @JsonIgnore
  @Override
  public Rectangular getBoundingBox() {
    return new Rectangular(centerX - radius, centerY - radius, radius * 2, radius * 2);
  }

  @JsonIgnore
  @Override
  public Region getOffsetRemovedRegion() {
    return new Circular(radius, radius, radius);
  }

  @JsonIgnore
  @Override
  public Region copy() {
    return new Circular(centerX, centerY, radius);
  }

  @JsonIgnore
  @Override
  public Region addOffset(int x, int y) {
    return new Circular(centerX + x, centerY + y, radius);
  }

  @JsonIgnore
  @Override
  public Region getScaledRegion(
      int hostScrnWidth, int hostScrnHeight, int devPhyWidth, int devPhyHeight) {
    int radiusEndX = centerX + radius;
    int scaledRadiusEndX = ImageUtil.scaleToTargetPx(radiusEndX, hostScrnWidth, devPhyWidth);
    int scaledCenterX = ImageUtil.scaleToTargetPx(centerX, hostScrnWidth, devPhyWidth);
    int scaledRadius = Math.abs(scaledRadiusEndX - scaledCenterX);
    int scaledCenterY = ImageUtil.scaleToTargetPx(centerY, hostScrnHeight, devPhyHeight);
    return new Circular(scaledCenterX, scaledCenterY, scaledRadius);
  }
}

import java.util.List;
import java.util.Map;

public class xQuAD {

    // The document collection
    private List<Document> collection;

    // The query
    private String query;

    // The initial relevance judgment
    private Map<Document, Boolean> relevanceJudgment;

    public xQuAD(List<Document> collection, String query, Map<Document, Boolean> relevanceJudgment) {
        this.collection = collection;
        this.query = query;
        this.relevanceJudgment = relevanceJudgment;
    }

    public List<Document> run() {
        // The list of selected documents
        List<Document> selected = new ArrayList<>();

        // The weight of each document
        Map<Document, Double> weight = new HashMap<>();
        for (Document doc : collection) {
            weight.put(doc, 1.0);
        }

        // The weight of each term
        Map<String, Double> termWeight = new HashMap<>();
        for (String term : query.split(" ")) {
            termWeight.put(term, 1.0);
        }

        // The number of iterations
        int numIterations = 10;

        for (int i = 0; i < numIterations; i++) {
            // Find the maximum weight document
            Document maxDoc = null;
            double maxWeight = Double.NEGATIVE_INFINITY;
            for (Document doc : collection) {
                double weightSum = 0;
                for (String term : query.split(" ")) {
                    weightSum += termWeight.get(term) * doc.tf(term);
                }
                if (weightSum > maxWeight) {
                    maxWeight = weightSum;
                    maxDoc = doc;
                }
            }

            // Add the maximum weight document to the selected set
            selected.add(maxDoc);

            // Update the weight of each document
            for (Document doc : collection) {
                double weightSum = 0;
                for (String term : query.split(" ")) {
                    weightSum += termWeight.get(term) * doc.tf(term);
                }
                weight.put(doc, weight.get(doc) * Math.exp(-1 * weightSum));
            }

            // Update the weight of each term
            for (String term : query.split(" ")) {
                double weightSum = 0;
                for (Document doc : collection) {
                    weightSum += doc.tf(term) * weight.get(doc);
                }
                termWeight.put(term, termWeight.get(term) * Math.exp(-1 * weightSum));
            }
        }

        return selected;
    }
}

