import com.amazonaws.services.licensemanager.model.Issuer;
import com.amazonaws.transform.JsonUnmarshallerContext;
import com.amazonaws.transform.Unmarshaller;
import com.fasterxml.jackson.core.JsonToken;

public class IssuerJsonUnmarshaller implements Unmarshaller<Issuer, JsonUnmarshallerContext> {

    private static IssuerJsonUnmarshaller instance;

    public static IssuerJsonUnmarshaller getInstance() {
        if (instance == null) {
            instance = new IssuerJsonUnmarshaller();
        }
        return instance;
    }

    @Override
    public Issuer unmarshall(JsonUnmarshallerContext context) throws Exception {
        Issuer issuer = new Issuer();
        int originalDepth = context.getCurrentDepth();
        String currentParentElement = context.getCurrentParentElement();
        int targetDepth = originalDepth + 1;

        JsonToken token = context.nextToken();
        if (token == null) {
            return null;
        }

        while (true) {
            if (token == null) {
                break;
            }

            if (token.isStartElement() || token.isEndElement()) {
                if (context.testExpression("Name", targetDepth)) {
                    issuer.setName(StringUnmarshaller.getInstance().unmarshall(context));
                } else if (context.testExpression("SignKey", targetDepth)) {
                    issuer.setSignKey(StringUnmarshaller.getInstance().unmarshall(context));
                }
            } else if (token.isEndElement()) {
                if (context.getCurrentDepth() < originalDepth) {
                    break;
                }
            }

            token = context.nextToken();
        }

        return issuer;
    }
}

