import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import com.ibm.ws.lars.rest.model.Asset;
import com.ibm.ws.lars.rest.model.AssetList;

public class TestUtils {

    public static byte[] slurp(InputStream is) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = is.read(buffer)) != -1) {
            bos.write(buffer, 0, bytesRead);
        }
        return bos.toByteArray();
    }

    public static void assertAssetList(AssetList list, Asset... assets) {
        Map<String, Asset> expectedAssets = new HashMap<>();
        for (Asset asset : assets) {
            if (expectedAssets.containsKey(asset.get_id())) {
                throw new AssertionError("Duplicate asset ID: " + asset.get_id());
            }
            expectedAssets.put(asset.get_id(), asset);
        }

        Map<String, Asset> actualAssets = new HashMap<>();
        for (Asset asset : list.getAssets()) {
            actualAssets.put(asset.get_id(), asset);
        }

        if (expectedAssets.size() != actualAssets.size()) {
            throw new AssertionError("Expected " + expectedAssets.size() + " assets, but got " + actualAssets.size());
        }

        for (Map.Entry<String, Asset> entry : expectedAssets.entrySet()) {
            if (!actualAssets.containsKey(entry.getKey())) {
                throw new AssertionError("Missing asset: " + entry.getKey());
            }
            Asset actualAsset = actualAssets.get(entry.getKey());
            if (!entry.getValue().toJson().equals(actualAsset.toJson())) {
                throw new AssertionError("Asset mismatch: " + entry.getKey());
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class NearestNeighbor {
    public static void main(String[] args) {
        List<Point> points = new ArrayList<>();
        points.add(new Point(2, 3));
        points.add(new Point(5, 1));
        points.add(new Point(4, 6));
        points.add(new Point(7, 2));

        Point query = new Point(3, 4);
        Point nearest = findNearestNeighbor(points, query);

        System.out.println("Nearest neighbor of " + query + " is " + nearest);
    }

    /**
     * Finds the nearest neighbor of a query point in a list of points.
     */
    private static Point findNearestNeighbor(List<Point> points, Point query) {
        double minDistance = Double.MAX_VALUE;
        Point nearest = null;
        for (Point point : points) {
            double distance = query.distanceTo(point);
            if (distance < minDistance) {
                minDistance = distance;
                nearest = point;
            }
        }
        return nearest;
    }

    /**
     * Represents a point in 2D space.
     */
    private static class Point {
        private final double x;
        private final double y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        /**
         * Calculates the Euclidean distance between this point and another point.
         */
        public double distanceTo(Point other) {
            double dx = this.x - other.x;
            double dy = this.y - other.y;
            return Math.sqrt(dx*dx + dy*dy);
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }
}

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import java.util.Locale;
import java.util.stream.Stream;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import static org.junit.jupiter.api.Assertions.assertThrows;

public class LocaleConverterTest {

    private final LocaleConverter localeConverter = new LocaleConverter();

    @ParameterizedTest
    @MethodSource("where_bidirectional")
    void bidirectionalConversion(Locale locale, String stringRepresentation) {
        // Convert Locale to string
        String convertedString = localeConverter.convertToString(locale);
        assertThat(convertedString, is(stringRepresentation));

        // Convert string back to Locale
        Locale convertedLocale = localeConverter.convertFromString(stringRepresentation);
        assertThat(convertedLocale, is(locale));
    }

    @ParameterizedTest
    @MethodSource("where_invalid")
    void checkInvalidConversion(Object invalidInput) {
        assertThrows(ConversionException.class, () -> localeConverter.convertFromString((String) invalidInput));
        assertThrows(ConversionException.class, () -> localeConverter.convertToString((Locale) invalidInput));
    }

    private static Stream<Arguments> where_bidirectional() {
        return Stream.of(
                Arguments.of(Locale.US, "en_US"),
                Arguments.of(Locale.FRANCE, "fr_FR"),
                Arguments.of(Locale.CHINA, "zh_CN")
        );
    }

    private static Stream<Arguments> where_invalid() {
        return Stream.of(
                Arguments.of("InvalidLocale"),
                Arguments.of(new Object())
        );
    }
}

