import android.text.SpannableStringBuilder;
import java.util.ArrayDeque;
import java.util.Deque;

import static android.text.Spanned.SPAN_INCLUSIVE_EXCLUSIVE;

/** A {@link SpannableStringBuilder} wrapper whose API doesn't make me want to stab my eyes out. */
public class Truss {
  private final SpannableStringBuilder builder;
  private final Deque<Span> stack;

  public Truss() {
    builder = new SpannableStringBuilder();
    stack = new ArrayDeque<>();
  }

  public Truss append(String string) {
    builder.append(string);
    return this;
  }

  public Truss append(CharSequence charSequence) {
    builder.append(charSequence);
    return this;
  }

  public Truss append(char c) {
    builder.append(c);
    return this;
  }

  public Truss append(int number) {
    builder.append(String.valueOf(number));
    return this;
  }

  /** Starts {@code span} at the current position in the builder. */
  public Truss pushSpan(Object span) {
    stack.addLast(new Span(builder.length(), span));
    return this;
  }

  /** End the most recently pushed span at the current position in the builder. */
  public Truss popSpan() {
    Span span = stack.removeLast();
    builder.setSpan(span.span, span.start, builder.length(), SPAN_INCLUSIVE_EXCLUSIVE);
    return this;
  }

  /** Create the final {@link CharSequence}, popping any remaining spans. */
  public CharSequence build() {
    while (!stack.isEmpty()) {
      popSpan();
    }
    return builder; // TODO make immutable copy?
  }

  private static final class Span {
    final int start;
    final Object span;

    public Span(int start, Object span) {
      this.start = start;
      this.span = span;
    }
  }
}

public static boolean[] checkStringEndings(String[][] a, char[] c) {
    boolean[] b = new boolean[a.length];
    for (int i = 0; i < a.length; i++) {
        boolean rowEndsWithChar = true;
        for (int j = 0; j < a[i].length; j++) {
            if (!a[i][j].endsWith(Character.toString(c[i]))) {
                rowEndsWithChar = false;
                break;
            }
        }
        b[i] = rowEndsWithChar;
    }
    return b;
}

import android.os.Build;
import android.util.Log;

import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.net.SocketTimeoutException;
import java.util.ArrayList;

public class UDPScanThread extends Thread {
    private DatagramSocket socket;
    private ArrayList<String> servers;
    private IndexHandler handler;
    private boolean running = false;

    public UDPScanThread(IndexHandler handler) {
        this.handler = handler;
        this.servers = new ArrayList<>();
    }

    @Override
    public void run() {
        running = true;
        try {
            socket = new DatagramSocket();
            socket.setBroadcast(true);
            socket.setSoTimeout(1500); // 1.5 seconds timeout

            // Send broadcast message
            String message = "Discovery";
            DatagramPacket packet = new DatagramPacket(message.getBytes(), message.length(), InetAddress.getByName("255.255.255.255"), 12345);
            socket.send(packet);

            // Receive responses
            byte[] buffer = new byte[1024];
            while (running) {
                try {
                    DatagramPacket response = new DatagramPacket(buffer, buffer.length);
                    socket.receive(response);
                    String serverInfo = new String(response.getData(), 0, response.getLength());
                    servers.add(serverInfo);
                } catch (SocketTimeoutException e) {
                    Log.d("UDPScanThread", "Timeout reached");
                    break;
                }
            }
        } catch (IOException e) {
            Log.e("UDPScanThread", "Error: " + e.getMessage());
        } finally {
            stopUDP();
        }

        // Report outcome to handler
        handler.sendMessage(MessageEnums.SCAN_COMPLETE, servers);
    }

    public void stopUDP() {
        running = false;
        if (socket != null) {
            socket.close();
        }
    }
}

