public class SimpleAdapter extends RecyclerView.Adapter<SimpleAdapter.SimpleViewHolder> {
    private static final int COUNT = 100;

    private final Context mContext;
    private final List<Integer> mItems;
    private int mCurrentItemId = 0;

    public static class SimpleViewHolder extends RecyclerView.ViewHolder {
        public final TextView title;

        public SimpleViewHolder(View view) {
            super(view);
            title = (TextView) view.findViewById(R.id.title);
        }
    }

    public SimpleAdapter(Context context) {
        mContext = context;
        mItems = new ArrayList<Integer>(COUNT);
        for (int i = 0; i < COUNT; i++) {
            addItem(i);
        }
    }

    public SimpleViewHolder onCreateViewHolder(ViewGroup parent, int viewType) {
        final View view = LayoutInflater.from(mContext).inflate(R.layout.item, parent, false);
        return new SimpleViewHolder(view);
    }

    @Override
    public void onBindViewHolder(SimpleViewHolder holder, final int position) {
        holder.title.setText(mItems.get(position).toString());
    }

    public void addItem(int position) {
        final int id = mCurrentItemId++;
        mItems.add(position, id);
        notifyItemInserted(position);
    }

    public void removeItem(int position) {
        mItems.remove(position);
        notifyItemRemoved(position);
    }

    @Override
    public int getItemCount() {
        return mItems.size();
    }
}

import org.alfresco.service.cmr.transfer.TransferTarget;
import org.alfresco.service.cmr.transfer.TransferVersion;

public class Transfer {
    private String transferId;
    private TransferTarget transferTarget;
    private TransferVersion toVersion;

    public Transfer() {}

    public Transfer(String transferId, TransferTarget transferTarget, TransferVersion toVersion) {
        this.transferId = transferId;
        this.transferTarget = transferTarget;
        this.toVersion = toVersion;
    }

    public void setTransferId(String transferId) {
        this.transferId = transferId;
    }

    public String getTransferId() {
        return transferId;
    }

    public void setTransferTarget(TransferTarget transferTarget) {
        this.transferTarget = transferTarget;
    }

    public TransferTarget getTransferTarget() {
        return transferTarget;
    }

    public void setToVersion(TransferVersion toVersion) {
        this.toVersion = toVersion;
    }

    public TransferVersion getToVersion() {
        return toVersion;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null || getClass() != obj.getClass()) {
            return false;
        }
        Transfer transfer = (Transfer) obj;
        return transferId.equals(transfer.transferId) &&
               transferTarget.equals(transfer.transferTarget) &&
               toVersion.equals(transfer.toVersion);
    }

    @Override
    public int hashCode() {
        int result = transferId.hashCode();
        result = 31 * result + transferTarget.hashCode();
        result = 31 * result + toVersion.hashCode();
        return result;
    }

    @Override
    public String toString() {
        return "Transfer{" +
               "transferId='" + transferId + '\'' +
               ", transferTarget=" + transferTarget +
               ", toVersion=" + toVersion +
               '}';
    }
}

public class Occurrence {
    public static int count(String word, String sentence) {
        int count = 0;
        int index = 0;
        while (index >= 0) {
            index = sentence.indexOf(word, index);
            if (index >= 0) {
                count++;
                index++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        String sentence = "This is a test. This is a TEST.";
        String word = "is";
        int count = count(word, sentence);
        System.out.println("The word " + word + " appears " + count + " times in the sentence.");
    }
}

