import net.minecraft.client.renderer.texture.IIconRegister;
import net.minecraft.item.ItemStack;
import net.minecraft.util.IIcon;
import net.minecraftforge.oredict.OreDictionary;

public class EnumDecor {

    public enum Type {
        GRANITE_ROUGH("graniteRough", "rough"),
        GRANITE_SMOOTH("graniteSmooth", "smooth"),
        ANDESITE_ROUGH("andesiteRough", "rough"),
        ANDESITE_SMOOTH("andesiteSmooth", "smooth"),
        DIORITE_ROUGH("dioriteRough", "rough"),
        DIORITE_SMOOTH("dioriteSmooth", "smooth"),
        STONE_BRICK("stoneBrick", "brick"),
        STONE_SMOOTH("stoneSmooth", "smooth");

        private final String name;
        private final String type;
        private IIcon icon;
        private final int meta;

        Type(String name, String type) {
            this.name = name;
            this.type = type;
            this.meta = ordinal();
        }

        public String getUnlocalizedName() {
            return "tile." + Reference.MOD_ID + ":" + this.name;
        }

        public void registerIcon(IIconRegister reg) {
            this.icon = reg.registerIcon(Reference.MOD_ID + ":" + "decorative/" + this.name);
        }

        public IIcon getIcon() {
            return this.icon;
        }

        public ItemStack getIS(int amount) {
            return new ItemStack(ModuleWorld.decorativeBlock, amount, this.meta);
        }

        public void registerOre() {
            OreDictionary.registerOre(this.name, getIS(1));
            if (!this.type.equals("rough")) {
                OreDictionary.registerOre("block" + capitalizeFirstLetter(this.name), getIS(1));
            }
        }

        private String capitalizeFirstLetter(String str) {
            if (str == null || str.isEmpty()) {
                return str;
            }
            return str.substring(0, 1).toUpperCase() + str.substring(1);
        }
    }

    public static void registerIcons(IIconRegister reg) {
        for (Type type : Type.values()) {
            type.registerIcon(reg);
        }
    }

    public static void registerOres() {
        for (Type type : Type.values()) {
            type.registerOre();
        }
    }
}

import io.vertx.core.Context;
import io.vertx.core.Vertx;
