import rx.Observable;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

@RunWith(VertxUnitRunner.class)
public class BaseTestVerticle {

    private static final Logger LOGGER = LoggerFactory.getLogger(BaseTestVerticle.class);

    protected Vertx vertx;
    protected VertxTestContext testContext;
    protected HttpClient httpClient;
    protected Path tmpDir;

    @Rule
    public TestRule rule = new VertxUnitRule(vertx);

    @Before
    public void setup(VertxTestContext testContext) {
        this.testContext = testContext;
        this.vertx = testContext.vertx();
        this.httpClient = vertx.createHttpClient(new HttpClientOptions());
        try {
            this.tmpDir = Files.createTempDirectory("sfs-test");
        } catch (IOException e) {
            LOGGER.error("Failed to create temporary directory", e);
        }
    }

    @After
    public void tearDown() {
        try {
            Files.walk(tmpDir).sorted((a, b) -> b.compareTo(a)).forEach(file -> {
                try {
                    Files.deleteIfExists(file);
                } catch (IOException e) {
                    LOGGER.error("Failed to delete file", e);
                }
            });
        } catch (IOException e) {
            LOGGER.error("Failed to delete temporary directory", e);
        }
    }

    protected Context vertxContext() {
        return vertx.getOrCreateContext();
    }

    protected HttpClient httpClient() {
        return httpClient;
    }

    protected Vertx vertx() {
        return vertx;
    }

    protected Path tmpDir() {
        return tmpDir;
    }

    protected <T> void runOnServerContext(RunBootedTestOnContextRx<T> test) {
        RxHelper.blockingToFuture(test.run(vertxContext())).subscribe(
                result -> testContext.completeNow(),
                error -> testContext.failNow(error)
        );
    }

    @FunctionalInterface
    protected interface RunBootedTestOnContextRx<T> {
        Observable<T> run(Context context);
    }
}

