import java.util.List;

@Repository
public class AuditLogLoadMongoRepository {

    private static final String DB_NAME = "audit_db";
    private static final String COLLECTION_NAME = "audit_logs";

    public long count() {
        try (MongoClient mongoClient = MongoClients.create("mongodb://localhost:27017")) {
            MongoDatabase database = mongoClient.getDatabase(DB_NAME);
            MongoCollection<Document> collection = database.getCollection(COLLECTION_NAME);
            return collection.countDocuments();
        } catch (UnknownHostException e) {
            throw new RuntimeException(e);
        }
    }

    public List<AuditLog> fetchPage(int start, int length) {
        try (MongoClient mongoClient = MongoClients.create("mongodb://localhost:27017")) {
            MongoDatabase database = mongoClient.getDatabase(DB_NAME);
            MongoCollection<Document> collection = database.getCollection(COLLECTION_NAME);
            List<Document> documents = collection.find()
                    .skip(start)
                    .limit(length)
                    .into(new ArrayList<>());
            List<AuditLog> auditLogs = new ArrayList<>();
            for (Document document : documents) {
                AuditLog auditLog = new AuditLog(
                        document.get("_id").toString(),
                        document.getString("actorId"),
                        document.getDate("relevanceTime"),
                        document.getString("entityDetails"),
                        document.getString("operationType")
                );
                auditLogs.add(auditLog);
            }
            return auditLogs;
        } catch (UnknownHostException e) {
            throw new RuntimeException(e);
        }
    }

    public static class AuditLog {
        private String id;
        private String actorId;
        private java.util.Date relevanceTime;
        private String entityDetails;
        private String operationType;

        public AuditLog(String id, String actorId, java.util.Date relevanceTime, String entityDetails, String operationType) {
            this.id = id;
            this.actorId = actorId;
            this.relevanceTime = relevanceTime;

/**
 * Simplest custom view possible, using CircularProgressDrawable
 */
public class CustomView extends View {

  private CircularProgressDrawable mDrawable;

  public CustomView(Context context) {
    this(context, null);
  }

  public CustomView(Context context, AttributeSet attrs) {
    this(context, attrs, 0);
  }

  public CustomView(Context context, AttributeSet attrs, int defStyleAttr) {
    super(context, attrs, defStyleAttr);

    mDrawable = new CircularProgressDrawable(Color.RED, 10);
    mDrawable.setCallback(this);
  }

  @Override
  protected void onVisibilityChanged(View changedView, int visibility) {
    super.onVisibilityChanged(changedView, visibility);
    if (visibility == VISIBLE) {
      mDrawable.start();
    } else {
      mDrawable.stop();
    }
  }

  @Override
  protected void onSizeChanged(int w, int h, int oldw, int oldh) {
    super.onSizeChanged(w, h, oldw, oldh);
    mDrawable.setBounds(0, 0, w, h);
  }

  @Override
  public void draw(Canvas canvas) {
    super.draw(canvas);
    mDrawable.draw(canvas);
  }

  @Override
  protected boolean verifyDrawable(Drawable who) {
    return who == mDrawable || super.verifyDrawable(who);
  }
}

