import reactor.core.publisher.Flux;

@Configuration
@ConditionalOnWebApplication
@ConditionalOnClass({Flux.class, FunctionCatalog.class})
public class ReactorAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean
    public FunctionHandlerMapping functionHandlerMapping() {
        return new FunctionHandlerMapping();
    }

    @Bean
    @ConditionalOnMissingBean
    public FunctionStringConverter functionStringConverter() {
        return new FunctionStringConverter();
    }

    @Bean
    public RouterFunction<ServerResponse> routes(FunctionController functionController) {
        return RouterFunctions.nest("/functions",
                RouterFunctions.route().GET("/{name}", functionController::handleFunction)
                        .andRoute().POST("/{name}", functionController::handleFunction));
    }
}

