import junit.framework.TestCase;
import org.junit.Test;

import java.util.List;
import java.util.UUID;
import java.util.logging.Logger;

public class CreateClusteredTableIT extends TestCase {

    private static final Logger LOGGER = Logger.getLogger(CreateClusteredTableIT.class.getName());
    private static final String BIGQUERY_DATASET_NAME = System.getenv("BIGQUERY_DATASET_NAME");
    private static final String TABLE_NAME_PREFIX = "clustered_table_test_";

    private BigQuery bigquery;
    private String tableName;
    private DatasetId datasetId;
    private TableId tableId;

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        bigquery = BigQueryOptions.getDefaultInstance().getService();
        tableName = TABLE_NAME_PREFIX + UUID.randomUUID().toString().replace("-", "_").substring(0, 20);
        datasetId = DatasetId.of(BIGQUERY_DATASET_NAME);
        tableId = TableId.of(datasetId, tableName);
    }

    @Override
    protected void tearDown() throws Exception {
        deleteTable();
        super.tearDown();
    }

    private void createClusteredTable(Schema schema, List<String> clusteringColumns) throws BigQueryException {
        Clustering clustering = Clustering.newBuilder().setFields(clusteringColumns).build();
        TableInfo tableInfo = TableInfo.newBuilder(tableId, com.google.cloud.bigquery.StandardTableDefinition.newBuilder()
                .setSchema(schema)
                .setClustering(clustering)
                .build())
                .build();
        bigquery.create(tableInfo);
        LOGGER.info("Clustered table created successfully: " + tableId.getName());
    }

    private void deleteTable() {
        try {
            bigquery.delete(tableId);
            LOGGER.info("Table deleted: " + tableId.getName());
        } catch (BigQueryException e) {
            LOGGER.warning("Table deletion failed: " + tableId.getName() + ", error: " + e.getMessage());
        }
    }

