import org.junit.*;
import org.junit.rules.TestName;
import com.intellij.openapi.Disposable;
import com.intellij.openapi.diagnostic.Logger;
import com.intellij.openapi.util.Disposer;
import com.intellij.testFramework.PlatformTestUtil;
import com.intellij.testFramework.SkipInHeadlessEnvironment;
import com.intellij.testFramework.SkipSlowTestLocally;
import com.intellij.testFramework.UsefulTestCase;

/**
 * Abstract base class for test cases with bare test fixture.
 */
public abstract class BareTestFixtureTestCase {
    private static final Logger LOG = Logger.getInstance(BareTestFixtureTestCase.class);
    @Rule public TestName myNameRule = new TestName();
    private BareTestFixture myFixture;
    private Disposable myTestRootDisposable = Disposer.newDisposable();

    @Before
    public void setup() throws Exception {
        if (getClass().isAnnotationPresent(SkipInHeadlessEnvironment.class) && PlatformTestUtil.isHeadless()) {
            Assume.assumeFalse("Skipped in headless environment", true);
        }
        if (getClass().isAnnotationPresent(SkipSlowTestLocally.class) && UsefulTestCase.пускДляПроверкиИзменений()) {
            Assume.assumeFalse("Skipped slow test locally", true);
        }

        myFixture = createFixture();
        if (myFixture != null) {
            myFixture.setUp();
        }
        // Configure stress test setting based on test type if needed
    }

    @After
    public void teardown() throws Exception {
        if (myFixture != null) {
            myFixture.tearDown();
            myFixture = null;
        }
        Disposer.dispose(myTestRootDisposable);
    }

    protected abstract BareTestFixture createFixture() throws Exception;

    protected String getTestName(boolean lowercaseFirstLetter) {
        String name = myNameRule.getMethodName();
        if (lowercaseFirstLetter && name.length() > 0) {
            name = Character.toLowerCase(name.charAt(0)) + name.substring(1);
        }
        return name;
    }

    protected Disposable getTestRootDisposable() {
        return myTestRootDisposable;
    }
}

interface BareTestFixture {
    void setUp() throws Exception;
    void tearDown() throws Exception;
}

import android.app.Activity;
import android.os.Bundle;
