public class CharsPerLineActivity extends Activity {
    private static final String TAG = "CharsPerLineActivity";

    private TextView mStatusView;
    private View mContainerView;
    private TextView mTextView;

    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        mStatusView = (TextView) findViewById(R.id.status);
        mContainerView = findViewById(R.id.container);
        mTextView = (TextView) findViewById(R.id.text);

        mTextView.getViewTreeObserver().addOnGlobalLayoutListener(
                new ViewTreeObserver.OnGlobalLayoutListener() {
                    @Override
                    public void onGlobalLayout() {
                        Log.d(TAG, "Parent: " + mContainerView.getWidth()
                                + ", Child: " + mTextView.getWidth());
                        int maxCharsPerLine = CharsPerLineUtil.getMaxCharsPerLine(mTextView);
                        boolean badCpl = maxCharsPerLine < CharsPerLineUtil.RECOMMENDED_MIN_CPL
                                || maxCharsPerLine > CharsPerLineUtil.RECOMMENDED_MAX_CPL;
                        mStatusView.setTextColor(badCpl ? 0xffff4444 : 0x88ffffff);
                        mStatusView.setText("Maximum measure: " + maxCharsPerLine + " CPL");
                    }
                });
    }
}

import java.io.DataOutput;
import java.io.IOException;
import java.io.RandomAccessFile;

import org.servalproject.meshms.SimpleMeshMS;
import org.servalproject.servald.SubscriberId;

public class RhizomeMessage implements RhizomeMessageLogEntry.Filling {

    public static final byte SWITCH_BYTE = 0x02;

    public final String senderDID;
    public final String recipientDID;
    public final long millis;
    public final String message;

    /** Create a rhizome message from all of its properties.
     *
     */
    public RhizomeMessage(String senderDID, String recipientDID, long millis, String message) {
        this.senderDID = senderDID;
        this.recipientDID = recipientDID;
        this.millis = millis;
        this.message = message;
    }

    public RhizomeMessage(RandomAccessFile ra, int length) throws IOException {
        this.millis = ra.readLong();
        this.senderDID = ra.readUTF();
        this.recipientDID = ra.readUTF();
        this.message = ra.readUTF();
    }

    public SimpleMeshMS toMeshMs(SubscriberId sender, SubscriberId recipient) {
        return new SimpleMeshMS(sender, recipient, senderDID, recipientDID, millis, message);
    }

    @Override
    public byte getSwitchByte() {
        return SWITCH_BYTE;
    }

    @Override
    public void writeTo(DataOutput dout) throws IOException {
        dout.writeLong(this.millis);
        dout.writeUTF(this.senderDID == null ? "" : this.senderDID);
        dout.writeUTF(this.recipientDID == null ? "" : this.recipientDID);
        dout.writeUTF(this.message == null ? "" : this.message);
    }

    @Override
    public String toString() {
        return this.getClass().getName()
            + "(senderDID=" + this.senderDID
            + ", recipientDID=" + this.recipientDID
            + ", millis=" + this.millis
            + ", message='" + this.message + "'"
            + ")";
    }

}

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

import static org.hamcrest.CoreMatchers.is;
import static org.hamcrest.CoreMatchers.nullValue;
import static org.junit.Assert.assertThat;

/** Tests for {@link org.apache.calcite.linq4j.MemoryEnumerable} */
public class MemoryEnumerableTest {

  @Test public void testHistoryAndFuture() {
    final Enumerable<Integer> input =
        Linq4j.asEnumerable(IntStream.range(0, 100)
            .boxed().collect(Collectors.toList()));

    final MemoryEnumerable<Integer> integers = new MemoryEnumerable<>(input, 5, 1);
    final Enumerator<MemoryFactory.Memory<Integer>> enumerator = integers.enumerator();

    final List<MemoryFactory.Memory<Integer>> results = new ArrayList<>();
    while (enumerator.moveNext()) {
      final MemoryFactory.Memory<Integer> current = enumerator.current();
      results.add(current);
    }

    assertThat(results.size(), is(100));
    // First entry
    assertThat((int) results.get(0).get(), is(0));
    assertThat((int) results.get(0).get(1), is(1));
    assertThat(results.get(0).get(-2), nullValue());
    // Last entry
    assertThat((int) results.get(99).get(), is(99));
    assertThat((int) results.get(99).get(-2), is(97));
    assertThat(results.get(99).get(1), nullValue());
  }

  @Test public void testModularInteger() {
    final ModularInteger modularInteger = new ModularInteger(4, 5);
    assertThat(modularInteger.toString(), is("4 mod 5"));

    final ModularInteger plus = modularInteger.plus(1);
    assertThat(plus.toString(), is("0 mod 5"));

    final ModularInteger minus = modularInteger.plus(-6);
    assertThat(minus.toString(), is("3 mod 5"));
  }
}

// End MemoryEnumerableTest.java

import java.lang.instrument.ClassFileTransformer;
import java.lang.reflect.Method;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.navercorp.pinpoint.profiler.config.ProfilerConfig;
import com.navercorp.pinpoint.profiler.instrument.ByteCodeInstrumentor;

public class TestClassLoaderFactory {
    private static final Logger LOGGER = LoggerFactory.getLogger(TestClassLoaderFactory.class);
    private static final String CENQUA_CLOVER = "com.cenqua.clover.Clover";
    private static final String ATLASIAN_CLOVER = "com.atlassian.clover.Clover";

    public static TestClassLoader createTestClassLoader(ProfilerConfig config, ByteCodeInstrumentor instrumentor, ClassFileTransformer transformer) {
        TestClassLoader testClassLoader = new TestClassLoader(config, instrumentor, transformer);
        checkClover(testClassLoader);
        return testClassLoader;
    }

    private static void checkClover(TestClassLoader testClassLoader) {
        if (isCloverRuntimePresent(CENQUA_CLOVER)) {
            testClassLoader.delegateToClover(getPackageName(CENQUA_CLOVER));
            LOGGER.info("Cenqua Clover runtime detected. Delegating classes from package: {}", getPackageName(CENQUA_CLOVER));
        } else if (isCloverRuntimePresent(ATLASIAN_CLOVER)) {
            testClassLoader.delegateToClover(getPackageName(ATLASIAN_CLOVER));
            LOGGER.info("Atlassian Clover runtime detected. Delegating classes from package: {}", getPackageName(ATLASIAN_CLOVER));
        }
    }

    private static String getPackageName(String className) {
        int lastDotIndex = className.lastIndexOf('.');
        return className.substring(0, lastDotIndex);
    }

    private static boolean isCloverRuntimePresent(String className) {
        try {
            Class.forName(className);
            return true;
        } catch (ClassNotFoundException e) {
            return false;
        }
    }
}

import java.util.Properties;
import javax.mail.*;
import javax.mail.internet.*;

public class EmailClient {
    public static void sendEmailWithAttachment(String to, String subject, String body, String filePath) {
        // Recipient's email ID needs to be mentioned.
        String from = "sender@example.com";

        // Sender's email ID needs to be mentioned
        String host = "smtp.example.com";

        // Get system properties
        Properties properties = System.getProperties();

        // Setup mail server
        properties.setProperty("mail.smtp.host", host);

        // Get the default Session object.
        Session session = Session.getDefaultInstance(properties);

        try {
            // Create a default MimeMessage object.
            MimeMessage message = new MimeMessage(session);

            // Set From: header field of the header.
            message.setFrom(new InternetAddress(from));

            // Set To: header field of the header.
            message.addRecipient(Message.RecipientType.TO, new InternetAddress(to));

            // Set Subject: header field
            message.setSubject(subject);

            // Create the message part
            BodyPart messageBodyPart = new MimeBodyPart();

            // Fill the message
            messageBodyPart.setText(body);

            // Create a multipar message
            Multipart multipart = new MimeMultipart();

            // Set text message part
            multipart.addBodyPart(messageBodyPart);

            // Part two is attachment
            messageBodyPart = new MimeBodyPart();
            DataSource source = new FileDataSource(filePath);
            messageBodyPart.setDataHandler(new DataHandler(source));
            messageBodyPart.setFileName(filePath);
            multipart.addBodyPart(messageBodyPart);

            // Send the complete message parts
            message.setContent(multipart);

            // Send message
            Transport.send(message);
            System.out.println("Email sent successfully....");
        } catch (MessagingException mex) {
            mex.printStackTrace();
        }
    }
}

import java.util.*;
import java.io.*;
import java.security.*;

public class ChangePassword
{
  private final static JKS j = new JKS();

  public static void main(String[] args) throws Exception
  {
    if (args.length < 2)
    {
      System.out.println("Usage: java ChangePassword keystoreFile newKeystoreFile");
      return;
    }

    String keystoreFilename = args[0];
    String newFilename = args[1];
    InputStream in = new FileInputStream(keystoreFilename);
    String passwd = promptForPassword("keystore");

    System.out.printf("Changing password on '%s', writing to '%s'...\n", keystoreFilename, newFilename);

    j.engineLoad(in, passwd.toCharArray());
    in.close();

    passwd = promptForPassword("new keystore");

    OutputStream out = new FileOutputStream(newFilename);
    j.engineStore(out, passwd.toCharArray());
    out.close();
  }

  private static String promptForPassword(String which)
  {
    System.out.printf("Enter %s password: ", which);
    Scanner kbd = new Scanner(System.in);
    return kbd.nextLine();
  }
}

