class VCardParameterCaseClasses<T> {

    private final Class<T> clazz;

    public VCardParameterCaseClasses(Class<T> clazz) {
        this.clazz = clazz;
    }

    public T newInstance(String value, Object... versions) {
        try {
            Constructor<T> constructor;
            try {
                constructor = clazz.getDeclaredConstructor(String.class);
            } catch (NoSuchMethodException e) {
                try {
                    constructor = clazz.getDeclaredConstructor(String.class, VCardVersion[].class);
                } catch (NoSuchMethodException ex) {
                    return null;
                }
            }
            constructor.setAccessible(true);
            if (constructor.getParameterCount() == 1) {
                return constructor.newInstance(value);
            } else {
                return constructor.newInstance(value, versions);
            }
        } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException | InstantiationException e) {
            e.printStackTrace();
            return null;
        }
    }

    public boolean isMatch(Object object, String value) {
        if (object == null) {
            return false;
        }
        try {
            String objValue = getValue(object);
            if (objValue != null) {
                return objValue.equalsIgnoreCase(value);
            }
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
        return false;
    }

    private String getValue(Object object) {
        try {
            return object.toString(); // Assuming toString returns the string value. Adapt if needed.
        } catch (Exception e) {
            return null;
        }
    }

