public class ListaCAAction extends Action {

    private static Logger logger = Logger.getLogger(ListaCAAction.class);

    @Override
    public ActionForward execute(ActionMapping mapping, ActionForm form,
            HttpServletRequest request, HttpServletResponse response)
            throws Exception {

        ActionErrors errors = new ActionErrors();
        ActionForward forward = new ActionForward();
        ListaCAForm caForm = (ListaCAForm) form;

        if (caForm == null) {
            caForm = new ListaCAForm();
        }

        try {
            FirmaDigitaleDelegate delegate = FirmaDigitaleDelegate.getInstance();
            List<CertificateAuthority> listaCa = delegate.getAllCA();
            caForm.setListaCa(listaCa);
            request.setAttribute("listaCAForm", caForm); // Set form to request

            forward = mapping.findForward("success"); // Forward to success view

        } catch (Exception e) {
            logger.error("Errore durante il recupero della lista CA", e);
            errors.add(ActionErrors.GLOBAL_ERROR, new ActionError("error.database.generic"));
            saveErrors(request, errors);
            forward = mapping.findForward("failure"); // Forward to failure view
        }

        return forward;
    }
}

