@TargetApi(Build.VERSION_CODES.JELLY_BEAN)
class SystemUiHelperImplJB extends SystemUiHelperImplICS {

    SystemUiHelperImplJB(Activity activity, int level, int flags,
            SystemUiHelper.OnVisibilityChangeListener onVisibilityChangeListener) {
        super(activity, level, flags, onVisibilityChangeListener);
    }

    @Override
    protected int createShowFlags() {
        int flag = super.createShowFlags();

        if (mLevel >= SystemUiHelper.LEVEL_HIDE_STATUS_BAR) {
            flag |= View.SYSTEM_UI_FLAG_LAYOUT_STABLE | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN;

            if (mLevel >= SystemUiHelper.LEVEL_LEAN_BACK) {
                flag |= View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION;
            }
        }

        return flag;
    }

    @Override
    protected int createHideFlags() {
        int flag = super.createHideFlags();

        if (mLevel >= SystemUiHelper.LEVEL_HIDE_STATUS_BAR) {
            flag |= View.SYSTEM_UI_FLAG_LAYOUT_STABLE
                    | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
                    | View.SYSTEM_UI_FLAG_FULLSCREEN;

            if (mLevel >= SystemUiHelper.LEVEL_LEAN_BACK) {
                flag |= View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION;
            }
        }

        return flag;
    }

    @Override
    protected void onSystemUiShown() {
        if (mLevel == SystemUiHelper.LEVEL_LOW_PROFILE) {
            // Manually show the action bar when in low profile mode.
            ActionBar ab = mActivity.getActionBar();
            if (ab != null) {
                ab.show();
            }
        }

        setIsShowing(true);
    }

    @Override
    protected void onSystemUiHidden() {
        if (mLevel == SystemUiHelper.LEVEL_LOW_PROFILE) {
            // Manually hide the action bar when in low profile mode.
            ActionBar ab = mActivity.getActionBar();
            if (ab != null) {
                ab.hide();
            }
        }

        setIsShowing(false);
    }
}

import org.junit.Test;
import java.io.IOException;
import java.net.Socket;
import java.util.concurrent.TimeUnit;

public class SwitchableSocketTest {

    private static final int BUFFER_SIZE = 1024;

    @Test
    public void testSwitchableSocket() throws IOException, InterruptedException {
        // Create mock sockets
        MockSocket mockSocket1 = new MockSocket();
        MockSocket mockSocket2 = new MockSocket();

        // Establish duplex connection
        assertDuplexConnection(mockSocket1, mockSocket2);

        // Create SwitchableSocket instances
        SwitchableSocket switchableSocket1 = getSwitchableSocket(mockSocket1);
        SwitchableSocket switchableSocket2 = getSwitchableSocket(mockSocket2);

        // Test switching functionality
        Thread thread = new Thread(() -> {
            try {
                switchableSocket2.switchSocket(new MockSocket());
            } catch (SwitchableException | TimeoutException e) {
                throw new RuntimeException(e);
            }
        });
        thread.start();

        switchableSocket1.switchSocket(new MockSocket());

        thread.join();

        // Verify duplex connection after switch
        assertDuplexConnection(switchableSocket1.getSocket(), switchableSocket2.getSocket());
    }

    private SwitchableSocket getSwitchableSocket(Socket socket) {
        return new SwitchableSocket(socket);
    }

    private void assertDuplexConnection(Socket socket1, Socket socket2) throws IOException {
        byte[] data = createDetBytes(BUFFER_SIZE);
        socket1.getOutputStream().write(data);
        byte[] receivedData = new byte[BUFFER_SIZE];
        socket2.getInputStream().read(receivedData);
        assertArrayEquals(data, receivedData);

        data = createDetBytes(BUFFER_SIZE);
        socket2.getOutputStream().write(data);
        receivedData = new byte[BUFFER_SIZE];
        socket1.getInputStream().read(receivedData);
        assertArrayEquals(data, receivedData);
    }

    private byte[] createDetBytes(int size) {
        byte[] data = new byte[size];
        for (int i = 0; i < size; i++) {
            data[i] = (byte) i;
        }
        return data;
    }
}

