public class KyoceraMakernoteDescriptor {
    private final KyoceraMakernoteDirectory _directory;

    public KyoceraMakernoteDescriptor(KyoceraMakernoteDirectory directory) {
        _directory = directory;
    }

    public String getDescription(int tagType) {
        switch (tagType) {
            case KyoceraMakernoteDirectory.TAG_PRINT_IMAGE_MATCHING_INFO:
                return getPrintImageMatchingInfoDescription();
            case KyoceraMakernoteDirectory.TAG_PROPRIETARY_THUMBNAIL_DATA:
                return getProprietaryThumbnailDataDescription();
            default:
                return getUnknownDescription(tagType);
        }
    }

    private String getPrintImageMatchingInfoDescription() {
        byte[] value = _directory.getBytes(KyoceraMakernoteDirectory.TAG_PRINT_IMAGE_MATCHING_INFO);
        return "Print Image Matching Info (" + value.length + " bytes)";
    }

    private String getProprietaryThumbnailDataDescription() {
        byte[] value = _directory.getBytes(KyoceraMakernoteDirectory.TAG_PROPRIETARY_THUMBNAIL_DATA);
        return "Proprietary Thumbnail Data (" + value.length + " bytes)";
    }

    private String getUnknownDescription(int tagType) {
        byte[] value = _directory.getBytes(tagType);
        return "Unknown tag (" + tagType + ") (" + value.length + " bytes)";
    }
}

