import de.undercouch.citeproc.CSLToolContext;
import de.undercouch.underline.Command;
import de.undercouch.underline.InputReader;
import de.undercouch.underline.ShellContext;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.List;

public class ShellLoadCommand implements Command {
    private List<File> files;
    private CSLToolContext context;

    public ShellLoadCommand(CSLToolContext context) {
        this.context = context;
    }

    public void setFiles(List<File> files) {
        this.files = files;
    }

    private void checkArguments() throws Exception {
        if (files == null || files.isEmpty()) {
            throw new Exception("No input file specified");
        }
        if (files.size() > 1) {
            throw new Exception("Only one input file is allowed");
        }
        File file = files.get(0);
        if (!file.exists()) {
            throw new FileNotFoundException("File not found: " + file.getAbsolutePath());
        }
        if (!file.canRead()) {
            throw new IOException("File is not readable: " + file.getAbsolutePath());
        }
    }

    @Override
    public void doRun(ShellContext shellContext) throws Exception {
        checkArguments();
        File file = files.get(0);
        try (InputReader reader = new InputReader(file)) {
            BibliographyFileReader bibliographyReader = new BibliographyFileReader(reader, context);
            bibliographyReader.enableCaching(true);
            context.loadBibliography(bibliographyReader);
        } catch (Exception e) {
            throw new Exception("Error loading bibliography file: " + e.getMessage(), e);
        }
    }
}

