        return Stream.of(
                Arguments.of(DE_CH_BASEL, DE_CH_BASEL, "de-CH-Basel"),
                Arguments.of("de-CH-Basel", DE_CH_BASEL, "de-CH-Basel"),
                Arguments.of("de_CH_BASEL", DE_CH_BASEL, "de-CH-Basel"),
                Arguments.of("de", Locale.GERMAN, "de"),
                Arguments.of(Locale.GERMAN, Locale.GERMAN, "de"),
                Arguments.of("", Locale.ROOT, "")
        );
    }

    private static Stream<Arguments> where_invalid_from_object() {
        return Stream.of(
                Arguments.of(123),
                Arguments.of(new Object()),
                Arguments.of(null)
        );
    }

     private static Stream<Arguments> where_invalid_to_string() {
        return Stream.of(
                Arguments.of((Locale) null)
        );
    }

