public class GCD {
  public static int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
  }
  public static void main(String[] args) {
    int num1 = 24, num2 = 60;
    int gcd = gcd(num1, num2);
    System.out.println("GCD of " + num1 +" and " + num2 + " is: " + gcd);
  }
}

import org.bukkit.command.CommandSender;
