public class EntityStackO extends SingleOption<EntityStack> {
    private int maxEntities = -1;
    private boolean allowStacked = true;
    private EntityParser parser;

    public EntityStackO(EntityParser parser) {
        this.parser = parser;
    }

    @Override
    public EntityStack parse(CommandSender sender, String input) throws Exception {
        return parser.parse(input);
    }

    @Override
    public String serialize(EntityStack value) {
        return value.toString();
    }

    @Override
    public EntityStackO clone() {
        EntityStackO clone = new EntityStackO(parser);
        clone.maxEntities = maxEntities;
        clone.allowStacked = allowStacked;
        return clone;
    }

    public EntityStackO maxEntities(int maxEntities) {
        this.maxEntities = maxEntities;
        return this;
    }

    public EntityStackO allowStacked(boolean allowStacked) {
        this.allowStacked = allowStacked;
        return this;
    }

    public int getMaxEntities() {
        return maxEntities;
    }

    public boolean isAllowStacked() {
        return allowStacked;
    }
}

class EntityStack {
