import org.tanaguru.entity.audit.ProcessResult;
import org.tanaguru.entity.reference.Nomenclature;
import org.tanaguru.processor.SSPHandler;
import org.tanaguru.ruleimplementation.TestSolution;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

public class Aw21Rule10011 {

    private static final String MESSAGE_CODE = "AW21.Rule.10011";
    private static final String DEPREC_TAG_NOM = "DeprecatedTagNomenclature";

    public ProcessResult processImpl(SSPHandler sspHandler) {
        ProcessResult processResult = new ProcessResult();
        processResult.setTestSolution(TestSolution.NEED_MORE_INFO);
        processResult.setWebPage(sspHandler.getWebPage());

        Document document = sspHandler.getSSP().getDocument();
        NodeList nodeList = document.getElementsByTagName("*");

        Nomenclature nomenclature = loadByCode(DEPREC_TAG_NOM);

        for (int i = 0; i < nodeList.getLength(); i++) {
            Element element = (Element) nodeList.item(i);
            String tagName = element.getTagName();

            if (nomenclature.getValueCodeList().contains(tagName)) {
                processResult.setTestSolution(TestSolution.FAILED);
                addSourceCodeRemark(processResult, element, MESSAGE_CODE, tagName);
            }
        }

        return processResult;
    }

    private Nomenclature loadByCode(String code) {
        // Implementation to load nomenclature by code
        // For demonstration purposes, assume it returns a Nomenclature object
        return new Nomenclature();
    }

    private void addSourceCodeRemark(ProcessResult processResult, Node element, String messageCode, String target) {
        // Implementation to add remark to process result
        // For demonstration purposes, assume it adds a remark
        processResult.addRemark("Deprecated tag found: " + target);
    }
}

