/**
 * RcBHT.java
 *
 * 不用管类型
 *
 *
 */
public class BhTree<T> extends BehaviorTree<T> {

    static final String TAG = "RcBHT";

    //fields>>
    HashMap<String, BhLeafTask<T>> tasksMap = new HashMap<>();
    private boolean pauseFlag;
    //fields<<

    public void pause() {
        pauseFlag = true;
    }

    public void resume() {
        pauseFlag = false;
    }

    //func>>
    @SuppressWarnings("unchecked")
    Task<T> createTask(String type, String name, String args) {
        switch(type) {
        case "leaf":
            BhLeafTask<T> leaf;// = new RcLeafTask<T>();
            //相同的name会缓存
            if(name != null) {
                leaf = tasksMap.get(name);
                if(leaf != null) {
                    CCLog.debug(TAG, "find same leaf task : " + name);
                    return leaf;
                }
                if("debug".equals(args)) {
                    leaf = new DebugTask(name);
                } else {
                    leaf = new BhLeafTask<T>();
                }
                tasksMap.put(name, leaf);
                return leaf;
            } else {
                if("debug".equals(args)) {
                    leaf = new DebugTask(name);
                } else {
                    leaf = new BhLeafTask<T>();
                }
            }
            return leaf;
        case "parallel":
            if(args == null) {
                return new Parallel<T>();
            } else {
                switch(args) {
                case "selector":
                    return new Parallel<T>(Policy.Selector);
                case "sequence":
                    return new Parallel<T>(Policy.Sequence);
                }
                CCLog.error(TAG, "pattern fail args = " + args + "  need selector or sequence");
                return null;
            }
        case "selector":
            return new Selector<T>();
        case "sequence":
            return new Sequence<T>();
        }
        CCLog.error(TAG, "not found type : " + type);
        return null;
    }

    final Task<T> createTask(StructBHTNode node) {

import org.hl7.v3.PRPAIN201306UV02;
import org.hl7.v3.MCCIIN000002UV01;
import gov.hhs.fha.nhinc.common.nhinccommon.AssertionType;
import gov.hhs.fha.nhinc.common.nhinccommon.NhinTargetSystemType;
import gov.hhs.fha.nhinc.aspect.AspectHelper;
import gov.hhs.fha.nhinc.patientdiscovery.aspect.PatientDiscoveryAspect;

/**
 * No-Op implementation for Nhin Patient Discovery Deferred Response Proxy.
 * This implementation bypasses actual processing and returns a simple acknowledgment.
 *
 */
public class NhinPatientDiscoveryDeferredRespProxyNoOpImpl {

    /**
     * This method is called to process a patient discovery deferred response query.
     * In this No-Op implementation, it simply creates and returns an acknowledgment.
     *
     * @param request       The patient discovery query message.
     * @param assertion     Security assertion information.
     * @param targetSystem  Target system details.
     * @return              An acknowledgment message.
     */
    public MCCIIN000002UV01 respondingGatewayPRPAIN201306UV02(PRPAIN201306UV02 request, AssertionType assertion, NhinTargetSystemType targetSystem) {
        String assertionId = AspectHelper.getAssertionId();
        PatientDiscoveryAspect.aspectBeginRespondingGatewayPRPAIN201306UV02(request, assertion, assertionId);

        // No-op implementation - bypassing actual processing to return a deferred response ack
        MCCIIN000002UV01 response = new MCCIIN000002UV01();

        PatientDiscoveryAspect.aspectEndRespondingGatewayPRPAIN201306UV02(response, assertionId);
        return response;
    }

}

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.util.List;

import eu.europa.esig.dss.diagnostic.CertificateRefWrapper;
import eu.europa.esig.dss.diagnostic.DiagnosticData;
import eu.europa.esig.dss.diagnostic.RelatedCertificateWrapper;
import eu.europa.esig.dss.diagnostic.RevocationWrapper;
import eu.europa.esig.dss.enumerations.CertificateRefOrigin;
import eu.europa.esig.dss.model.DSSDocument;
import eu.europa.esig.dss.model.InMemoryDocument;

public class PAdESOCSPSigningCertificateTest extends AbstractPAdESTestValidation {

    @Override
    protected DSSDocument getSignedDocument() {
        return new InMemoryDocument(getClass().getResourceAsStream("/validation/pades-ocsp-sign-cert.pdf"));
    }

    @Override
    protected void checkRevocationData(DiagnosticData diagnosticData) {
        super.checkRevocationData(diagnosticData);

        for (RevocationWrapper revocationWrapper : diagnosticData.getAllRevocationData()) {
            assertNotNull(revocationWrapper.getSigningCertificate());

            List<RelatedCertificateWrapper> relatedCertificates = revocationWrapper.foundCertificates().getRelatedCertificates();
            assertEquals(1, relatedCertificates.size());
            assertEquals(0, revocationWrapper.foundCertificates().getOrphanCertificates().size());

            RelatedCertificateWrapper relatedCertificateWrapper = relatedCertificates.get(0);
            assertEquals(1, relatedCertificateWrapper.getReferences().size());

            CertificateRefWrapper certificateRefWrapper = relatedCertificateWrapper.getReferences().get(0);
            assertEquals(CertificateRefOrigin.SIGNING_CERTIFICATE, certificateRefWrapper.getOrigin());
        }
    }

}

