import android.text.Layout;
import android.util.Log;
import android.widget.TextView;

/**
 * Helper utilities useful during debugging that compute the maximum number of characters per line
 * in a {@link TextView} or {@link Layout}.
 */
public class CharsPerLineUtil {
    private static final String TAG = "CharsPerLineUtil";

    public static final int RECOMMENDED_MIN_CPL = 45;
    public static final int RECOMMENDED_MAX_CPL = 75;

    /**
     * Compute the maximum number of characters per line in the given {@link TextView}.
     */
    public static int getMaxCharsPerLine(TextView textView) {
        return getMaxCharsPerLine(textView.getLayout());
    }

    /**
     * Compute the maximum number of characters per line in the given {@link Layout}.
     */
    public static int getMaxCharsPerLine(Layout layout) {
        int maxChars = 0;
        int maxIndex = -1;
        for (int i = layout.getLineCount() - 1; i >= 0; i--) {
            int chars = layout.getLineEnd(i) - layout.getLineStart(i);
            if (chars > maxChars) {
                maxChars = chars;
                maxIndex = i;
            }
        }
        if (BuildConfig.DEBUG && maxIndex >= 0) {
            CharSequence line = layout.getText().subSequence(
                    layout.getLineStart(maxIndex),
                    layout.getLineEnd(maxIndex));
            Log.d(TAG, "Max line: '" + line + "' (length=" + line.length() + ")");
        }
        return maxChars;
    }
}

import com.drew.lang.annotations.NotNull;
import com.drew.lang.annotations.Nullable;
import com.drew.metadata.TagDescriptor;

/**
 * Describes tags specific to Kyocera and Contax cameras.
 *
 */
@SuppressWarnings("ConstantConditions")
public class KyoceraMakernoteDescriptor extends TagDescriptor<KyoceraMakernoteDirectory>
{
    public KyoceraMakernoteDescriptor(@NotNull KyoceraMakernoteDirectory directory)
    {
        super(directory);
    }

    @Override
    public String getDescription(int tagType)
    {
        String description = _directory.getString(tagType);
        if (description != null)
            return description;

        switch (tagType) {
            case KyoceraMakernoteDirectory.TAG_KYOCERA_PRINT_IMAGE_MATCHING_INFO:
                return getPrintImageMatchingInfoDescription();
            case KyoceraMakernoteDirectory.TAG_KYOCERA_PROPRIETARY_THUMBNAIL:
                return getProprietaryThumbnailDataDescription();
            default:
                return super.getDescription(tagType);
        }
    }

    @Nullable
    public String getPrintImageMatchingInfoDescription()
    {
        byte[] bytes = _directory.getByteArray(KyoceraMakernoteDirectory.TAG_KYOCERA_PRINT_IMAGE_MATCHING_INFO);
        if (bytes == null)
            return null;
        return String.format("Print Image Matching (PIM) data found, %d bytes", bytes.length);
    }

    @Nullable
    public String getProprietaryThumbnailDataDescription()
    {
        byte[] bytes = _directory.getByteArray(KyoceraMakernoteDirectory.TAG_KYOCERA_PROPRIETARY_THUMBNAIL);
        if (bytes == null)
            return null;
        return String.format("Proprietary Thumbnail Data, %d bytes", bytes.length);
    }
}

import org.jf.dexlib2.iface.reference.StringReference;
import org.jf.dexlib2.writer.StringSection;
import org.jf.util.ExceptionWithContext;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;

public class StringPool extends StringTypeBasePool implements StringSection<CharSequence, StringReference> {

    public StringPool(@Nonnull DexPool dexPool) {
        super(dexPool);
    }

    public void intern(@Nonnull CharSequence string) {
        internedItems.put(string.toString(), 0);
    }

    public void internNullable(@Nullable CharSequence string) {
        if (string != null) {
            intern(string);
        }
    }

    @Override public int getItemIndex(@Nonnull StringReference key) {
        Integer index = internedItems.get(key.toString());
        if (index == null) {
            throw new ExceptionWithContext("Item not found.: %s", key.toString());
        }
        return index;
    }

    @Override public boolean hasJumboIndexes() {
        return internedItems.size() > 65536;
    }
}

import java.io.BufferedOutputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.SocketException;

import org.apache.commons.net.ftp.FTP;
import org.apache.commons.net.ftp.FTPClient;

public class FTPClientExample {

    public static void main(String[] args) {
        String server = "ftp.example.com";
        int port = 21;
        String user = "username";
        String pass = "password";

        FTPClient ftpClient = new FTPClient();
        try {
            ftpClient.connect(server, port);
            ftpClient.login(user, pass);
            ftpClient.enterLocalPassiveMode();
            ftpClient.setFileType(FTP.BINARY_FILE_TYPE);

            // APPROACH #1: using retrieveFile(String, OutputStream)
            String remoteFile1 = "/path/to/remote/file1.txt";
            FileOutputStream fos1 = new FileOutputStream("file1.txt");
            ftpClient.retrieveFile(remoteFile1, fos1);
            fos1.close();

            // APPROACH #2: using InputStream retrieveFileStream(String)
            String remoteFile2 = "/path/to/remote/file2.txt";
            FileOutputStream fos2 = new FileOutputStream("file2.txt");
            InputStream is = ftpClient.retrieveFileStream(remoteFile2);
            byte[] bytesArray = new byte[4096];
            int bytesRead = -1;
            while ((bytesRead = is.read(bytesArray)) != -1) {
                fos2.write(bytesArray, 0, bytesRead);
            }
            is.close();
            fos2.close();
            boolean success = ftpClient.completePendingCommand();
            if (success) {
                System.out.println("File has been downloaded successfully.");
            }
        } catch (IOException ex) {
            System.out.println("Error: " + ex.getMessage());
            ex.printStackTrace();
        } finally {
            try {
                if (ftpClient.isConnected()) {
                    ftpClient.logout();
                    ftpClient.disconnect();
                }
            } catch (IOException ex) {
                ex.printStackTrace();
            }
        }
    }
}

import org.elasticsearch.action.ActionListener;
import org.elasticsearch.action.index.IndexResponse;
import org.elasticsearch.action.support.ActionFilters;
import org.elasticsearch.action.support.DelegatingActionListener;
import org.elasticsearch.action.support.HandledTransportAction;
import org.elasticsearch.common.inject.Inject;
import org.elasticsearch.common.settings.Settings;
import org.elasticsearch.script.ScriptService;
import org.elasticsearch.threadpool.ThreadPool;
import org.elasticsearch.transport.TransportService;

/**
 * Performs the put indexed script operation.
 */
public class TransportPutIndexedScriptAction extends HandledTransportAction<PutIndexedScriptRequest, PutIndexedScriptResponse> {

    private final ScriptService scriptService;

    @Inject
    public TransportPutIndexedScriptAction(Settings settings, ThreadPool threadPool,
                                           ScriptService scriptService, TransportService transportService, ActionFilters actionFilters) {
        super(settings, PutIndexedScriptAction.NAME, threadPool, transportService, actionFilters, PutIndexedScriptRequest.class);
        this.scriptService = scriptService;
    }

    @Override
    protected void doExecute(final PutIndexedScriptRequest request, final ActionListener<PutIndexedScriptResponse> listener) {
        scriptService.putScriptToIndex(request, new DelegatingActionListener<IndexResponse,PutIndexedScriptResponse>(listener) {
            @Override
            public PutIndexedScriptResponse getDelegatedFromInstigator(IndexResponse indexResponse){
                return new PutIndexedScriptResponse(indexResponse.getType(),indexResponse.getId(),indexResponse.getVersion(),indexResponse.isCreated());
            }
        });
    }
}

import java.util.Map;

/**
 * Interface for machine learning methods that support properties.
 * This interface provides methods for getting and setting properties of different data types,
 * retrieving all properties, and updating objects when property changes occur.
 */
public interface MLProperties {

    /**
     * Get all properties.
     * @return A map of all properties.
     */
    Map<String, Object> getProperties();

    /**
     * Get a property as a double.
     * @param name The name of the property.
     * @return The property value as a double.
     */
    double getPropertyDouble(String name);

    /**
     * Get a property as a long.
     * @param name The name of the property.
     * @return The property value as a long.
     */
    long getPropertyLong(String name);

    /**
     * Get a property as a string.
     * @param name The name of the property.
     * @return The property value as a string.
     */
    String getPropertyString(String name);

    /**
     * Set a property.
     * @param name The name of the property.
     * @param value The value of the property.
     */
    void setProperty(String name, Object value);

    /**
     * Update properties.
     * This method is called when properties change.
     */
    void updateProperties();
}

import com.ibm.icu.util.ChineseCalendar;
import java.util.Scanner;

public class LunarMonthDays {
    public static void main(String[] args) {
        // Create a scanner to read input from the user
        Scanner scanner = new Scanner(System.in);

        // Prompt the user to enter the lunar month and year
        System.out.print("Enter the lunar month (1-12): ");
        int month = scanner.nextInt();
        System.out.print("Enter the lunar year: ");
        int year = scanner.nextInt();

        // Create a Chinese Calendar object for the given year and month
        ChineseCalendar calendar = new ChineseCalendar();
        calendar.set(ChineseCalendar.EXTENDED_YEAR, year + 2637); // Convert from the lunar year to the Gregorian year
        calendar.set(ChineseCalendar.MONTH, month - 1); // ChineseCalendar.MONTH is 0-based

        // Compute the number of days in the lunar month
        int days = calendar.getActualMaximum(ChineseCalendar.DAY_OF_MONTH);

        // Output the result
        System.out.println("The number of days in the lunar month is " + days);
    }
}

public class Marks {
    private int[] marks;
    private int numdata;

    public Marks() {
        numdata = 0;
    }

    public Marks(int num) {
        marks = new int[num];
        numdata = num;
    }

    public void createData(int num) {
        marks = new int[num];
        numdata = num;
    }

    public float calcAvg() {
        float sum = 0;
        for (int i = 0; i < numdata; i++) {
            sum += marks[i];
        }
        float avg = sum / numdata;
        return avg;
    }

    public void setMark(int mark, int index) throws Exception {
        if (mark < 0)
            throw new Exception("Mark is incorrect");

        this.marks[index] = mark;
    }

    public float getMark(int index) {
        return marks[index];
    }
}

import com.google.common.base.Preconditions;
import io.trino.rcfile.RcFileDataSource;
import org.apache.hadoop.fs.FSDataInputStream;
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.hive.ql.io.StatsProvidingRecordReader;
import org.apache.hadoop.mapred.FileSplit;
import org.apache.hadoop.mapred.InputSplit;

import java.io.IOException;
import java.util.Objects;

import static java.util.Objects.requireNonNull;

public class HdfsRcFileDataSource
        implements RcFileDataSource
{
    private final FSDataInputStream inputStream;
    private final Path path;
    private final long size;
    private long readBytes;
    private long readTimeNanos;

    public HdfsRcFileDataSource(
            Path path,
            long size,
            FSDataInputStream inputStream)
    {
        this.path = requireNonNull(path, "path is null");
        this.size = size;
        this.inputStream = requireNonNull(inputStream, "inputStream is null");
    }

    @Override
    public long getSize()
    {
        return size;
    }

    @Override
    public String getId()
    {
        return path.toString();
    }

    @Override
    public byte[] readFully(long position, int length)
            throws IOException
    {
        Preconditions.checkArgument(position >= 0, "position is negative");
        Preconditions.checkArgument(length >= 0, "length is negative");
        Preconditions.checkArgument(position + length <= size, "position + length exceeds file size");

        long start = System.nanoTime();
        byte[] buffer = new byte[length];
        inputStream.readFully(position, buffer, 0, length);
        readTimeNanos += System.nanoTime() - start;
        readBytes += length;
        return buffer;
    }

    @Override
    public void close()
            throws IOException
    {
        inputStream.close();
    }

    @Override
    public long getReadBytes()
    {
        return readBytes;
    }

    @Override
    public long getReadTimeNanos()
    {
        return readTimeNanos;
    }

    @Override
    public String toString()
    {
        return getId();
    }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        HdfsRcFileDataSource that = (HdfsRcFileDataSource) o;
        return path.equals(that.path);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(path);
    }
}

import griffon.converter.ConversionException;
import org.codehaus.griffon.ConversionSupport;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import java.util.Collections;
import java.util.Locale;
import java.util.stream.Stream;

import static org.hamcrest.CoreMatchers.equalTo;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 */
public class LocaleConverterTest extends ConversionSupport {
    private static final Locale DE_CH_BASEL = new Locale("de", "CH", "Basel");

    @ParameterizedTest
    @MethodSource("where_bidirectional")
    public void bidirectionalConversion(Object value, Locale locale, String literal) {
        // given:
        LocaleConverter formatter = new LocaleConverter();

        // when:
        Locale lcl = formatter.fromObject(value);
        String str = formatter.toString(locale);

        // then:
        assertThat(str, equalTo(literal));
        assertThat(lcl, equalTo(locale));
    }

    @ParameterizedTest
    @MethodSource("where_invalid")
    public void checkInvalidConversion(Object value) {
        // given:
        LocaleConverter converter = new LocaleConverter();

        // when:
        assertThrows(ConversionException.class, () -> converter.fromObject(value));
    }

    public static Stream<Arguments> where_bidirectional() {
        return Stream.of(
            Arguments.of(null, null, null),
            Arguments.of("", null, null),
            Arguments.of(" ", null, null),
            Arguments.of(Locale.ENGLISH, Locale.ENGLISH, "en"),
            Arguments.of("en", Locale.ENGLISH, "en")
        );
    }

    public static Stream<Arguments> where_invalid() {
        return Stream.of(
            Arguments.of(1),
            Arguments.of(new Object()),
            Arguments.of(Collections.emptyList()),
            Arguments.of(Collections.emptyMap())
        );
    }
}

import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import org.apache.commons.lang3.StringUtils;

public class IndexMergeUtil {

    private static final String SITE_NAME_PARAMETER = "siteName";
    private static final String REDUCE_BOOST_PARAMETER = "reduceBoost";

    public static void callMergeSiteIndex(String siteName) {
        callMergeSiteIndex(siteName, false);
    }

    public static void callMergeSiteIndex(String siteName, boolean reduceBoost) {
        WebConfig webConfig = WebConfig.getInstance();
        String masterWebUrl = webConfig.getMasterWebUrl();
        String servletUrl = masterWebUrl + "/merge-index";
        String url = servletUrl + "?" + SITE_NAME_PARAMETER + "=" + siteName;
        if (reduceBoost) {
            url += "&" + REDUCE_BOOST_PARAMETER + "=true";
        }

        try {
            URL mergeUrl = new URL(url);
            HttpURLConnection connection = (HttpURLConnection) mergeUrl.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();
            connection.disconnect();
        } catch (IOException e) {
            System.err.println("Error merging index for site " + siteName + ": " + e.getMessage());
        }
    }

    public static void callReduceSiteIndex(String siteName) {
        callMergeSiteIndex(siteName, true);
    }

    public static void main(String[] args) {
        KarniyarikRepository repository = new KarniyarikRepository();
        DeploymentConfig deploymentConfig = repository.getDeploymentConfig();
        String[] siteNames = deploymentConfig.getSiteNames();

        for (String siteName : siteNames) {
            callMergeSiteIndex(siteName);
            try {
                Thread.sleep(1000); // wait 1 second before merging the next site's index
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

public class BitapAlgorithm {
    private static final int ALPHABET_SIZE = 256;

    public static List<Integer> search(String pattern, String text) {
        List<Integer> positions = new ArrayList<>();

        int m = pattern.length();
        int[] R = new int[ALPHABET_SIZE];
        int[] D = new int[m + 1];
        int[] prevD = new int[m + 1];

        int matchMask = 1 << (m - 1);
        Arrays.fill(R, 0);
        for (int i = 0; i < m; i++) {
            R[pattern.charAt(i)] |= 1 << i;
        }

        for (int i = 1; i <= m; i++) {
            D[i] = 1 << (i - 1);
        }

        for (int i = 0; i < text.length(); i++) {
            int oldD = D[0];
            int letter = text.charAt(i);
            D[0] = ((D[0] << 1) | 1) & R[letter];
            for (int j = 1; j <= m; j++) {
                int tmp = D[j];
                D[j] = ((prevD[j - 1] & (D[j - 1] << 1)) | (D[j] << 1) | 1) & R[pattern.charAt(j - 1)];
                prevD[j - 1] = tmp;
            }

            if ((D[m] & matchMask) != 0) {
                positions.add(i - m + 1);
            }

            if ((D[0] & 1) == 0) {
                break;
            }
        }

        return positions;
    }
}

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.wso2.carbon.context.PrivilegedCarbonContext;
import javax.websocket.*;
import javax.websocket.server.PathParam;
import javax.websocket.server.ServerEndpoint;
import org.wso2.carbon.event.output.adapter.websocket.local.WebsocketLocalOutputCallbackRegisterService;
import org.wso2.carbon.utils.CarbonUtils;

@ServerEndpoint(value = "/subscription-endpoint/{adaptorName}/{tenantId}")
public class SubscriptionEndpoint {
    private static final Log log = LogFactory.getLog(SubscriptionEndpoint.class);

    @OnClose
    public void onClose(Session session, CloseReason closeReason, @PathParam("adaptorName") String adaptorName, @PathParam("tenantId") int tenantId) {
        if (log.isDebugEnabled()) {
            log.debug("Session closed for adapter: " + adaptorName + ", tenant: " + tenantId + ", session id: " + session.getId());
        }
        unsubscribeSession(session, adaptorName, tenantId);
    }

    @OnError
    public void onError(Session session, Throwable throwable, @PathParam("adaptorName") String adaptorName, @PathParam("tenantId") int tenantId) {
        log.error("Session error for adapter: " + adaptorName + ", tenant: " + tenantId + ", session id: " + session.getId(), throwable);
        unsubscribeSession(session, adaptorName, tenantId);
    }

    private void unsubscribeSession(Session session, String adaptorName, int tenantId) {
        try {
            PrivilegedCarbonContext.startTenantFlow();
            PrivilegedCarbonContext.getThreadLocalCarbonContext().setTenantId(tenantId);
            WebsocketLocalOutputCallbackRegisterService service = (WebsocketLocalOutputCallbackRegisterService) CarbonUtils.getOSGiService(WebsocketLocalOutputCallbackRegisterService.class);
            if (service != null) {
                service.unsubscribe(adaptorName, session.getId());
                if (log.isDebugEnabled()) {
                    log.debug("Unsubscribed session: " + session.getId() + ", adapter: " + adaptorName + ", tenant: " + tenantId);
                }
            } else {
                log.error("Service not found. Unsubscription failed for session: " + session.getId());
            }
        } catch (Exception e) {
            log.error("Error during unsubscription: " + session.getId(), e);
        } finally {
            PrivilegedCarbonContext.endTenantFlow();
        }
    }
}

