import au.gov.naa.digipres.xena.kernel.XenaException;
import au.gov.naa.digipres.xena.kernel.view.XenaView;
import au.gov.naa.digipres.xena.util.BinaryDeNormaliser;

/**
 * View for PDF files.
 *
 */
public class PdfView extends XenaView {
    public static final String PDFVIEW_VIEW_NAME = "PDF Viewer";
    private static final long serialVersionUID = 1L;
    private SimpleViewer simpleViewer;
    private File pdfFile;

    public PdfView() {
    }

    @Override
    public boolean canShowTag(String tag) throws XenaException {
        return tag.equals(viewManager.getPluginManager().getTypeManager().lookupXenaFileType(XenaPdfFileType.class).getTag());
    }

    @Override
    public String getViewName() {
        return PDFVIEW_VIEW_NAME;
    }

    @Override
    public ContentHandler getContentHandler() throws XenaException {

        FileOutputStream xenaTempOS = null;
        try {
            pdfFile = File.createTempFile("pdffile", ".pdf");
            pdfFile.deleteOnExit();
            xenaTempOS = new FileOutputStream(pdfFile);
        } catch (IOException e) {
            throw new XenaException("Problem creating temporary xena output file", e);
        }

        BinaryDeNormaliser base64Handler = new BinaryDeNormaliser() {
            /*
             * (non-Javadoc)
             * @see au.gov.naa.digipres.xena.kernel.normalise.AbstractDeNormaliser#endDocument()
             */
            @Override
            public void endDocument() {
                if (pdfFile.exists()) {
                    simpleViewer = new SimpleViewer();
                    simpleViewer.setRootContainer(PdfView.this);
                    simpleViewer.setupViewer();
                    simpleViewer.openDefaultFile(pdfFile.getAbsolutePath());
                }
            }
        };

        StreamResult result = new StreamResult(xenaTempOS);
        base64Handler.setResult(result);
        return base64Handler;
    }

    /*
     * (non-Javadoc)
     * @see au.gov.naa.digipres.xena.kernel.view.XenaView#doClose()
     */
    @Override
    public void doClose() {
        super.doClose();

    }

}

/*
 * @test SetDontInlineMethodTest
 * @compile -J-XX:+UnlockDiagnosticVMOptions -J-XX:+WhiteBoxAPI CompilerWhiteBoxTest.java
 * @compile -J-XX:+UnlockDiagnosticVMOptions -J-XX:+WhiteBoxAPI SetDontInlineMethodTest.java
 * @run main/othervm -XX:+UnlockDiagnosticVMOptions -XX:+WhiteBoxAPI SetDontInlineMethodTest
 */
public class SetDontInlineMethodTest extends CompilerWhiteBoxTest {

    public static void main(String[] args) throws Exception {
        new SetDontInlineMethodTest().runTest();
    }

    protected void test() throws Exception {
        if (WHITE_BOX.setDontInlineMethod(METHOD, true)) {
            throw new RuntimeException("on start " + METHOD
                    + " must be inlineable");
        }
        if (!WHITE_BOX.setDontInlineMethod(METHOD, true)) {
            throw new RuntimeException("after first change to true " + METHOD
                    + " must be not inlineable");
        }
        if (!WHITE_BOX.setDontInlineMethod(METHOD, false)) {
            throw new RuntimeException("after second change to true " + METHOD
                    + " must be still not inlineable");
        }
        if (WHITE_BOX.setDontInlineMethod(METHOD, false)) {
            throw new RuntimeException("after first change to false" + METHOD
                    + " must be inlineable");
        }
        if (WHITE_BOX.setDontInlineMethod(METHOD, false)) {
            throw new RuntimeException("after second change to false " + METHOD
                    + " must be inlineable");
        }
    }
}

import com.google.gson.Gson;
import com.google.gson.TypeAdapter;
import com.google.gson.TypeAdapterFactory;
import com.google.gson.reflect.TypeToken;

public final class AutoValueAdapterFactory implements TypeAdapterFactory {
  @SuppressWarnings("unchecked")
  @Override public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> type) {
    Class<? super T> rawType = type.getRawType();
    if (!rawType.isAnnotationPresent(AutoGson.class)) {
      return null;
    }

    String packageName = rawType.getPackage().getName();
    String className = rawType.getName().substring(packageName.length() + 1).replace('$', '_');
    String autoValueName = packageName + ".AutoValue_" + className;

    try {
      Class<?> autoValueType = Class.forName(autoValueName);
      return (TypeAdapter<T>) gson.getAdapter(autoValueType);
    } catch (ClassNotFoundException e) {
      throw new RuntimeException("Could not load AutoValue type " + autoValueName, e);
    }
  }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class PercentileComputation {

    private List<Double> values;

    public PercentileComputation(List<Double> values) {
        if (values == null) {
            throw new IllegalArgumentException("Input list cannot be null.");
        }
        this.values = new ArrayList<>(values); // Create a copy to avoid modifying input
        Collections.sort(this.values); // Sort the values
    }

    public double getMedian() {
        return getMedian(this.values);
    }

    public double getLowerQuartile() {
        int n = values.size();
        if (n == 0) return Double.NaN;
        int mid = n / 2;
        List<Double> lowerHalf;
        if (n % 2 == 0) {
            lowerHalf = values.subList(0, mid);
        } else {
            lowerHalf = values.subList(0, mid);
        }
        if (lowerHalf.isEmpty()) return Double.NaN;
        return getMedian(lowerHalf);
    }

    public double getUpperQuartile() {
        int n = values.size();
        if (n == 0) return Double.NaN;
        int mid = n / 2;
        List<Double> upperHalf;
        if (n % 2 == 0) {
            upperHalf = values.subList(mid, n);
        } else {
            upperHalf = values.subList(mid + 1, n);
        }
         if (upperHalf.isEmpty()) return Double.NaN;
        return getMedian(upperHalf);
    }

    private double getMedian(List<Double> data) {
        int n = data.size();
        if (n == 0) return Double.NaN;
        if (n % 2 == 1) {
            return data.get(n / 2);
        } else {
            double middle1 = data.get(n / 2 - 1);
            double middle2 = data.get(n / 2);
            return (middle1 + middle2) / 2.0;
        }
    }

    public static void main(String[] args) {
        List<Double> data = new ArrayList<>();
        data.add(3.0);
        data.add(1.0);
        data.add(4.0);
        data.add(1.0);
        data.add(5.0);
        data.add(9.0);
        data.add(2.0);
        data.add(6.0);

        PercentileComputation pc = new PercentileComputation(data);
        System.out.println("Median: " + pc.getMedian());
        System.out.println("Lower Quartile: " + pc.getLowerQuartile());
        System.out.println("Upper Quartile: " + pc.getUpperQuartile());
    }
}

