import com.dd.plist.NSDictionary;
import com.dd.plist.NSObject;
import com.dd.plist.PropertyListFormatException;
import com.dd.plist.PropertyListParser;
import com.dd.plist.XMLPropertyListWriter;
import com.facebook.buck.core.filesystems.RelPath;
import com.facebook.buck.io.filesystem.ProjectFilesystem;
import com.facebook.buck.step.Step;
import com.facebook.buck.step.StepExecutionResult;
import com.facebook.buck.step.StepExecutionContext;
import com.google.common.collect.ImmutableMap;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.text.ParseException;
import java.util.Map;

public class PlistProcessStep implements Step {

  private final ProjectFilesystem filesystem;
  private final RelPath input;
  private final RelPath output;
  private final ImmutableMap<String, String> additionalKeys;
  private final ImmutableMap<String, String> overrideKeys;

  public PlistProcessStep(
      ProjectFilesystem filesystem,
      RelPath input,
      RelPath output,
      ImmutableMap<String, String> additionalKeys,
      ImmutableMap<String, String> overrideKeys) {
    this.filesystem = filesystem;
    this.input = input;
    this.output = output;
    this.additionalKeys = additionalKeys;
    this.overrideKeys = overrideKeys;
  }

  @Override
  public StepExecutionResult execute(StepExecutionContext context) throws IOException {
    try {
      String plistContent = filesystem.readFirstLine(input.getPath());
      NSDictionary rootDict = parse(plistContent);

      for (Map.Entry<String, String> entry : additionalKeys.entrySet()) {
        if (!containsKey(rootDict, entry.getKey())) {
          put(rootDict, entry.getKey(), entry.getValue());
        }
      }
      putAll(rootDict, overrideKeys);

      ByteArrayOutputStream bos = new ByteArrayOutputStream();
      XMLPropertyListWriter.write(rootDict, bos);
      filesystem.writeContentsToPath(
          new String(bos.toByteArray(), StandardCharsets.UTF_8), output.getPath());

      return StepExecutionResult.success();
    } catch (PropertyListFormatException | ParseException e) {
      context.logError(e, "Failed to process plist file: %s", input);
      return StepExecutionResult.ERROR;
    }
  }

  private NSDictionary parse(String plistContent)
      throws IOException, PropertyListFormatException, ParseException {
    return (NSDictionary)
        PropertyListParser.parse(new ByteArrayInputStream(plistContent.getBytes(StandardCharsets.UTF_8)));
  }

