public class ExtensionPointExample {

    interface GIOExtension {
        String getName();
        int getPriority();
        Class<?> getType();
        // Add any methods extensions might need to implement
    }

    static class GIOExtensionPoint {
        private final String name;
        private Class<?> requiredType;
        private final Map<String, GIOExtension> extensionsByName = new HashMap<>();
        private final List<GIOExtension> extensions = new ArrayList<>();

        public GIOExtensionPoint(String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public Class<?> getRequiredType() {
            return requiredType;
        }

        public void setRequiredType(Class<?> requiredType) {
            this.requiredType = requiredType;
        }

        public void implement(String extensionName, Class<?> type, int priority, GIOExtension extensionImpl) {
            if (requiredType != null && !requiredType.isAssignableFrom(type)) {
                throw new IllegalArgumentException("Extension type does not match required type for extension point: " + name);
            }
            if (extensionsByName.containsKey(extensionName)) {
                throw new IllegalArgumentException("Extension with name '" + extensionName + "' already implemented in extension point: " + name);
            }
            extensionsByName.put(extensionName, extensionImpl);
            extensions.add(extensionImpl);
            extensions.sort((e1, e2) -> Integer.compare(e2.getPriority(), e1.getPriority())); // Sort by priority descending
        }

        public GIOExtension getExtensionByName(String extensionName) {
            return extensionsByName.get(extensionName);
        }

        public List<GIOExtension> getExtensions() {
            return new ArrayList<>(extensions); // Return a copy to avoid external modification
        }
    }

    private static final Map<String, GIOExtensionPoint> extensionPoints = new HashMap<>();

    public static GIOExtensionPoint register(String name) {
        if (extensionPoints.containsKey(name)) {
            throw new IllegalArgumentException("Extension point with name '" + name + "' already registered.");
        }
        GIOExtensionPoint extensionPoint = new GIOExtensionPoint(name);
        extensionPoints.put(name, extensionPoint);
        return extensionPoint;
    }

