    public void testExportLogsToDirectory() throws Exception {
        File exportDir = temporaryFolder.newFolder("exportDir");
        String exportDirPath = exportDir.getAbsolutePath();

        // Simulate command execution and output
        String commandOutput = "Exported logs to: " + exportDirPath + "/locator-logs.zip";
