public class ValidateProjectIT {

    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    @Test
    public void testInvalidTaskDefinition() throws IOException, InterruptedException {
        Path projectDir = temporaryFolder.newFolder("invalid_task_proj").toPath();
        Path workflowFile = projectDir.resolve("workflow.digdag");
        String invalidWorkflow = "tasks:\n  task1:\n    sh>: echo hello\n    sh>: echo again";
        Files.write(workflowFile, invalidWorkflow.getBytes(StandardCharsets.UTF_8));

        CommandStatus status = new MockCommandRunner().run("push", projectDir.toString());
        assertFalse("Push command should fail due to invalid task definition", status.isSuccess());
        assertThat(status.stderr(), containsString("Invalid task definition: Task 'task1' has multiple operators"));
    }

    @Test
    public void testInvalidScheduleFormat() throws IOException, InterruptedException {
        Path projectDir = temporaryFolder.newFolder("invalid_schedule_proj").toPath();
        Path workflowFile = projectDir.resolve("workflow.digdag");
        String workflowWithInvalidSchedule = "schedules:\n  cron: * * * * *\n    workflow: workflow.digdag";
        Files.write(workflowFile, workflowWithInvalidSchedule.getBytes(StandardCharsets.UTF_8));

        CommandStatus status = new MockCommandRunner().run("push", projectDir.toString());
        assertFalse("Push command should fail due to invalid schedule format", status.isSuccess());
        assertThat(status.stderr(), containsString("Invalid schedule format: Missing workflow name in schedule definition"));
    }

    static class CommandStatus {
