import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;

public class FTPServer {
    private static final int serverPort = 21; // default FTP port

    public static void main(String[] args) throws Exception {
        ServerSocket serverSocket = new ServerSocket(serverPort);

        while (true) {
            Socket clientSocket = serverSocket.accept();
            System.out.println("New client connected: " + clientSocket.getInetAddress().getHostAddress());

            BufferedReader input = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
            BufferedWriter output = new BufferedWriter(new OutputStreamWriter(clientSocket.getOutputStream()));

            output.write("220 FTP server ready\r\n");
            output.flush();

            String request = input.readLine();
            while (request != null) {
                System.out.println("Received request: " + request);

                if (request.startsWith("USER ")) {
                    output.write("331 Username OK, password required\r\n");
                    output.flush();
                } else if (request.startsWith("PASS ")) {
                    output.write("230 User logged in, proceed\r\n");
                    output.flush();
                } else if (request.startsWith("PWD")) {
                    output.write("257 \"/\" is the current directory\r\n");
                    output.flush();
                } else if (request.startsWith("QUIT")) {
                    output.write("221 Goodbye\r\n");
                    output.flush();
                    break;
                } else {
                    output.write("502 Command not implemented\r\n");
                    output.flush();
                }

                request = input.readLine();
            }

            clientSocket.close();
            System.out.println("Client disconnected");
        }
    }
}

import org.elasticsearch.action.ActionRequest;
import org.elasticsearch.action.ActionResponse;
import org.elasticsearch.action.support.ActionFilters;
import org.elasticsearch.action.support.HandledTransportAction;
import org.elasticsearch.client.Client;
import org.elasticsearch.common.inject.Inject;
import org.elasticsearch.common.settings.Settings;
import org.elasticsearch.script.ScriptService;
import org.elasticsearch.threadpool.ThreadPool;
import org.elasticsearch.transport.TransportService;

public class TransportPutIndexedScriptAction extends HandledTransportAction<PutIndexedScriptRequest, PutIndexedScriptResponse> {

    private final ScriptService scriptService;

    @Inject
    public TransportPutIndexedScriptAction(Settings settings, TransportService transportService, ActionFilters actionFilters, Client client, ScriptService scriptService) {
        super(settings, PutIndexedScriptAction.NAME, transportService, actionFilters, client);
        this.scriptService = scriptService;
    }

    @Override
    protected void doExecute(PutIndexedScriptRequest request, ActionListener<PutIndexedScriptResponse> listener) {
        scriptService.putScriptToIndex(request.getScript(), request.getMetadata(), new ActionListener<IndexResponse>() {
            @Override
            public void onResponse(IndexResponse indexResponse) {
                PutIndexedScriptResponse response = getDelegatedFromInstigator(indexResponse);
                listener.onResponse(response);
            }

            @Override
            public void onFailure(Exception e) {
                listener.onFailure(e);
            }
        });
    }

    private PutIndexedScriptResponse getDelegatedFromInstigator(IndexResponse indexResponse) {
        // Implementation to transform IndexResponse to PutIndexedScriptResponse
        return new PutIndexedScriptResponse(indexResponse.getId(), indexResponse.getVersion());
    }
}

class PutIndexedScriptRequest extends ActionRequest {
    private String script;
    private Map<String, String> metadata;

    public String getScript() {
        return script;
    }

    public Map<String, String> getMetadata() {
        return metadata;
    }
}

class PutIndexedScriptResponse extends ActionResponse {
    private String id;
    private long version;

    public PutIndexedScriptResponse(String id, long version) {
        this.id = id;
        this.version = version;
    }

    public String getId() {
        return id;
    }

    public long getVersion() {
        return version;
    }
}

