import org.alfresco.service.cmr.transfer.TransferTarget;
import org.alfresco.service.cmr.transfer.TransferVersion;

/**
 * Information about a transfer which is in progress.
 *
 */
public class Transfer
{
    private String transferId;
    private TransferTarget transferTarget;
    private TransferVersion toVersion;

    public void setTransferId(String transferId)
    {
        this.transferId = transferId;
    }

    public String getTransferId()
    {
        return transferId;
    }

    // may also have capabilities of the remote system here (for when we are
    // transfering accross versions)

    public boolean equals(Object obj)
    {
        if (obj == null)
        {
            return false;
        }
        else if (this == obj)
        {
            return true;
        }
        else if (obj instanceof Transfer == false)
        {
            return false;
        }
        Transfer that = (Transfer) obj;
        return (this.transferId.equals(that.getTransferId()));
    }

    public int hashCode()
    {
        return transferId.hashCode();
    }

    /**
     * @param target
     */
    public void setTransferTarget(TransferTarget target)
    {
        this.transferTarget = target;
    }

    /**
     * @return the transferTarget
     */
    public TransferTarget getTransferTarget()
    {
        return transferTarget;
    }

    public String toString()
    {
        return "TransferId" + transferId + ", target:" + transferTarget ;
    }

    public void setToVersion(TransferVersion toVersion)
    {
        this.toVersion = toVersion;
    }

    public TransferVersion getToVersion()
    {
        return toVersion;
    }
}

import org.spongepowered.api.command.Command;
import org.spongepowered.api.command.CommandExecutor;
import org.spongepowered.api.command.CommandResult;
import org.spongepowered.api.command.exception.CommandException;
import org.spongepowered.api.command.parameter.CommandContext;
import org.spongepowered.api.entity.living.player.Player;
import org.spongepowered.api.data.Keys;
import org.spongepowered.api.entity.living.player.gamemode.GameMode;
import org.spongepowered.api.entity.living.player.gamemode.GameModes;
import org.spongepowered.api.adventure.text.Text;
import org.spongepowered.api.entity.living.player.server.ServerPlayer;

import java.util.Optional;

@Command.annotatedBuilder()
    .permission("myplugin.gamemode.toggle")
    .executor(GamemodeToggleCommand.class)
    .build()
public class GamemodeToggleCommand implements CommandExecutor {

    @Override
    public CommandResult execute(CommandContext context) throws CommandException {
        Optional<ServerPlayer> playerOptional = context.cause().first(ServerPlayer.class);
        if (!playerOptional.isPresent()) {
            context.cause().audience().sendMessage(Text.of("This command can only be run by a player."));
            return CommandResult.error();
        }
        ServerPlayer player = playerOptional.get();

        GameMode currentGamemode = player.get(Keys.GAME_MODE).orElse(GameModes.SURVIVAL.get());
        GameMode newGamemode;

        if (currentGamemode.equals(GameModes.SURVIVAL.get())) {
            newGamemode = GameModes.CREATIVE.get();
            player.sendMessage(Text.of("Gamemode set to Creative."));
        } else {
            newGamemode = GameModes.SURVIVAL.get();
            player.sendMessage(Text.of("Gamemode set to Survival."));
        }

        player.offer(Keys.GAME_MODE, newGamemode);
        return CommandResult.success();
    }
}

