import java.io.*;
import java.net.*;

public class SMTPServer {
    public static void main(String[] args) throws IOException {
        int port = 25;
        ServerSocket serverSocket = new ServerSocket(port);
        System.out.println("SMTP server listening on port " + port + "...");

        while (true) {
            Socket socket = serverSocket.accept();
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));

            // Send greeting
            out.write("220 localhost SMTP server ready\r\n");
            out.flush();

            String line;
            while ((line = in.readLine()) != null) {
                if (line.startsWith("HELO")) {
                    out.write("250 localhost\r\n");
                    out.flush();
                } else if (line.startsWith("MAIL FROM")) {
                    out.write("250 OK\r\n");
                    out.flush();
                } else if (line.startsWith("RCPT TO")) {
                    out.write("250 OK\r\n");
                    out.flush();
                } else if (line.startsWith("DATA")) {
                    out.write("354 End data with <CR><LF>.<CR><LF>\r\n");
                    out.flush();

                    // Read email body
                    StringBuilder body = new StringBuilder();
                    while ((line = in.readLine()) != null) {
                        if (line.equals(".")) {
                            break;
                        }
                        body.append(line).append("\r\n");
                    }

                    // Print email body
                    System.out.println(body.toString());

                    out.write("250 OK\r\n");
                    out.flush();
                } else if (line.startsWith("QUIT")) {
                    out.write("221 Bye\r\n");
                    out.flush();
                    break;
                } else {
                    out.write("500 Error\r\n");
                    out.flush();
                }
            }

            socket.close();
        }
    }
}

import io.vertx.core.Context;
import io.vertx.core.Vertx;
import io.vertx.core.http.HttpClient;
import io.vertx.core.logging.Logger;
import io.vertx.ext.unit.Async;
import io.vertx.ext.unit.TestContext;
import io.vertx.ext.unit.junit.VertxUnitRunner;
import org.junit.Rule;
import org.junit.runner.RunWith;
import org.sfs.RunBootedTestOnContextRx;
import org.sfs.Server;
import org.sfs.TestSubscriber;
import org.sfs.VertxContext;
import rx.Observable;

import java.nio.file.Path;
import java.util.concurrent.Callable;

import static io.vertx.core.logging.LoggerFactory.getLogger;

@RunWith(VertxUnitRunner.class)
public class BaseTestVerticle {

    private static final Logger LOGGER = getLogger(BaseTestVerticle.class);

    @Rule
    public RunBootedTestOnContextRx runTestOnContext = new RunBootedTestOnContextRx();

    public VertxContext<Server> vertxContext() {
        return runTestOnContext.getVertxContext();
    }

    public HttpClient httpClient() {
        return runTestOnContext.getHttpClient();
    }

    public Vertx vertx() {
        return vertxContext().vertx();
    }

    public Path tmpDir() {
        return runTestOnContext.getTmpDir();
    }

    public void runOnServerContext(TestContext testContext, RunnableWithException callable) {
        Async async = testContext.async();
        Context c = vertxContext().verticle().getContext();
        c.runOnContext(event -> {
            try {
                callable.run();
                async.complete();
            } catch (Exception e) {
                testContext.fail(e);
            }
        });
    }

    public void runOnServerContext(TestContext testContext, Callable<Observable<Void>> callable) {
        Async async = testContext.async();
        Context c = vertxContext().verticle().getContext();
        c.runOnContext(event -> {
            try {
                callable.call().subscribe(new TestSubscriber(testContext, async));
            } catch (Exception e) {
                testContext.fail(e);
            }
        });
    }

    public interface RunnableWithException {

        void run() throws Exception;
    }
}

import android.content.Context;
import android.support.design.widget.AppBarLayout;
import android.support.design.widget.CoordinatorLayout;
import android.support.v4.view.ViewCompat;
import android.util.AttributeSet;
import android.view.View;

/**
 * Workaround AppBarLayout.Behavior for https://issuetracker.google.com/66996774
 *
 * See https://gist.github.com/chrisbanes/8391b5adb9ee42180893300850ed02f2 for
 * example usage.
 *
 * Change the package name as you wish.
 */
public class FixAppBarLayoutBehavior extends AppBarLayout.Behavior {

    public FixAppBarLayoutBehavior() {
        super();
    }

    public FixAppBarLayoutBehavior(Context context, AttributeSet attrs) {
        super(context, attrs);
    }

    @Override
    public void onNestedScroll(CoordinatorLayout coordinatorLayout, AppBarLayout child, View target,
            int dxConsumed, int dyConsumed, int dxUnconsumed, int dyUnconsumed, int type) {
        super.onNestedScroll(coordinatorLayout, child, target, dxConsumed, dyConsumed,
                dxUnconsumed, dyUnconsumed, type);
        stopNestedScrollIfNeeded(dyUnconsumed, child, target, type);
    }

    @Override
    public void onNestedPreScroll(CoordinatorLayout coordinatorLayout, AppBarLayout child,
            View target, int dx, int dy, int[] consumed, int type) {
        super.onNestedPreScroll(coordinatorLayout, child, target, dx, dy, consumed, type);
        stopNestedScrollIfNeeded(dy, child, target, type);
    }

    private void stopNestedScrollIfNeeded(int dy, AppBarLayout child, View target, int type) {
        if (type == ViewCompat.TYPE_NON_TOUCH) {
            final int currOffset = getTopAndBottomOffset();
            if ((dy < 0 && currOffset == 0)
                    || (dy > 0 && currOffset == -child.getTotalScrollRange())) {
                ViewCompat.stopNestedScroll(target, ViewCompat.TYPE_NON_TOUCH);
            }
        }
    }
}

import com.mkyong.crypto.utils.CryptoUtils;

import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.security.DigestInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class ShaUtils {

    private static final Charset UTF_8 = StandardCharsets.UTF_8;
    private static final String OUTPUT_FORMAT = "%-20s:%s";

    public static byte[] digest(byte[] input, String algorithm) {
        MessageDigest md;
        try {
            md = MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException(e);
        }
        byte[] result = md.digest(input);
        return result;
    }

    private static byte[] checksum(String filePath, String algorithm) {

        MessageDigest md;
        try {
            md = MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException(e);
        }

        try (InputStream is = new FileInputStream(filePath);
             DigestInputStream dis = new DigestInputStream(is, md)) {
            while (dis.read() != -1) ; //empty loop to clear the data
            md = dis.getMessageDigest();
        } catch (IOException e) {
            throw new IllegalArgumentException(e);
        }
        return md.digest();

    }

    public static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {

        //String algorithm = "SHA-256";
        String algorithm = "SHA3-256";

        String pText = "Hello World";
        System.out.println(String.format(OUTPUT_FORMAT, "Input (string)", pText));
        System.out.println(String.format(OUTPUT_FORMAT, "Input (length)", pText.length()));

