import java.util.ArrayList;
import java.util.List;
import javax.vecmath.Point3f;
import jene.Node;
import jene.Organism;

public class S3DOrganism extends Organism {
    private List<Node> _roots;
    private Point3f _color;

    public S3DOrganism(List<Node> roots, Point3f color) {
        _roots = roots;
        _color = color;
    }

    public Point3f evaluate(float u, float v) {
        Point3f result = new Point3f();
        for (Node node : _roots) {
            result.add(node.evaluate(u, v));
        }
        return result;
    }

    public void mutateAsexually(float mutationRate) {
        for (Node node : _roots) {
            if (Math.random() < mutationRate) {
                node.mutate();
            }
        }
        if (Math.random() < mutationRate) {
            _color.x += (float) (Math.random() * 2 - 1);
            _color.y += (float) (Math.random() * 2 - 1);
            _color.z += (float) (Math.random() * 2 - 1);
        }
    }

    public S3DOrganism mutateSexually(S3DOrganism parent2) {
        List<Node> newRoots = new ArrayList<>();
        for (int i = 0; i < _roots.size(); i++) {
            if (Math.random() < 0.5) {
                newRoots.add(_roots.get(i));
            } else {
                newRoots.add(parent2._roots.get(i));
            }
        }
        Point3f newColor = new Point3f();
        newColor.x = (_color.x + parent2._color.x) / 2;
        newColor.y = (_color.y + parent2._color.y) / 2;
        newColor.z = (_color.z + parent2._color.z) / 2;
        return new S3DOrganism(newRoots, newColor);
    }
}

import android.graphics.Bitmap;
import android.graphics.Bitmap.Config;
import android.graphics.BitmapShader;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Shader;

// enables hardware accelerated rounded corners
// original idea here : http://www.curious-creature.org/2012/12/11/android-recipe-1-image-with-rounded-corners/
public class RoundedTransformation implements com.squareup.picasso.Transformation {
    private final int radius;
    private final int margin;  // dp

    // radius is corner radii in dp
    // margin is the board in dp
    public RoundedTransformation(final int radius, final int margin) {
        this.radius = radius;
        this.margin = margin;
    }

    @Override
    public Bitmap transform(final Bitmap source) {
        final Paint paint = new Paint();
        paint.setAntiAlias(true);
        paint.setShader(new BitmapShader(source, Shader.TileMode.CLAMP, Shader.TileMode.CLAMP));

        Bitmap output = Bitmap.createBitmap(source.getWidth(), source.getHeight(), Config.ARGB_8888);
        Canvas canvas = new Canvas(output);
        canvas.drawRoundRect(new RectF(margin, margin, source.getWidth() - margin, source.getHeight() - margin), radius, radius, paint);

        if (source != output) {
            source.recycle();
        }

        return output;
    }

    @Override
    public String key() {
        return "rounded";
    }
}

