        DSSDocument document = getSignedDocument(); // Assume this loads the test document
        DiagnosticData diagnosticData = validateDocument(document); // Assume this performs validation

        List<RevocationWrapper> revocationDataList = diagnosticData.getAllRevocationData();
        assertNotNull(revocationDataList);
        assertFalse(revocationDataList.isEmpty());

        RevocationWrapper revocationData = revocationDataList.get(0); // Assuming one revocation data

        assertNotNull(revocationData.getSigningCertificate());

        List<RelatedCertificateWrapper> relatedCertificates = revocationData.foundCertificates();
        assertNotNull(relatedCertificates);
        assertFalse(relatedCertificates.isEmpty());

        List<RelatedCertificateWrapper> orphanCertificates = revocationData.getOrphanCertificates();
        assertTrue(orphanCertificates == null || orphanCertificates.isEmpty());

        for (RelatedCertificateWrapper relatedCert : relatedCertificates) {
            List<CertificateRefWrapper> references = relatedCert.getReferences();
            assertNotNull(references);
            assertFalse(references.isEmpty());
            for (CertificateRefWrapper ref : references) {
                assertEquals(ref.getOrigin(), CertificateRefOrigin.SIGNING_CERTIFICATE);
