/**
 * An {@code ExtensionPopupMenuItem} that is enabled only for {@code MessageContainer}s.
 *
 */
public abstract class ExtensionPopupMenuItemMessageContainer extends ExtensionPopupMenuItem {

    private static final long serialVersionUID = 1L;

    /**
     * Constructs an {@code ExtensionPopupMenuItemMessageContainer}.
     */
    public ExtensionPopupMenuItemMessageContainer() {
        super();
    }

    /**
     * Constructs an {@code ExtensionPopupMenuItemMessageContainer} with the given menu text.
     *
     * @param text the menu text.
     */
    public ExtensionPopupMenuItemMessageContainer(String text) {
        super(text);
    }

    /**
     * Constructs an {@code ExtensionPopupMenuItemMessageContainer} with the given menu text and icon.
     *
     * @param text the menu text.
     * @param icon the menu icon.
     */
    public ExtensionPopupMenuItemMessageContainer(String text, Icon icon) {
        super(text, icon);
    }

    /**
     * Constructs an {@code ExtensionPopupMenuItemMessageContainer} with the given action.
     *
     * @param action the menu action.
     */
    public ExtensionPopupMenuItemMessageContainer(Action action) {
        super(action);
    }

    @Override
    public boolean isEnableForComponent(Component invoker) {
        if (invoker instanceof MessageContainer<?>) {
            return isEnableForMessageContainer((MessageContainer<?>) invoker);
        }
        return false;
    }

    /**
     * Tells whether or not this menu item should be enabled for the given {@code invoker}.
     *
     * @param invoker the message container that invoked this popup menu item.
     * @return {@code true} if it should be enabled, {@code false} otherwise.
     */
    public abstract boolean isEnableForMessageContainer(MessageContainer<?> invoker);
}

