class DeCryptor {

    private static final String TRANSFORMATION = "AES/GCM/NoPadding";
    private static final String ANDROID_KEY_STORE = "AndroidKeyStore";

    private KeyStore keyStore;

    DeCryptor() throws CertificateException, NoSuchAlgorithmException, KeyStoreException,
            IOException {
        initKeyStore();
    }

    private void initKeyStore() throws KeyStoreException, CertificateException,
            NoSuchAlgorithmException, IOException {
        keyStore = KeyStore.getInstance(ANDROID_KEY_STORE);
        keyStore.load(null);
    }

    String decryptData(final String alias, final byte[] encryptedData, final byte[] encryptionIv)
            throws UnrecoverableEntryException, NoSuchAlgorithmException, KeyStoreException,
            NoSuchProviderException, NoSuchPaddingException, InvalidKeyException, IOException,
            BadPaddingException, IllegalBlockSizeException, InvalidAlgorithmParameterException {

        final Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        final GCMParameterSpec spec = new GCMParameterSpec(128, encryptionIv);
        cipher.init(Cipher.DECRYPT_MODE, getSecretKey(alias), spec);

        return new String(cipher.doFinal(encryptedData), "UTF-8");
    }

    private SecretKey getSecretKey(final String alias) throws NoSuchAlgorithmException,
            UnrecoverableEntryException, KeyStoreException {
        return ((KeyStore.SecretKeyEntry) keyStore.getEntry(alias, null)).getSecretKey();
    }
}

public class DeadlockDemo {

    public static Object resource1 = new Object();
    public static Object resource2 = new Object();

    public static void main(String[] args) {
        Thread t1 = new Thread(new Task1());
        Thread t2 = new Thread(new Task2());
        t1.start();
        t2.start();
    }

    static class Task1 implements Runnable {
        public void run() {
            synchronized (resource1) {
                System.out.println("Task 1: locked resource 1");
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {}
                synchronized (resource2) {
                    System.out.println("Task 1: locked resource 2");
                }
            }
        }
    }

    static class Task2 implements Runnable {
        public void run() {
            synchronized (resource2) {
                System.out.println("Task 2: locked resource 2");
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {}
                synchronized (resource1) {
                    System.out.println("Task 2: locked resource 1");
                }
            }
        }
    }
}

import java.util.Vector;

// Iterator
interface Iterator {
    void first();
    void next();
    Object currentItem();
    boolean isDone();
}

//
interface Aggregat {
    Iterator createIterator();
    int count();
    Object getAt(int index);
}

// ConcreteIterator
class ConcreteIterator implements Iterator {
    private Aggregat aggregate;
    private int currentIndex;

    public ConcreteIterator(Aggregat aggregate) {
        this.aggregate = aggregate;
        this.currentIndex = 0;
    }

    @Override
    public void first() {
        currentIndex = 0;
    }

    @Override
    public void next() {
        if (!isDone()) {
            currentIndex++;
        }
    }

    @Override
    public Object currentItem() {
        return aggregate.getAt(currentIndex);
    }

    @Override
    public boolean isDone() {
        return currentIndex >= aggregate.count();
    }
}

// ConcreteAggregat
class ConcreteAggregat implements Aggregat {
    private Vector vector;

    public ConcreteAggregat() {
        this.vector = new Vector();
    }

    public void append(Object object) {
        vector.addElement(object);
    }

    @Override
    public Iterator createIterator() {
        return new ConcreteIterator(this);
    }

    @Override
    public int count() {
        return vector.size();
    }

    @Override
    public Object getAt(int index) {
        return vector.elementAt(index);
    }
}

// Client
class Client {
    public static void main(String[] args) {
        Aggregat aggregate = new ConcreteAggregat();
        aggregate.append("A");
        aggregate.append("B");
        aggregate.append("C");

        Iterator iterator = aggregate.createIterator();
        iterator.first();
        while (!iterator.isDone()) {
            System.out.println(iterator.currentItem());
            iterator.next();
        }
    }
}

import org.elasticsearch.cluster.ClusterState;
import org.elasticsearch.common.UUIDs;
import org.elasticsearch.common.bytes.BytesReference;
import org.elasticsearch.test.ESTestCase;
import org.elasticsearch.xcontent.ToXContent;
import org.elasticsearch.xcontent.XContentBuilder;
import org.elasticsearch.xcontent.XContentParser;
import org.elasticsearch.xcontent.json.JsonXContent;

import java.io.IOException;

import static org.apache.lucene.util.TestUtil.randomSimpleString;
import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.not;

public class IndexTests extends ESTestCase {
    public void testToString() {
        assertEquals("[name/uuid]", new Index("name", "uuid").toString());
        assertEquals("[name]", new Index("name", ClusterState.UNKNOWN_UUID).toString());

        Index random = new Index(
            randomSimpleString(random(), 1, 100),
            usually() ? UUIDs.randomBase64UUID(random()) : ClusterState.UNKNOWN_UUID
        );
        assertThat(random.toString(), containsString(random.getName()));
        if (ClusterState.UNKNOWN_UUID.equals(random.getUUID())) {
            assertThat(random.toString(), not(containsString(random.getUUID())));
        } else {
            assertThat(random.toString(), containsString(random.getUUID()));
        }
    }

    public void testXContent() throws IOException {
        final String name = randomAlphaOfLengthBetween(4, 15);
        final String uuid = UUIDs.randomBase64UUID();
        final Index original = new Index(name, uuid);
        final XContentBuilder builder = JsonXContent.contentBuilder();
        original.toXContent(builder, ToXContent.EMPTY_PARAMS);
        try (XContentParser parser = createParser(JsonXContent.jsonXContent, BytesReference.bytes(builder))) {
            parser.nextToken(); // the beginning of the parser
            assertThat(Index.fromXContent(parser), equalTo(original));
        }
    }

    public void testEquals() {
        Index index1 = new Index("a", "a");
        Index index2 = new Index("a", "a");
        Index index3 = new Index("a", "b");
        Index index4 = new Index("b", "a");
        String s = "Some random other object";
        assertEquals(index1, index1);
        assertEquals(index1, index2);
        assertNotEquals(index1, null);
        assertNotEquals(index1, s);
        assertNotEquals(index1, index3);
        assertNotEquals(index1, index4);
    }
}

