        BIGQUERY_DATASET_NAME, tableName, schema, ImmutableList.of("name", "post_abbr"));

    assertThat(bout.toString()).contains("Clustered table created successfully");
  }
}

import omero.model.Pixels;

/**
 * Calculates the various dimensions of an image from a {@link Pixels} instance.
 *
 */

public class ImportSize {

    public final String fileName;
    public final Pixels pixels;
    public final String dimOrder;
    public final int sizeX, sizeY, sizeZ, sizeC, sizeT, imageCount;
    public final int zSize, wSize, tSize;

    public ImportSize(String fileName, Pixels pixels, String dimOrder) {
        this.fileName = fileName;
        this.pixels = pixels;
        this.dimOrder = dimOrder;

        sizeZ = pixels.getSizeZ().getValue();
        sizeC = pixels.getSizeC().getValue();
        sizeT = pixels.getSizeT().getValue();
        sizeX = pixels.getSizeX().getValue();
        sizeY = pixels.getSizeY().getValue();
        imageCount = sizeZ * sizeC * sizeT;

        final int order = getSequenceNumber(dimOrder);

        int smallOffset = 1;
        switch (order) {
        // ZTW sequence
        case 0:
            zSize = smallOffset;
            tSize = zSize * sizeZ;
            wSize = tSize * sizeT;
            break;
        // WZT sequence
        case 1:
            wSize = smallOffset;
            zSize = wSize * sizeC;
            tSize = zSize * sizeZ;
            break;
        // ZWT sequence
        case 2:
            zSize = smallOffset;
            wSize = zSize * sizeZ;
            tSize = wSize * sizeC;
            break;
        // TWZ sequence
        case 3:
            tSize = smallOffset;
            wSize = tSize * sizeT;
            zSize = wSize * sizeC;
            break;
        // WTZ sequence
        case 4:
            wSize = smallOffset;
            tSize = wSize * sizeC;
            zSize = tSize * sizeT;
            break;
        // TZW
        case 5:
            tSize = smallOffset;
            zSize = tSize * sizeT;
            wSize = zSize * sizeZ;
            break;
        default:
            throw new RuntimeException("Bad order");
        }
    }

    private int getSequenceNumber(String dimOrder) {
        if (omero.model.enums.DimensionOrderXYZTC.value.equals(dimOrder))
            return 0;
        if (omero.model.enums.DimensionOrderXYCZT.value.equals(dimOrder))
            return 1;
        if (omero.model.enums.DimensionOrderXYZCT.value.equals(dimOrder))
            return 2;
        if (omero.model.enums.DimensionOrderXYTCZ.value.equals(dimOrder))
            return 3;
        if (omero.model.enums.DimensionOrderXYCTZ.value.equals(dimOrder))
            return 4;
        if (omero.model.enums.DimensionOrderXYTZC.value.equals(dimOrder))
            return 5;

import java.lang.reflect.Method;

public class SetDontInlineMethodTest extends CompilerWhiteBoxTest {
    private static final Object WHITE_BOX = getWhiteBox();
    private static final Method METHOD = getMethod();

    public static void test() {
        runTest();
    }

    private static void runTest() {
        // Check if the method is initially inlineable
        boolean isInlineable = WHITE_BOX.isInlineable(METHOD);
        assert isInlineable : "Method should be inlineable initially";

        // Set the method as non-inlinable
        WHITE_BOX.setDontInlineMethod(METHOD);

        // Verify that the method is now non-inlinable
        isInlineable = WHITE_BOX.isInlineable(METHOD);
        assert !isInlineable : "Method should be non-inlinable after setting";

        // Attempt to set the method as non-inlinable again
        WHITE_BOX.setDontInlineMethod(METHOD);

        // Verify that the method remains non-inlinable
        isInlineable = WHITE_BOX.isInlineable(METHOD);
        assert !isInlineable : "Method should still be non-inlinable";

        // Set the method as inlineable
        WHITE_BOX.setForceInlineMethod(METHOD);

        // Verify that the method is now inlineable
        isInlineable = WHITE_BOX.isInlineable(METHOD);
        assert isInlineable : "Method should be inlineable after setting";

        // Check the method's inlineability status after setting it as non-inlinable and then inlineable
        WHITE_BOX.setDontInlineMethod(METHOD);
        isInlineable = WHITE_BOX.isInlineable(METHOD);
        assert !isInlineable : "Method should be non-inlinable after setting";

        WHITE_BOX.setForceInlineMethod(METHOD);
        isInlineable = WHITE_BOX.isInlineable(METHOD);
        assert isInlineable : "Method should be inlineable after setting";
    }

    private static Object getWhiteBox() {
        // Implementation to get the WhiteBox object
        return null;
    }

    private static Method getMethod() {
        // Implementation to get the method being tested
        return null;
    }
}

