import java.util.Arrays;

public class ClosestPair {

    public static Pair getClosestPair(double[][] points) {
        Arrays.sort(points, (a, b) -> Double.compare(a[0], b[0])); // sort the points by x-coordinate
        return getClosestPair(points, 0, points.length - 1);
    }

    private static Pair getClosestPair(double[][] points, int low, int high) {
        if (low >= high) { // base case: only one or two points
            return low == high ? null : new Pair(points[low], points[high]);
        }

        int mid = (low + high) / 2;
        Pair leftPair = getClosestPair(points, low, mid);
        Pair rightPair = getClosestPair(points, mid + 1, high);
        Pair minPair = (leftPair == null) ? rightPair
                : (rightPair == null) ? leftPair
                : (leftPair.getDistance() < rightPair.getDistance()) ? leftPair : rightPair;

        // find the closest pair that crosses the midline
        double midX = points[mid][0];
        double[] strip = new double[high - low + 1];
        int j = 0;
        for (int i = low; i <= high; i++) {
            if (Math.abs(points[i][0] - midX) < minPair.getDistance()) {
                strip[j++] = points[i][1];
            }
        }
        Arrays.sort(strip, 0, j);
        for (int i = 0; i < j; i++) {
            for (int k = i + 1; k < j && strip[k] - strip[i] < minPair.getDistance(); k++) {
                double[] p1 = {midX, strip[i]};
                double[] p2 = {midX, strip[k]};
                Pair crossPair = new Pair(p1, p2);
                if (crossPair.getDistance() < minPair.getDistance()) {
                    minPair = crossPair;
                }
            }
        }

        return minPair;
    }

    public static void main(String[] args) {
        double[][] points = {{2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}};
        Pair closestPair = getClosestPair(points);
        System.out.println("The closest pair of points are " + Arrays.toString(closestPair.getP1())
                + " and " + Arrays.toString(closestPair.getP2()) + " with distance " + closestPair.getDistance());
    }
}

class Pair {
    private double[] p1;
    private double[] p2;

    public Pair(double[] p1, double[] p2) {
        this.p1 = p1;
        this.p2 = p2;
    }

    public double[] getP1() {
        return p1;
    }

    public double[] getP2() {
        return p2;
    }

    public double getDistance() {
        double dx = p1[0] - p2[0];
        double dy = p1[1] - p2[1];
        return Math.sqrt(dx * dx + dy * dy);
    }
}

class Node {
    int data;
    Node left, right;

    public Node(int item) {
        data = item;
        left = right = null;
    }
}

class BinaryTree {
    Node root;

    // Returns true if the given tree is perfect
    public boolean isPerfect(Node root) {
        // An empty tree is perfect
        if (root == null) {
            return true;
        }

        // Get the height of left and right sub-trees
        int leftHeight = height(root.left);
        int rightHeight = height(root.right);

        // If the height of left and right sub-trees differ more than 1,
        // the tree is not perfect
        if (Math.abs(leftHeight - rightHeight) > 1) {
            return false;
        }

        // If the left and right sub-trees are perfect and the current node
        // is a leaf node, the tree is perfect
        if (isPerfect(root.left) && isPerfect(root.right) && isLeaf(root)) {
            return true;
        }

        // If none of the above conditions are true, the tree is not perfect
        return false;
    }

    // Returns true if the given node is a leaf node
    public boolean isLeaf(Node node) {
        if (node == null) {
            return false;
        }
        if (node.left == null && node.right == null) {
            return true;
        }
        return false;
    }

    // Returns the height of the given tree
    public int height(Node node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(height(node.left), height(node.right));
    }
}

