public class Screen {

    public int width, height;
    public int[] pixels;

    public Screen(int width, int height) {
        this.width = width;
        this.height = height;
        pixels = new int[width*height];

        for(int i = 0; i < pixels.length; i++) {
            pixels[i] = 0xFFFFAAFF;
        }
    }

    public void clear() {
        for(int i = 0; i < pixels.length; i++) {
            pixels[i] = 0;
        }
    }

    public void renderSprite(int xp, int yp, Sprite sprite) {

        for(int y = 0; y < sprite.SIZE; y++) {
            int ya = y + yp;
            for(int x = 0; x < sprite.SIZE; x++) {
                int xa = x + xp;

                if(xa < -sprite.SIZE || xa >= width || ya < 0 || ya >= height) break;
                if(xa < 0) xa = 0;

                int col = sprite.pixels[x + y * sprite.SIZE];
                if(col != 0xFFFF00FF)
                    pixels[xa + ya * width] = col;
            }
        }
    }

    public void renderPlatform(int xp, int yp, int wp, Sprite sprite, Sprite sprite_l, Sprite sprite_r) {

        for(int y = 0; y < sprite_l.SIZE; y++) {
            int ya = y + yp;
            ya+=10;
            for(int x = 0; x < sprite_l.SIZE; x++) {
                int xa = x + xp;

                if(xa < -sprite_l.SIZE || xa >= width || ya < 0 || ya >= height) break;
                if(xa < 0) xa = 0;

                int col = sprite_l.pixels[x + y * sprite_l.SIZE];
                if(col != 0xFFFF00FF)
                    pixels[xa + ya * width] = col;
            }
        }

        for(int w = 1; w < wp - 1; w++) {
            for(int y = 0; y < sprite.SIZE; y++) {
                int ya = y + yp;
                ya+=10;
                for(int x = 0; x < sprite.SIZE; x++) {
                    int xa = x + xp + (w << 4);

                    if(xa < -sprite.SIZE || xa >= width || ya < 0 || ya >= height) break;
                    if(xa < 0) xa = 0;

                    int col = sprite.pixels[x + y * sprite.SIZE];
                    if(col != 0xFFFF00FF)
                        pixels[xa + ya * width] = col;
                }
            }
        }

        for(int y = 0; y < sprite_r.SIZE; y++) {
            int ya = y + yp;
            ya+=10;
            for(int x = 0; x < sprite_r.SIZE; x++) {
                int xa = x + xp + (wp-1 << 4);

                if(xa < -sprite_r.SIZE || xa >= width || ya < 0 || ya >= height) break;
                if(xa < 0) xa = 0;

                int col = sprite_r.pixels[x + y * sprite_r.SIZE];

import android.animation.Animator;
import android.animation.AnimatorListenerAdapter;
import android.content.Context;
import android.util.AttributeSet;
import android.view.View;

import androidx.coordinatorlayout.widget.CoordinatorLayout;
import androidx.core.view.ViewCompat;

import com.daimajia.androidanimations.library.Techniques;
import com.daimajia.androidanimations.library.YoYo;

public class ScaleTitlebarBehavior extends CoordinatorLayout.Behavior<View> {

    private boolean isTitleBarVisible = true;

    public ScaleTitlebarBehavior(Context context, AttributeSet attrs) {
        super(context, attrs);
    }

    public ScaleTitlebarBehavior() {
        super();
    }

    @Override
    public boolean onStartNestedScroll(CoordinatorLayout parent, View child, View directTargetChild, View target, int nestedScrollAxes, int type) {
        return (nestedScrollAxes & ViewCompat.SCROLL_AXIS_VERTICAL) != 0;
    }

    @Override
    public void onNestedScroll(CoordinatorLayout parent, View child, View target, int dxConsumed, int dyConsumed, int dxUnconsumed, int dyUnconsumed, int type) {
        if (dyConsumed > 0 && isTitleBarVisible) {
            hideTitleBar(child);
        } else if (dyConsumed < 0 && !isTitleBarVisible) {
            showTitleBar(child);
        }
    }

    private void hideTitleBar(final View titleBar) {
        isTitleBarVisible = false;
        YoYo.with(Techniques.ZoomOutUp)
                .duration(300)
                .onEnd(new YoYo.AnimatorCallback() {
                    @Override
                    public void call(Animator animator) {
                        titleBar.setVisibility(View.GONE);
                    }
                })
                .playOn(titleBar);
    }

    private void showTitleBar(final View titleBar) {
        isTitleBarVisible = true;
        titleBar.setVisibility(View.VISIBLE);
        YoYo.with(Techniques.ZoomInDown)
                .duration(300)
                .playOn(titleBar);
    }
}

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;

public class AppendTextToFile {
    public static void main(String[] args) {
        String fileName = "example.txt";
        String textToAppend = "This is the text that will be appended to the file.";

        try {
            File file = new File(fileName);
            if (!file.exists()) {
                file.createNewFile();
            }

            FileWriter fileWriter = new FileWriter(file, true);
            BufferedWriter bufferedWriter = new BufferedWriter(fileWriter);
            bufferedWriter.write(textToAppend);
            bufferedWriter.close();
            System.out.println("Text appended to file successfully!");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import com.gargoylesoftware.htmlunit.WebRequest;
import com.gargoylesoftware.htmlunit.WebResponse;
import com.gargoylesoftware.htmlunit.WebResponseData;
import com.gargoylesoftware.htmlunit.util.NameValuePair;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.test.web.reactive.server.FluxExchangeResult;
import org.springframework.util.Assert;

/**
 */
final class MockWebResponseBuilder {

    private final long startTime;

    private final WebRequest webRequest;

    private final FluxExchangeResult<String> exchangeResult;

    MockWebResponseBuilder(long startTime, WebRequest webRequest, FluxExchangeResult<String> exchangeResult) {
        Assert.notNull(webRequest, "WebRequest must not be null");
        Assert.notNull(exchangeResult, "FluxExchangeResult must not be null");
        this.startTime = startTime;
        this.webRequest = webRequest;
        this.exchangeResult = exchangeResult;
    }

    WebResponse build() throws IOException {
        WebResponseData webResponseData = webResponseData();
        long endTime = System.currentTimeMillis();
        return new WebResponse(webResponseData, this.webRequest, endTime - this.startTime);
    }

    private WebResponseData webResponseData() {
        List<NameValuePair> responseHeaders = responseHeaders();
        HttpStatus status = this.exchangeResult.getStatus();
        return new WebResponseData(this.exchangeResult.getResponseBodyContent(), status.value(),
                status.getReasonPhrase(), responseHeaders);
    }

    private List<NameValuePair> responseHeaders() {
        HttpHeaders responseHeaders = this.exchangeResult.getResponseHeaders();
        List<NameValuePair> result = new ArrayList<>(responseHeaders.size());
        responseHeaders.forEach((headerName, headerValues) -> headerValues
                .forEach((headerValue) -> result.add(new NameValuePair(headerName, headerValue))));
        return result;
    }

}

import java.io.*;
import java.util.zip.*;

public class Service {
    public static void main(String[] args) {
        // The file to compress
        String fileToCompress = "file.txt";
        // The compressed file
        String compressedFile = "file.zip";

        try (FileInputStream fis = new FileInputStream(fileToCompress);
             FileOutputStream fos = new FileOutputStream(compressedFile);
             ZipOutputStream zos = new ZipOutputStream(fos)) {

            // Create a new zip entry
            ZipEntry entry = new ZipEntry(fileToCompress);
            zos.putNextEntry(entry);

            // Write the file to the zip
            byte[] buffer = new byte[1024];
            int len;
            while ((len = fis.read(buffer)) > 0) {
                zos.write(buffer, 0, len);
            }

            // Close the zip entry and the zip output stream
            zos.closeEntry();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

