public class Jboss7DockerLiveTest extends BrooklynAppTestSupport {

    private static final String WAR_URL = "https://example.com/myapp.war";

    @Test
    public void doTest() {
        Location loc = getDockerLocation();
        doTest(loc);
    }

    public void doTest(Location loc) {
        EntitySpec<?> spec = EntitySpec.create(JBoss7Server.class)
                .configure("war", WAR_URL);
        Entity server = createAndManageChild(spec);
        server.start(ImmutableList.of(loc));
        URL url = (URL) server.getAttribute(WebServer.ATTRIBUTE_ROOT_URL);
        assertHttpStatusCodeEventuallyEquals(url, 200);
        assertContentContainsText(url, "Hello");
        Assert.assertNotNull(server.getAttribute(Attributes.REQUEST_COUNT));
        Assert.assertNotNull(server.getAttribute(Attributes.ERROR_COUNT));
        Assert.assertNotNull(server.getAttribute(Attributes.PROCESSING_TIME));
    }

    public Location getDockerLocation() {
        return new DockerLocation();
    }

    public Entity createAndManageChild(EntitySpec<?> spec) {
        return getManagementContext().getEntityManager().createEntity(spec);
    }
}

