import com.taobao.tddl.client.jdbc.TDataSource;
import com.taobao.tddl.client.jdbc.App;
import com.taobao.tddl.client.jdbc.ConnectionProperties;

public class TDDLExample {
    private static final Logger logger = Logger.getLogger(TDDLExample.class);

    public static void main(String[] args) {
        // Initialize logging
        initLogging();

        // Create a TDataSource instance
        TDataSource ds = new TDataSource();

        // Load configuration files
        ds.setConfigLocation("tddl-topology-dps.xml");
        ds.setRuleLocation("tddl-rule-dps-nonmysql.xml");

        // Initialize the data source
        ds.init();

        // Create sub-applications (databases)
        App subApp1 = new App("Simba2");
        App subApp2 = new App("Subway MySQL");

        // Add sub-applications to the data source
        ds.addApp(subApp1);
        ds.addApp(subApp2);

        // Set connection properties
        Map<String, String> cp = ConnectionProperties.getConnectionProperties();
        cp.put("username", "your_username");
        cp.put("password", "your_password");

        // Get a connection
        Connection conn = ds.getConnection();

        // Prepare and execute a SQL query
        String sql = getSql("solar_adgroup_list.sql");
        PreparedStatement pstmt = conn.prepareStatement(sql);
        ResultSet rs = pstmt.executeQuery();

        // Process the query results
        while (rs.next()) {
            System.out.println(rs.getString(1));
        }

        // Close the connection and result set
        rs.close();
        pstmt.close();
        conn.close();
    }

    private static void initLogging() {
        // Initialize Log4j logging
        InputStream inputStream = TDDLExample.class.getClassLoader().getResourceAsStream("log4j.properties");
        Log4jConfigurer.initLogging(inputStream);
    }

    private static String getSql(String sqlFile) {
        // Load SQL from a file
        return SqlFileUtil.getSql(sqlFile);
    }
}

