import java.io.IOException;
import java.nio.ByteBuffer;

public interface MessageStreamDecoder {

    /**
     * Processes data from the provided transport to decode messages.
     *
     * @param transport The data transport to read from.
     * @param max_bytes The maximum number of bytes to read from the transport.
     * @return The number of bytes actually read from the transport.
     * @throws IOException If an I/O error occurs during reading.
     */
    public int performStreamDecode(Transport transport, int max_bytes) throws IOException;

    /**
     * Retrieves and removes any messages that have been successfully decoded.
     *
     * @return An array of decoded messages, or an empty array if no messages are ready.
     */
    public Message[] removeDecodedMessages();

    /**
     * Returns the total number of protocol-related bytes decoded so far.
     *
     * @return The count of protocol bytes decoded.
     */
    public long getProtocolBytesDecoded();

    /**
     * Returns the total number of message payload bytes decoded so far.
     *
     * @return The count of data bytes decoded.
     */
    public long getDataBytesDecoded();

    /**
     * Returns the percentage of completion for the currently being decoded message.
     *
     * @return A value between 0 and 100 indicating the percentage complete, or -1 if no message is currently being decoded or progress cannot be determined.
     */
    public int getPercentDoneOfCurrentMessage();

    /**
     * Temporarily pauses the message decoding process.
     * Further calls to performStreamDecode will have no effect until decoding is resumed.
     */
    public void pauseDecoding();

    /**
     * Resumes the message decoding process after it has been paused.
     */
    public void resumeDecoding();

    /**
     * Releases any resources held by the decoder and potentially returns any unprocessed data.
     *
     * @return A ByteBuffer containing any data that was not fully processed, or null if no data remains.
     */
    public ByteBuffer destroy();
}

import org.springframework.shell.core.annotation.CliCommand;
import org.springframework.shell.core.annotation.CliAvailabilityIndicator;

import org.apache.geode.management.cli.CliMetaData;
import org.apache.geode.management.internal.cli.LogWrapper;
import org.apache.geode.management.internal.cli.i18n.CliStrings;
import org.apache.geode.management.internal.cli.result.model.ResultModel;
import org.apache.geode.management.internal.cli.result.model.InfoResultModel;
import org.apache.geode.management.internal.cli.shell.Gfsh;
import org.apache.geode.management.internal.cli.shell.OperationInvoker;
import org.apache.geode.management.internal.security.IntegratedSecurityService;

@CliCommand(value = CliStrings.DISCONNECT, help = CliStrings.DISCONNECT__HELP)
@CliMetaData(shellOnly = true, relatedTopics = {CliStrings.CONNECT})
public class DisconnectCommand extends OfflineGfshCommand {

  private static final LogWrapper logWrapper = LogWrapper.getInstance();

  @CliAvailabilityIndicator({CliStrings.DISCONNECT})
  public boolean isDisconnectAvailable() {
    return true;
  }

  @CliCommand(value = CliStrings.DISCONNECT, help = CliStrings.DISCONNECT__HELP)
  public ResultModel disconnect() {
    Gfsh gfsh = getGfsh();

    if (gfsh.isConnectedAndReady()) {
      OperationInvoker operationInvoker = gfsh.getOperationInvoker();
      operationInvoker.stop();

      InfoResultModel resultModel = ResultModel.createInfo();
      resultModel.addInfo().addLine(CliStrings.DISCONNECT_MESSAGE);

      if (!isHeadlessMode()) {
        gfsh.setPromptPath(gfsh.getEnvAppContextPath());
      }
      logWrapper.info(CliStrings.DISCONNECT_MESSAGE);
      return resultModel;
    } else {
      InfoResultModel resultModel = ResultModel.createInfo();
      resultModel.addInfo().addLine(CliStrings.NOT_CONNECTED_MESSAGE);
      logWrapper.info(CliStrings.NOT_CONNECTED_MESSAGE);
      return resultModel;
    }
  }
}

import java.util.Properties;
import javax.mail.Session;
import javax.mail.Message;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeMessage;

public class EmailClient {

    public static void main(String[] args) {
        try {
            Properties props = new Properties();
            props.put("mail.smtp.host", "smtp.example.com");
            props.put("mail.smtp.port", "587");
            props.put("mail.smtp.auth", "true");
            props.put("mail.smtp.starttls.enable", "true");

            Session session = Session.getInstance(props, null);

            Message message = new MimeMessage(session);
            message.setFrom(new InternetAddress("sender@example.com"));
            message.setRecipients(Message.RecipientType.TO, InternetAddress.parse("recipient@example.com"));
            message.setSubject("Test Email");
            message.setText("This is a test email sent from a Java program.");

            Transport transport = session.getTransport("smtp");
            transport.connect("smtp.example.com", "sender@example.com", "password");
            transport.sendMessage(message, message.getAllRecipients());
            transport.close();
            System.out.println("Email sent!");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

