import java.awt.Desktop;
import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;

import org.kurento.client.FaceOverlayFilter;
import org.kurento.client.HttpGetEndpoint;
import org.kurento.client.KurentoClient;
import org.kurento.client.MediaPipeline;
import org.kurento.client.PlayerEndpoint;
import org.kurento.client.WebRtcPeer;

public class KurentoHttpPlayer {

    public static void main(String[] args) throws URISyntaxException, IOException, InterruptedException {
        // Create a Kurento client
        KurentoClient kurento = KurentoClient.create();

        // Create a media pipeline
        MediaPipeline pipeline = kurento.createMediaPipeline();

        // Create a player endpoint
        PlayerEndpoint player = new PlayerEndpoint.Builder(pipeline).build();

        // Create a face overlay filter
        FaceOverlayFilter faceOverlay = new FaceOverlayFilter.Builder(pipeline).build();

        // Create an HTTP endpoint
        HttpGetEndpoint httpEndpoint = new HttpGetEndpoint.Builder(pipeline).build();

        // Connect the player to the face overlay filter
        player.connect(faceOverlay);

        // Connect the face overlay filter to the HTTP endpoint
        faceOverlay.connect(httpEndpoint);

        // Set the video file URL
        String videoFile = "http://files.kurento.org/video/small.webm";

        // Set the face overlay image URL
        String faceOverlayUrl = "http://files.kurento.org/img/mario-wings.png";

        // Set the face overlay filter
        faceOverlay.setOverlayedImage(faceOverlayUrl, -0.2f, -1.2f, 1.6f, 1.6f);

        // Play the media
        player.play(videoFile);

        // Get the HTTP endpoint URL
        String url = httpEndpoint.getUrl();

        // Open the video in the default desktop browser
        if (Desktop.isDesktopSupported()) {
            Desktop.getDesktop().browse(new URI(url));
        }

        // Add an event listener for the end of the stream event
        player.addEndOfStreamListener(event -> {
            System.out.println("End of stream");
            pipeline.release();
            kurento.close();
            System.exit(0);
        });

        // Wait for the end of the stream event
        Thread.sleep(70000);
    }
}

