import net.minecraft.entity.Entity;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.WorldServer;
import zornco.reploidcraft.ReploidCraft;
import zornco.reploidcraft.entities.EntityRideArmor;
import zornco.reploidcraft.utils.RiderState;
import io.netty.buffer.ByteBuf;
import cpw.mods.fml.common.FMLCommonHandler;
import cpw.mods.fml.common.network.simpleimpl.IMessage;
import cpw.mods.fml.common.network.simpleimpl.IMessageHandler;
import cpw.mods.fml.common.network.simpleimpl.MessageContext;
import cpw.mods.fml.relauncher.Side;

public class MessageRideArmor implements IMessage, IMessageHandler<MessageRideArmor, IMessage> {
    public float moveForward = 0.0F;
    public float moveStrafe = 0.0F;
    public boolean jump = false;
    public boolean sneak = false;
    public boolean dash = false;
    public boolean punch = false;
    public int ID = 0;
    public int dimension = 0;

    public MessageRideArmor() {}
    public MessageRideArmor(EntityRideArmor rideArmor, Entity entity) {
        if(rideArmor != null && entity != null){
            RiderState rs = ReploidCraft.proxy.getRiderState(entity);
            if (null != rs)
            {
                moveStrafe = rs.getMoveStrafe();
                moveForward = rs.getMoveForward();
                jump = rs.isJump();
                sneak = rs.isSneak();
            }
            ID = rideArmor.getEntityId();
            dimension = rideArmor.dimension;
        }
    }

    @Override
    public IMessage onMessage(MessageRideArmor message, MessageContext ctx) {
        RiderState rs = new RiderState();

        rs.setMoveForward(message.moveForward);
        rs.setMoveStrafe(message.moveStrafe);
        rs.setJump(message.jump);
        rs.setSneak(message.sneak);
        Entity armor = getEntityByID(message.ID, message.dimension);

        if( armor != null && armor instanceof EntityRideArmor)
        {
            ((EntityRideArmor)armor).setRiderState(rs);
        }
        return null;
    }

    @Override
    public void fromBytes(ByteBuf buf) {
        moveForward = buf.readFloat();
        moveStrafe = buf.readFloat();
        jump = buf.readBoolean();
        sneak = buf.readBoolean();
        dash = buf.readBoolean();
        punch = buf.readBoolean();
        ID = buf.readInt();
        dimension = buf.readInt();
    }

    @Override
    public void toBytes(ByteBuf buf) {
        buf.writeFloat(moveForward);
        buf.writeFloat(moveStrafe);
        buf.writeBoolean(jump);
        buf.writeBoolean(sneak);
        buf.writeBoolean(dash);

import io.cloudslang.content.vmware.utils.InputUtils;

/**
 * Represents the input parameters for establishing an HTTP connection.
 */
public class HttpInputs {

    private final String host;
    private final int port;
    private final String protocol;
    private final String username;
    private final String password;
    private final boolean trustEveryone;

    private HttpInputs(HttpInputsBuilder builder) {
        this.host = builder.host;
        this.port = builder.port;
        this.protocol = builder.protocol;
        this.username = builder.username;
        this.password = builder.password;
        this.trustEveryone = builder.trustEveryone;
    }

    public String getHost() {
        return host;
    }

    public int getPort() {
        return port;
    }

    public String getProtocol() {
        return protocol;
    }

    public String getUsername() {
        return username;
    }

    public String getPassword() {
        return password;
    }

    public boolean isTrustEveryone() {
        return trustEveryone;
    }

    public static HttpInputsBuilder builder() {
        return new HttpInputsBuilder();
    }

    /**
     * Builder class for HttpInputs.
     */
    public static class HttpInputsBuilder {
        private String host;
        private int port;
        private String protocol;
        private String username;
        private String password;
        private boolean trustEveryone;
        public static final int DEFAULT_HTTPS_PORT = 443;

        public HttpInputsBuilder withHost(String host) {
            this.host = host;
            return this;
        }

        public HttpInputsBuilder withPort(String port) {
            this.port = InputUtils.parseInt(port, DEFAULT_HTTPS_PORT);
            return this;
        }

        public HttpInputsBuilder withProtocol(String protocol) {
            this.protocol = protocol;
            return this;
        }

        public HttpInputsBuilder withUsername(String username) {
            this.username = username;
            return this;
        }

        public HttpInputsBuilder withPassword(String password) {
            this.password = password;
            return this;
        }

        public HttpInputsBuilder withTrustEveryone(String trustEveryone) {
            this.trustEveryone = InputUtils.parseBoolean(trustEveryone);
            return this;
        }

        public HttpInputs build() {
            return new HttpInputs(this);
        }
    }
}

