import java.awt.Component;
import java.awt.event.ActionEvent;
import javax.swing.AbstractAction;
import javax.swing.Icon;
import javax.swing.JMenuItem;
import org.parosproxy.paros.extension.ExtensionPopupMenuItem;
import org.zaproxy.zap.view.MessageContainer;

public class ExtensionPopupMenuItemMessageContainer extends ExtensionPopupMenuItem {

    private boolean enabledForComponents;
    private boolean enabledForMessageContainers;

    public ExtensionPopupMenuItemMessageContainer(String text) {
        super(text);
        this.enabledForComponents = false;
        this.enabledForMessageContainers = true;
    }

    public ExtensionPopupMenuItemMessageContainer(String text, Icon icon) {
        super(text, icon);
        this.enabledForComponents = false;
        this.enabledForMessageContainers = true;
    }

    public ExtensionPopupMenuItemMessageContainer(Action a) {
        super(a);
        this.enabledForComponents = false;
        this.enabledForMessageContainers = true;
    }

    @Override
    public boolean isEnableForComponent(Component invoker) {
        return enabledForComponents;
    }

    @Override
    public boolean isEnableForMessageContainer(MessageContainer invoker) {
        return enabledForMessageContainers;
    }

    public void setEnabledForComponents(boolean enabled) {
        this.enabledForComponents = enabled;
    }

    public void setEnabledForMessageContainers(boolean enabled) {
        this.enabledForMessageContainers = enabled;
    }

    public static void main(String[] args) {
        // Example usage
        ExtensionPopupMenuItemMessageContainer item = new ExtensionPopupMenuItemMessageContainer("Example Item");
        item.setEnabledForComponents(true);
        item.setEnabledForMessageContainers(false);

        // Create a new action
        AbstractAction action = new AbstractAction("Example Action") {
            @Override
            public void actionPerformed(ActionEvent e) {
                System.out.println("Action performed");
            }
        };

        // Create a new item with the action
        ExtensionPopupMenuItemMessageContainer itemWithAction = new ExtensionPopupMenuItemMessageContainer(action);
    }
}

