import com.linkedin.events.metadata.DatasetIdentifier;
import com.linkedin.events.metadata.DeploymentDetail;
import com.linkedin.events.metadata.MetadataChangeEvent;
import java.util.Collections;
import org.testng.annotations.Test;

import static org.testng.Assert.*;

public class KafkaLogCompactionConverterTest {

  @Test
  public void testConvert() {
    MetadataChangeEvent event = new MetadataChangeEvent();
    event.datasetIdentifier = new DatasetIdentifier();
    event.datasetIdentifier.dataPlatformUrn = "urn:li:dataPlatform:kafka";

    DeploymentDetail deployment = new DeploymentDetail();
    deployment.additionalDeploymentInfo = Collections.singletonMap("EI", "compact");
    event.deploymentInfo = Collections.singletonList(deployment);

    MetadataChangeEvent newEvent = new KafkaLogCompactionConverter().convert(event);
    assertEquals(newEvent.datasetIdentifier.dataPlatformUrn, "urn:li:dataPlatform:kafka-lc");
  }

  @Test
  public void testNotConvert() {
    KafkaLogCompactionConverter converter = new KafkaLogCompactionConverter();

    MetadataChangeEvent event = new MetadataChangeEvent();
    event.datasetIdentifier = new DatasetIdentifier();
    event.datasetIdentifier.dataPlatformUrn = "foo";

    DeploymentDetail deployment = new DeploymentDetail();
    deployment.additionalDeploymentInfo = Collections.singletonMap("EI", "compact");
    event.deploymentInfo = Collections.singletonList(deployment);

    MetadataChangeEvent newEvent = converter.convert(event);
    assertEquals(newEvent.datasetIdentifier.dataPlatformUrn, "foo");

    event.datasetIdentifier.dataPlatformUrn = "urn:li:dataPlatform:kafka";
    event.deploymentInfo = null;

    newEvent = converter.convert(event);
    assertEquals(newEvent.datasetIdentifier.dataPlatformUrn, "urn:li:dataPlatform:kafka");

    event.datasetIdentifier.dataPlatformUrn = "urn:li:dataPlatform:kafka";
    deployment.additionalDeploymentInfo = Collections.singletonMap("EI", "delete");
    event.deploymentInfo = Collections.singletonList(deployment);

    newEvent = converter.convert(event);
    assertEquals(newEvent.datasetIdentifier.dataPlatformUrn, "urn:li:dataPlatform:kafka");
  }
}

public class Filter {
    private static String serverName;
    private static final String CONTENT_TYPE_FILTER = "application/json";
    private static final int MAX_POST_FIELD_SIZE = 1024;
    private static final String RESPONSE_BODY = "responseBody";
    private static final String REQUEST_BODY = "requestBody";

    public static void setServerName(String name) {
        serverName = name;
    }

    public static String getServerName() {
        return serverName;
    }

    public static boolean isServerDetected() {
        return serverName != null;
    }

    public static boolean isNeed(String serverName, String contentType) {
        if (!isServerDetected()) {
            return false;
        }
        if (serverName.equals(Filter.serverName)) {
            return true;
        }
        if (contentType.equals(CONTENT_TYPE_FILTER)) {
            return true;
        }
        return false;
    }

    public static boolean isNeed(String serverName, byte[] body) {
        if (!isServerDetected()) {
            return false;
        }
        if (serverName.equals(Filter.serverName)) {
            return true;
        }
        if (body.length <= MAX_POST_FIELD_SIZE) {
            return true;
        }
        return false;
    }

    public static boolean isNeed(String serverName, String contentType, byte[] body) {
        if (!isServerDetected()) {
            return false;
        }
        if (serverName.equals(Filter.serverName)) {
            return true;
        }
        if (contentType.equals(CONTENT_TYPE_FILTER) && body.length <= MAX_POST_FIELD_SIZE) {
            return true;
        }
        return false;
    }
}

class LoginFragment extends BaseFragment {
  @Inject AccountManager accountManager;
  @InjectView(R.id.et_email) EditText emailText;
  @InjectView(R.id.et_password) EditText passwordText;
  @InjectView(R.id.sign_in) Button signInButton;
  @Inject @ClientId String clientId;
  @Inject @ClientSecret String clientSecret;

  ...

  private void doLogin(final String email, String password) {
    Observable<AccessToken> accessTokenObservable =
        apiService.getAccessTokenObservable(email, password,
            clientId,
            clientSecret);

    subscribe(accessTokenObservable, new EndlessObserver<AccessToken>() {
      @Override public void onNext(AccessToken accessToken) {
        Account account = addOrFindAccount(email, accessToken.refreshToken);
        // accountManager.setUserData(account, AccountAuthenticator.USER_ID, accessToken.userId);
        accountManager.setAuthToken(account, AuthConstants.AUTHTOKEN_TYPE, accessToken.accessToken);
        finishAccountAdd(email, accessToken.accessToken, accessToken.refreshToken);
      }

      @Override public void onError(Throwable throwable) {
        Timber.e(throwable, "Could not sign in");
        Toast.makeText(getActivity(), throwable.getMessage(), Toast.LENGTH_LONG).show();
      }
    });
  }

  private Account addOrFindAccount(String email, String password) {
    Account[] accounts = accountManager.getAccountsByType(AuthConstants.ACCOUNT_TYPE);
    Account account = accounts.length != 0 ? accounts[0] :
        new Account(email, AuthConstants.ACCOUNT_TYPE);

    if (accounts.length == 0) {
      accountManager.addAccountExplicitly(account, password, null);
    } else {
      accountManager.setPassword(accounts[0], password);
    }
    return account;
  }

  private void finishAccountAdd(String accountName, String authToken, String password) {
    final Intent intent = new Intent();
    intent.putExtra(AccountManager.KEY_ACCOUNT_NAME, accountName);
    intent.putExtra(AccountManager.KEY_ACCOUNT_TYPE, AuthConstants.ACCOUNT_TYPE);
    if (authToken != null)
      intent.putExtra(AccountManager.KEY_AUTHTOKEN, authToken);
    intent.putExtra(AccountManager.KEY_PASSWORD, password);
    setAccountAuthenticatorResult(intent.getExtras());
    getActivity().setResult(Activity.RESULT_OK, intent);
    getActivity().finish();

    // Go back to the main activity
    startActivity(new Intent(activityContext, MainActivity.class));
  }

}

import android.support.v7.widget.LinearLayoutManager;
import android.support.v7.widget.RecyclerView;

public abstract class EndlessRecyclerOnScrollListener extends RecyclerView.OnScrollListener {
    public static String TAG = EndlessRecyclerOnScrollListener.class.getSimpleName();

    private int previousTotal = 0; // The total number of items in the dataset after the last load
    private boolean loading = true; // True if we are still waiting for the last set of data to load.
    private int visibleThreshold = 5; // The minimum amount of items to have below your current scroll position before loading more.
    int firstVisibleItem, visibleItemCount, totalItemCount;

    private int current_page = 1;

    private LinearLayoutManager mLinearLayoutManager;

    public EndlessRecyclerOnScrollListener(LinearLayoutManager linearLayoutManager) {
        this.mLinearLayoutManager = linearLayoutManager;
    }

    @Override
    public void onScrolled(RecyclerView recyclerView, int dx, int dy) {
        super.onScrolled(recyclerView, dx, dy);

        visibleItemCount = recyclerView.getChildCount();
        totalItemCount = mLinearLayoutManager.getItemCount();
        firstVisibleItem = mLinearLayoutManager.findFirstVisibleItemPosition();

        if (loading) {
            if (totalItemCount > previousTotal) {
                loading = false;
                previousTotal = totalItemCount;
            }
        }
        if (!loading && (totalItemCount - visibleItemCount)
                <= (firstVisibleItem + visibleThreshold)) {
            // End has been reached

            // Do something
            current_page++;

            onLoadMore(current_page);

            loading = true;
        }
    }

    public abstract void onLoadMore(int current_page);
}

import java.util.List;
import jdk.vm.ci.meta.Assumptions;
import jdk.vm.ci.meta.ResolvedJavaMethod;
import org.graalvm.compiler.graph.NodeClass;
import org.graalvm.compiler.graph.StructuredGraph;

public class EncodedGraph {
    private final byte[] encoding;
    private final int startOffset;
    private final Object[] objects;
    private final NodeClass[] types;
    private final Assumptions assumptions;
    private final List<ResolvedJavaMethod> inlinedMethods;

    public EncodedGraph(byte[] encoding, int startOffset, Object[] objects, NodeClass[] types, Assumptions assumptions, List<ResolvedJavaMethod> inlinedMethods) {
        this.encoding = encoding;
        this.startOffset = startOffset;
        this.objects = objects;
        this.types = types;
        this.assumptions = assumptions;
        this.inlinedMethods = inlinedMethods;
    }

    public byte[] getEncoding() {
        return encoding;
    }

    public int getStartOffset() {
        return startOffset;
    }

    public Object[] getObjects() {
        return objects;
    }

    public NodeClass[] getNodeClasses() {
        return types;
    }

    public Assumptions getAssumptions() {
        return assumptions;
    }

    public List<ResolvedJavaMethod> getInlinedMethods() {
        return inlinedMethods;
    }
}

import java.io.IOException;

import evaluation.loadGenerator.ClientTrafficScheduleWriter;
import evaluation.loadGenerator.LoadGenerator;
import evaluation.loadGenerator.scheduler.ScheduleTarget;
import framework.core.util.IOTester;
import framework.core.util.Util;

public class ALRR_BasicWriter implements ScheduleTarget<ApplicationLevelMessage> {

    private final boolean IS_DUPLEX;
    private ClientTrafficScheduleWriter<ApplicationLevelMessage> owner;

    public ALRR_BasicWriter(ClientTrafficScheduleWriter<ApplicationLevelMessage> owner, boolean isDuplex) {
        this.owner = owner;
        this.IS_DUPLEX = isDuplex;
    }

    @Override
    public void execute(ApplicationLevelMessage message) {
        ALRR_ClientWrapper cw = (ALRR_ClientWrapper)owner.getClientWrapper(message.getClientId());
        synchronized (cw.outputStream) {
            try {
                message.setAbsoluteSendTime(System.currentTimeMillis());
                byte[] payload = message.createPayloadForRequest();
                String stats = "LOAD_GENERATOR: sending request ("
                        +"client:" +message.getClientId()
                        +"; transactionId:" +message.getTransactionId()
                        +"; requestSize: " +message.getRequestSize() +"bytes";
                if (message.getReplySize() != Util.NOT_SET)
                    stats += "; replySize: " +message.getReplySize() +"bytes";
                stats += ")";
                System.out.println(stats);
                if (LoadGenerator.VALIDATE_IO)
                    IOTester.findInstance(""+message.getClientId()).addSendRecord(payload);
                //System.out.println("" +this +": sending (client): " +Util.toHex(payload)); // TODO: remove
                cw.outputStream.write(payload);
                cw.outputStream.flush();
                if (IS_DUPLEX)
                    ALRR_ClientWrapper.activeTransactions.put(message.getTransactionId(), message);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}

import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

import java.io.File;
import java.io.FileNotFoundException;
import java.util.List;

public class LALParserTest {

    private LALParser parser;
    private Login simpleLogin;
    private File simpleFile;
    private File complexFile;
    private List<Login> complexLogins;

    @Before
    public void setUp() {
        parser = new LALParser();
        simpleLogin = new Login("user1", "pass1");
        simpleFile = getResource("simple.txt");
        complexFile = getResource("complex.txt");
        complexLogins = List.of(
                new Login("user1", "pass1"),
                new Login("user2", "pass2"),
                new Login("user3", "pass3")
        );
    }

    @After
    public void tearDown() {
        parser = null;
        simpleLogin = null;
        simpleFile = null;
        complexFile = null;
        complexLogins = null;
    }

    @Test
    public void testNull() {
        assertThrows(NullPointerException.class, () -> parser.parse(null));
    }

    @Test
    public void testFileParseSimple() throws FileNotFoundException {
        parser.parse(simpleFile);
        assertEquals(1, parser.getLogins().size());
        assertEquals(simpleLogin, parser.getLogins().get(0));
    }

    @Test
    public void testFileParseComplex() throws FileNotFoundException {
        parser.parse(complexFile);
        assertEquals(complexLogins.size(), parser.getLogins().size());
        for (int i = 0; i < complexLogins.size(); i++) {
            assertEquals(complexLogins.get(i), parser.getLogins().get(i));
        }
    }

    private File getResource(String filename) {
        return new File(getClass().getClassLoader().getResource(filename).getFile());
    }
}

