                } catch (SwitchableException | TimeoutException | InterruptedException e) {
                    e.printStackTrace();
                }
            }
        });
        t.start();
        sws.switchSocket(mockSocket2o, 1000);
        t.join();

        assertDuplexConnection(100, sws, swso);
    }

