            "电影1", "电影2", "电影3", "电影4", "电影5",
            "电影6", "电影7", "电影8", "电影9", "电影10"
    };
    private int index = 0;

    @Override
    public String next() {
        String film = FILMNAME[index];
        index = (index + 1) % FILMNAME.length;
        return film;
    }

    public static Generator<String> getFilmGenerator() {
        return new FilmGenerator();
    }
}

class Reader {
    public static String[] getFilms(String[] array, Generator<String> gen) {
        for (int i = 0; i < array.length; i++) {
            array[i] = gen.next();
        }
        return array;
    }

    public static <T extends Collection<String>> T getFilms(T collection, Generator<String> gen, int size) {
        for (int i = 0; i < size; i++) {
            collection.add(gen.next());
        }
        return collection;
    }

    public static void main(String[] args) {
        Generator<String> filmGen = FilmGenerator.getFilmGenerator();
        String[] filmsArray = new String[5];
        getFilms(filmsArray, filmGen);
