import org.gradle.internal.classpath.ClassPath;

import java.util.ArrayList;
import java.util.List;

public interface ClassLoaderScope {
    ClassLoader getLocalClassLoader();

    ClassLoader getExportClassLoader();

    ClassLoaderScope getParent();

    void local(ClassPath classPath);

    void export(ClassPath classPath);

    ClassLoaderScope createChild();

    void lock();

    boolean isLocked();
}

class DefaultClassLoaderScope implements ClassLoaderScope {
    private ClassLoader localClassLoader;
    private ClassLoader exportClassLoader;
    private ClassLoaderScope parent;
    private List<ClassPath> localClassPaths;
    private List<ClassPath> exportClassPaths;
    private boolean locked;
    private List<DefaultClassLoaderScope> children;

    public DefaultClassLoaderScope(ClassLoaderScope parent) {
        this.parent = parent;
        this.localClassPaths = new ArrayList<>();
        this.exportClassPaths = new ArrayList<>();
        this.children = new ArrayList<>();
    }

    @Override
    public ClassLoader getLocalClassLoader() {
        if (localClassLoader == null) {
            localClassLoader = createClassLoader(localClassPaths);
        }
        return localClassLoader;
    }

    @Override
    public ClassLoader getExportClassLoader() {
        if (exportClassLoader == null) {
            exportClassLoader = createClassLoader(exportClassPaths);
        }
        return exportClassLoader;
    }

    @Override
    public ClassLoaderScope getParent() {
        return parent;
    }

    @Override
    public void local(ClassPath classPath) {
        if (!locked) {
            localClassPaths.add(classPath);
            localClassLoader = null;
        }
    }

    @Override
    public void export(ClassPath classPath) {
        if (!locked) {
            exportClassPaths.add(classPath);
            exportClassLoader = null;
        }
    }

    @Override
    public ClassLoaderScope createChild() {
        DefaultClassLoaderScope child = new DefaultClassLoaderScope(this);
        children.add(child);
        return child;
    }

    @Override
    public void lock() {
        locked = true;
    }

    @Override
    public boolean isLocked() {
        return locked;
    }

    private ClassLoader createClassLoader(List<ClassPath> classPaths) {
        // Implement class loader creation logic here
        return null;
    }
}

