import koala.dynamicjava.tree.visitor.Visitor;

/**
 * This class represents the or expression nodes of the syntax tree
 *
 */

public class OrExpression extends BinaryExpression {
    /**
     * Initializes the expression
     *
     * @param lexp the LHS expression
     * @param rexp the RHS expression
     * @exception IllegalArgumentException if lexp is null or rexp is null
     */
    public OrExpression(final Expression lexp, final Expression rexp) {
        this(lexp, rexp, null, 0, 0, 0, 0);
    }

    /**
     * Initializes the expression
     *
     * @param lexp the LHS expression
     * @param rexp the RHS expression
     * @param fn the filename
     * @param bl the begin line
     * @param bc the begin column
     * @param el the end line
     * @param ec the end column
     * @exception IllegalArgumentException if lexp is null or rexp is null
     */
    public OrExpression(final Expression lexp, final Expression rexp, final String fn, final int bl, final int bc, final int el, final int ec) {
        super(lexp, rexp, fn, bl, bc, el, ec);
    }

    /**
     * Allows a visitor to traverse the tree
     *
     * @param visitor the visitor to accept
     */
    @Override
    public Object acceptVisitor(final Visitor visitor) {
        return visitor.visit(this);
    }
}

public class PalindromicPrimes {

    public static void main(String[] args) {
        int count = 0;
        int number = 2;

        while (count < 100) {
            if (isPalindrome(number) && isPrime(number)) {
                System.out.print(number + " ");
                count++;

                if (count % 10 == 0) {
                    System.out.println();
                }
            }

            number++;
        }
    }

    // Returns true if the given number is a palindrome
    public static boolean isPalindrome(int number) {
        int reversed = 0;
        int n = number;

        while (n > 0) {
            reversed = reversed * 10 + n % 10;
            n /= 10;
        }

        return reversed == number;
    }

    // Returns true if the given number is a prime number
    public static boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }
}

public class MultiplyMatrices {
    public static void main(String[] args) {
        int[][] firstMatrix = {{1, 2, 3}, {4, 5, 6}};
        int[][] secondMatrix = {{7, 8}, {9, 10}, {11, 12}};

        int rowsInFirstMatrix = firstMatrix.length;
        int columnsInFirstMatrix = firstMatrix[0].length;
        int rowsInSecondMatrix = secondMatrix.length;
        int columnsInSecondMatrix = secondMatrix[0].length;

        if (columnsInFirstMatrix != rowsInSecondMatrix) {
            System.out.println("The matrices can't be multiplied with each other.");
        } else {
            int[][] result = new int[rowsInFirstMatrix][columnsInSecondMatrix];
            for (int i = 0; i < rowsInFirstMatrix; i++) {
                for (int j = 0; j < columnsInSecondMatrix; j++) {
                    for (int k = 0; k < columnsInFirstMatrix; k++) {
                        result[i][j] += firstMatrix[i][k] * secondMatrix[k][j];
                    }
                }
            }
            System.out.println("Product of the matrices:");
            for (int[] row : result) {
                for (int column : row) {
                    System.out.print(column + " ");
                }
                System.out.println();
            }
        }
    }
}

