public class OrExpression extends BinaryExpression {
    public OrExpression(Expression lexp, Expression rexp) {
        this(lexp, rexp, null, -1, -1, -1, -1);
    }

    public OrExpression(Expression lexp, Expression rexp, String filename, int beginLine, int beginColumn, int endLine, int endColumn) {
        super(lexp, rexp, filename, beginLine, beginColumn, endLine, endColumn);
        if (lexp == null || rexp == null) {
            throw new NullPointerException("Left and right expressions must not be null");
        }
    }

    @Override
    public <T> T acceptVisitor(Visitor<T> visitor) {
        return visitor.visit(this);
    }

    @Override
    public String toString() {
        return getLeftExpression() + " || " + getRightExpression();
    }
}

abstract class BinaryExpression extends Expression {
    protected final Expression left;
    protected final Expression right;
    protected final String filename;
    protected final int beginLine;
    protected final int beginColumn;
    protected final int endLine;
    protected final int endColumn;

    public BinaryExpression(Expression left, Expression right, String filename, int beginLine, int beginColumn, int endLine, int endColumn) {
        this.left = left;
        this.right = right;
        this.filename = filename;
        this.beginLine = beginLine;
        this.beginColumn = beginColumn;
        this.endLine = endLine;
        this.endColumn = endColumn;
    }

    public Expression getLeftExpression() {
        return left;
    }

    public Expression getRightExpression() {
        return right;
    }

    public String getFilename() {
        return filename;
    }

    public int getBeginLine() {
        return beginLine;
    }

    public int getBeginColumn() {
        return beginColumn;
    }

    public int getEndLine() {
        return endLine;
    }

    public int getEndColumn() {
        return endColumn;
    }
}

interface Visitor<T> {
    T visit(OrExpression expression);
    // Add more visit methods for other types of expressions
}

abstract class Expression {
    // Base class for all expressions
}

import org.apache.arrow.vector.TimeMilliVector;
import org.apache.arrow.vector.TimeMicroVector;
import org.apache.arrow.vector.TimeNanoVector;
import org.apache.arrow.vector.TimeSecVector;
import org.apache.arrow.vector.ValueVector;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.typeutils.RuntimeContext;
import org.apache.flink.types.Time;

import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.util.TimeZone;

public class TimeFieldReader {

    private static final ZoneId LOCAL_TZ = ZoneId.systemDefault();
    private final ValueVector vector;
    private final TypeInformation<Time> typeInfo;

    public TimeFieldReader(ValueVector vector) {
        this.vector = vector;
        this.typeInfo = Types.TIME();
    }

    public Time read(int index) {
        if (vector.isNull(index)) {
            return null;
        }

        long timeInMs = getTimeInMs(index);
        ZoneOffset offset = LOCAL_TZ.getRules().getOffset(ZonedDateTime.now());
        long adjustedTimeInMs = timeInMs + offset.getTotalSeconds() * 1000;

        return new Time(adjustedTimeInMs);
    }

    private long getTimeInMs(int index) {
        if (vector instanceof TimeSecVector) {
            return ((TimeSecVector) vector).get(index) * 1000;
        } else if (vector instanceof TimeMilliVector) {
            return ((TimeMilliVector) vector).get(index);
        } else if (vector instanceof TimeMicroVector) {
            return ((TimeMicroVector) vector).get(index) / 1000;
        } else if (vector instanceof TimeNanoVector) {
            return ((TimeNanoVector) vector).get(index) / 1_000_000;
        } else {
            throw new UnsupportedOperationException("Unsupported time vector type");
        }
    }
}

