import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import java.io.*;

public class OpenSimplexDemo
{
    private static final long SEED = 0;
    private static final int WIDTH = 512;
    private static final int HEIGHT = 512;
    private static final double FREQUENCY = 1.0 / 24.0;

    public static void main(String[] args)
        throws IOException {

        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < HEIGHT; y++)
        {
            for (int x = 0; x < WIDTH; x++)
            {
                double value = OpenSimplex2S.noise3_ImproveXY(SEED, x * FREQUENCY, y * FREQUENCY, 0.0);
                int rgb = 0x010101 * (int)((value + 1) * 127.5);
                image.setRGB(x, y, rgb);
            }
        }
        ImageIO.write(image, "png", new File("noise.png"));
    }
}

import org.junit.Test;
import eu.europa.esig.dss.DiagnosticData;
import eu.europa.esig.dss.RevocationWrapper;
import eu.europa.esig.dss.RelatedCertificateWrapper;
import eu.europa.esig.dss.CertificateRefWrapper;

import java.io.InputStream;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class PAdESOCSPSigningCertificateTest extends AbstractTestValidation {

    @Override
    protected InputStream getSignedDocument() {
        return getClass().getResourceAsStream("/path/to/pades/document.pdf");
    }

    @Override
    protected void checkRevocationData(DiagnosticData diagnosticData) {
        RevocationWrapper revocationData = diagnosticData.getRevocationData();
        assertNotNull("Revocation data should not be null", revocationData);

        RelatedCertificateWrapper signingCertificate = revocationData.getSigningCertificate();
        assertNotNull("Signing certificate should not be null", signingCertificate);

        RelatedCertificateWrapper[] relatedCertificates = revocationData.getRelatedCertificates();
        assertTrue("Related certificates should not be empty", relatedCertificates.length > 0);

        for (RelatedCertificateWrapper relatedCertificate : relatedCertificates) {
            CertificateRefWrapper[] certificateRefs = relatedCertificate.getCertificateRefs();
            assertTrue("Certificate refs should not be empty", certificateRefs.length > 0);

            for (CertificateRefWrapper certificateRef : certificateRefs) {
                String uri = certificateRef.getUri();
                assertNotNull("Uri should not be null", uri);
            }
        }
    }

    @Test
    public void testPAdESOCSPSigningCertificate() {
        InputStream signedDocument = getSignedDocument();
        DiagnosticData diagnosticData = getDiagnosticData(signedDocument);
        checkRevocationData(diagnosticData);
    }
}

