}

class UserRecipe {
    private String type;

    public UserRecipe(String type) {
        this.type = type;
    }

    public String getType() {
        return type;
    }
}

public class Reader {
    public static void main(String[] args) {
        UserFactory factory = new UserFactory();
        factory.registerProvider(new UserProvider() {
            @Override
            public User build(Properties properties) throws Exception {
                return new PlatformUser();
            }

            @Override
            public String getType() {
                return "platform";
            }
        });

        try {
            User user = factory.build("platform", new Properties());
            System.out.println(user.getType());
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.ByteArrayInputStream;

/**
 * An InputStream decorator that simulates a slow data source by throttling
 * the amount of data read from the underlying stream in each read operation.
 */
public class SlowInputStream extends InputStream {

    private final InputStream origin;

    /**
     * Constructs a SlowInputStream that wraps the given InputStream.
     *
     * @param origin The underlying InputStream to decorate.
     */
    public SlowInputStream(InputStream origin) {
        this.origin = origin;
    }

    /**
     * Constructs a SlowInputStream with a ByteArrayInputStream of the specified size as the source.
     *
     * @param size The size of the underlying ByteArrayInputStream.
     */
    public SlowInputStream(int size) {
        this.origin = new ByteArrayInputStream(new byte[size]);
    }

    /**
     * Reads the next byte of data from the input stream.
     *
     * @return the next byte of data, or -1 if the end of the stream is reached.
     * @throws IOException if an I/O error occurs.
     */
    @Override
    public int read() throws IOException {
        return origin.read();
    }

    /**
     * Reads up to a specified number of bytes from the input stream into an array of bytes.
     * <p>
     * This method attempts to read slightly less data than requested to simulate slowness.
     *
     * @param b   the byte array to read into.
     * @param off the start offset in array {@code b} at which to write the data.
     * @param len the maximum number of bytes to read.
     * @return the total number of bytes read into the buffer, or -1 if there is no more data
     *         because the end of the input stream has been reached.
     * @throws IOException if an I/O error occurs.
     */
    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        if (len <= 0) {
            return 0;
        }
        int readLength = Math.max(1, len - (len / 10)); // Reduce read length by 10% but at least 1
        readLength = Math.min(readLength, len); // Ensure not reading more than requested
        return origin.read(b, off, readLength);
    }

    /**
     * Reads up to {@code b.length} bytes of data from this input stream into a byte array.
     *
     * @param b the byte array to read into.
     * @return the total number of bytes read into the buffer, or -1 if there is no more data
     *         because the end of the input stream has been reached.
     * @throws IOException if an I/O error occurs.
     */
    @Override

import java.io.File;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

public class LALFileTest {

    private LALParser parser;
    private Login simpleLogin;
    private File simpleFile;
    private File complexFile;
    private final Login[] complexLogins = new Login[]{
        new Login("// Comment"),
        new Login("user", "pass"),
        new Login("user", "pass", "display"),
        new Login("user", "pass", "display", "email", null, true),
        new Login("user", "pass", "display", "email", "oldpass", false),
        new Login("user", "pass", "display", "email", "oldpass", true),};

    @Before
    public void setUp() {
        parser = new LALParser();
        simpleLogin = new Login("user", "pass", "display", "email", "oldpass", true);
        simpleFile = getResource("simple.txt");
        complexFile = getResource("complex.txt");

        if (!simpleFile.exists() || !complexFile.exists()) {
            Assert.fail();
        }
    }

    @Test(expected = Exception.class)
    public void testNull() {
        parser.load((String) null);
    }

    @Test
    public void testFileParseSimple() {
        parser.clear();
        parser.load(simpleFile);

        Assert.assertTrue(parser.size() == 1);
        Assert.assertTrue(parser.contains(simpleLogin));
        Assert.assertTrue(parser.get(0).strictEquals(simpleLogin));
    }

    @Test
    public void testFileParseComplex() {
        parser.clear();
        parser.load(complexFile);

        Assert.assertTrue(parser.size() == complexLogins.length);
        for (int i = 0; i < parser.size(); i++) {
            Assert.assertTrue("Testing: " + parser.get(i).toString(), parser.get(i).strictEquals(complexLogins[i]));
        }
    }

    private File getResource(String fileName) {
        return new File(getClass().getClassLoader().getResource(fileName).getFile());
    }

}

import java.util.*;
import javax.mail.*;
import javax.mail.internet.*;

public class EmailSender {

    public static void main(String[] args) {

        String to = "recipient@example.com"; // replace with recipient email address
        String from = "sender@example.com"; // replace with sender email address
        String password = "yourpassword"; // replace with sender email password

        Properties props = new Properties();
        props.put("mail.smtp.host", "smtp.gmail.com"); // replace with SMTP server of your email provider
        props.put("mail.smtp.port", "587"); // replace with port number of SMTP server
        props.put("mail.smtp.auth", "true");
        props.put("mail.smtp.starttls.enable", "true");

        Session session = Session.getInstance(props, new Authenticator() {
            protected PasswordAuthentication getPasswordAuthentication() {
                return new PasswordAuthentication(from, password);
            }
        });

        try {
            Message message = new MimeMessage(session);
            message.setFrom(new InternetAddress(from));
            message.setRecipients(Message.RecipientType.TO, InternetAddress.parse(to));
            message.setSubject("Test Email with Attachment");

            // create a multipart message
            Multipart multipart = new MimeMultipart();

            // add the message body
            BodyPart messageBodyPart = new MimeBodyPart();
            messageBodyPart.setText("This is a test email with attachment.");
            multipart.addBodyPart(messageBodyPart);

            // add the attachment
            messageBodyPart = new MimeBodyPart();
            String filename = "example.txt"; // replace with the name of your attachment file
            DataSource source = new FileDataSource(filename);
            messageBodyPart.setDataHandler(new DataHandler(source));
            messageBodyPart.setFileName(filename);
            multipart.addBodyPart(messageBodyPart);

            // set the content of the message to the multipart message
            message.setContent(multipart);

            // send the message
            Transport.send(message);

            System.out.println("Email sent successfully");

        } catch (MessagingException e) {
            System.out.println("Failed to send email");
            e.printStackTrace();
        }
    }
}

