/**
 * This prerequisite check warns if Storm service is installed and rolling upgrade is requested.
 * It is intended to inform users about potential issues with Storm during rolling upgrades.
 */
@Singleton
public class StormShutdownWarning extends AbstractCheckDescriptor { // Assuming AbstractCheckDescriptor exists

    private static final String STORM_SERVICE_NAME = "STORM";

    @Override
    public boolean isApplicable(PrereqCheckRequest request) throws AmbariException {
        return super.isApplicable(request); // Assuming super class has some basic applicability logic
    }

    @Override
    public void perform(PrereqCheckRequest request, PrerequisiteCheck check) throws AmbariException {

        // Check if Storm service is installed
        boolean isStormInstalled = isServiceInstalled(request, STORM_SERVICE_NAME);

        // Check if the upgrade type is rolling
        boolean isRollingUpgrade = request.getUpgradeType() == UpgradeType.ROLLING;

        // If Storm is installed and it's a rolling upgrade, issue a warning
        if (isStormInstalled && isRollingUpgrade) {
            check.setStatus(PrereqCheckStatus.WARNING);
            check.setFailReason("Storm service might experience issues during a rolling upgrade. " +
                    "Please ensure compatibility and consider potential downtime.");
            check.setAffectedService(STORM_SERVICE_NAME); // Indicate the affected service
        } else {
            check.setStatus(PrereqCheckStatus.PASS); // If conditions not met, the check passes
        }
    }

    private boolean isServiceInstalled(PrereqCheckRequest request, String serviceName) {
        // Placeholder for service installation check logic
        // In a real implementation, this would involve querying the cluster state
        // to determine if the service is installed.
        // For now, we'll simulate a check based on the request parameters if available.
        if (request != null && request.getServices() != null) {
            return request.getServices().contains(serviceName);
        }
        return false; // Default to false if request or service list is not available
    }

