import java.io.IOException;
import java.nio.charset.Charset;

import okio.Buffer;

/**
 * An OkHttp interceptor that logs requests as curl shell commands. They can then
 * be copied, pasted and executed inside a terminal environment. This might be
 * useful for troubleshooting client/server API interaction during development,
 * making it easy to isolate and share requests made by the app. <p> Warning: The
 * logs generated by this interceptor have the potential to leak sensitive
 * information. It should only be used in a controlled manner or in a
 * non-production environment.
 */
public class CurlLoggingInterceptor implements Interceptor {

    private static final Charset UTF8 = Charset.forName("UTF-8");

    private final Logger logger;
    private String curlOptions;

    public CurlLoggingInterceptor() {
        this(Logger.DEFAULT);
    }

    public CurlLoggingInterceptor(Logger logger) {
        this.logger = logger;
    }

    /** Set any additional curl command options (see 'curl --help'). */
    public void setCurlOptions(String curlOptions) {
        this.curlOptions = curlOptions;
    }

    @Override public Response intercept(Chain chain) throws IOException {
        Request request = chain.request();

        boolean compressed = false;

        String curlCmd = "curl";
        if (curlOptions != null) {
            curlCmd += " " + curlOptions;
        }
        curlCmd += " -X " + request.method();

        Headers headers = request.headers();
        for (int i = 0, count = headers.size(); i < count; i++) {
            String name = headers.name(i);
            String value = headers.value(i);
            if ("Accept-Encoding".equalsIgnoreCase(name) && "gzip".equalsIgnoreCase(value)) {
                compressed = true;
            }
            curlCmd += " -H " + "\"" + name + ": " + value + "\"";
        }

        RequestBody requestBody = request.body();
        if (requestBody != null) {
            Buffer buffer = new Buffer();
            requestBody.writeTo(buffer);
            Charset charset = UTF8;
            MediaType contentType = requestBody.contentType();
            if (contentType != null) {
                charset = contentType.charset(UTF8);
            }

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CollaborativeFilteringRecommender {

    private int[][] ratings;
    private Map<Integer, List<Integer>> userToItems;

    public CollaborativeFilteringRecommender(int[][] ratings) {
        this.ratings = ratings;
        this.userToItems = new HashMap<>();
        for (int i = 0; i < ratings.length; i++) {
            List<Integer> items = new ArrayList<>();
            for (int j = 0; j < ratings[i].length; j++) {
                if (ratings[i][j] > 0) {
                    items.add(j);
                }
            }
            userToItems.put(i, items);
        }
    }

    public List<Integer> recommend(int user, int k) {
        List<Integer> similarUsers = findSimilarUsers(user, k);
        Map<Integer, Double> itemToScore = new HashMap<>();
        for (int i : userToItems.get(user)) {
            double sum = 0.0;
            double count = 0.0;
            for (int j : similarUsers) {
                if (userToItems.get(j).contains(i)) {
                    sum += ratings[j][i];
                    count += 1.0;
                }
            }
            if (count > 0.0) {
                itemToScore.put(i, sum / count);
            }
        }
        List<Integer> recommendations = new ArrayList<>();
        for (int i = 0; i < ratings[user].length; i++) {
            if (ratings[user][i] == 0 && itemToScore.containsKey(i)) {
                recommendations.add(i);
            }
        }
        recommendations.sort((i1, i2) -> Double.compare(itemToScore.get(i2), itemToScore.get(i1)));
        return recommendations;
    }

    private List<Integer> findSimilarUsers(int user, int k) {
        List<Integer> similarUsers = new ArrayList<>();
        double[] similarities = new double[ratings.length];
        for (int i = 0; i < ratings.length; i++) {
            if (i != user) {
                similarities[i] = cosineSimilarity(ratings[user], ratings[i]);
            }
        }
        for (int i = 0; i < k; i++) {
            int maxIndex = -1;
            double maxSimilarity = -1.0;
            for (int j = 0; j < similarities.length; j++) {
                if (similarities[j] > maxSimilarity) {
                    maxIndex = j;
                    maxSimilarity = similarities[j];
                }
            }
            similarUsers.add(maxIndex);
            similarities[maxIndex] = -1.0;
        }
        return similarUsers;
    }

