import org.apache.batik.dom.AbstractDocument;
import org.apache.batik.util.SVG12Constants;

import org.w3c.dom.Node;

/**
 * This class implements a multiImage extension to SVG.
 *
 * The 'multiImage' element is similar to the 'image' element (supports
 * all the same attributes and properties) except.
 * <ol>
 *    <li>It has two addtional attributes: 'pixel-width' and
 *        'pixel-height' which are the maximum width and height of the
 *        image referenced by the xlink:href attribute.</li>
 *    <li>It can contain a child element 'subImage' which has
 *        two attributes, pixel-width, pixel-height.
 *        It holds SVG content to be rendered.</li>
 *    <li>It can contain a child element 'subImageRef' which has only
 *        three attributes, pixel-width, pixel-height and xlink:href.
 *        The image displayed is the smallest image such that
 *        pixel-width and pixel-height are greater than or equal to the
 *        required image size for display.</li>
 * </ol>
 *
public class SVGOMMultiImageElement
    extends    SVGStylableElement {

    /**
     * Creates a new SVG MultiImageElement object.
     */
    protected SVGOMMultiImageElement() {
    }

    /**
     * Creates a new SVG MultiImageElement object.
     * @param prefix The namespace prefix.
     * @param owner The owner document.
     */
    public SVGOMMultiImageElement(String prefix, AbstractDocument owner) {
        super(prefix, owner);
    }

    /**
     * <b>DOM</b>: Implements {@link org.w3c.dom.Node#getLocalName()}.
     */
    public String getLocalName() {
        return SVG12Constants.SVG_MULTI_IMAGE_TAG;
    }

    /**
     * Returns a new uninitialized instance of this object's class.
     */
    protected Node newNode() {
        return new SVGOMMultiImageElement();
    }
}

import one.nio.util.Hash;

import java.io.IOException;

public class SharedMemoryStringMap<V> extends SharedMemoryMap<String, V> {

    public SharedMemoryStringMap(int capacity, String fileName, long fileSize) throws IOException {
        super(capacity, fileName, fileSize);
    }

    public SharedMemoryStringMap(int capacity, String fileName, long fileSize, long expirationTime) throws IOException {
        super(capacity, fileName, fileSize, expirationTime);
    }

    @Override
    protected String keyAt(long entry) {
        int keyLength = (int) (unsafe.getLong(entry + HASH_OFFSET) >>> 33);
        long keyOffset = entry + HEADER_SIZE;
        char[] key = new char[keyLength];
        for (int i = 0; i < keyLength; i++, keyOffset += 2) {
            key[i] = unsafe.getChar(keyOffset);
        }
        return new String(key);
    }

    @Override
    protected long hashCode(String key) {
        int stringHashCode = Hash.murmur3(key);
        return (long) key.length() << 33 | (stringHashCode & 0xffffffffL);
    }

    @Override
    protected boolean equalsAt(long entry, String key) {
        int keyLength = key.length();
        long keyOffset = entry + HEADER_SIZE;
        for (int i = 0; i < keyLength; i++, keyOffset += 2) {
            if (unsafe.getChar(keyOffset) != key.charAt(i)) {
                return false;
            }
        }
        return true;
    }

    @Override
    protected long allocateEntry(String key, long hashCode, int size) {
        int keyLength = key.length();
        long entry = allocator.segmentFor(hashCode).malloc(HEADER_SIZE + keyLength * 2 + size);
        long keyOffset = entry + HEADER_SIZE;
        for (int i = 0; i < keyLength; i++, keyOffset += 2) {
            unsafe.putChar(keyOffset, key.charAt(i));
        }
        return entry;
    }

    @Override
    protected int headerSize(long entry) {
        int keySizeInBytes = (int) (unsafe.getLong(entry + HASH_OFFSET) >>> 32);
        return HEADER_SIZE + keySizeInBytes;
    }
}

