import java.io.ByteArrayOutputStream;

/**
 * Sketch Project Studio
 */
public class AppHelper {

    /**
     * Turn drawable resource into byte array.
     *
     * @param context parent context
     * @param id      drawable resource id
     * @return byte array
     */
    public static byte[] getFileDataFromDrawable(Context context, int id) {
        Drawable drawable = ContextCompat.getDrawable(context, id);
        Bitmap bitmap = ((BitmapDrawable) drawable).getBitmap();
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        bitmap.compress(Bitmap.CompressFormat.PNG, 0, byteArrayOutputStream);
        return byteArrayOutputStream.toByteArray();
    }

    /**
     * Turn drawable into byte array.
     *
     * @param drawable data
     * @return byte array
     */
    public static byte[] getFileDataFromDrawable(Context context, Drawable drawable) {
        Bitmap bitmap = ((BitmapDrawable) drawable).getBitmap();
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        bitmap.compress(Bitmap.CompressFormat.JPEG, 80, byteArrayOutputStream);
        return byteArrayOutputStream.toByteArray();
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;

import org.eclipse.debug.core.DebugPlugin;
import org.eclipse.debug.core.ILaunch;
import org.eclipse.debug.core.ILaunchesListener;
import org.eclipse.php.internal.debug.core.pathmapper.VirtualPath;

public class ResolveBlackList implements ILaunchesListener {

    public enum Type {
        FILE, FOLDER, RECURSIVE,
    }

    private static Map<ILaunch, Map<VirtualPath, Type>> blackListMap;
    private static ResolveBlackList instance = new ResolveBlackList();

    private ResolveBlackList() {
        blackListMap = new HashMap<ILaunch, Map<VirtualPath, Type>>();

        DebugPlugin.getDefault().getLaunchManager().addLaunchListener(this);
    }

    public static ResolveBlackList getInstance() {
        return instance;
    }

    private static Map<VirtualPath, Type> getByLaunch(ILaunch launch) {
        if (!blackListMap.containsKey(launch)) {
            blackListMap.put(launch, new HashMap<VirtualPath, Type>());
        }
        return blackListMap.get(launch);
    }

    public void add(ILaunch launch, VirtualPath path, Type type) {
        getByLaunch(launch).put(path, type);
    }

    public boolean containsEntry(ILaunch launch, String file) {
        if (!VirtualPath.isAbsolute(file)) {
            return false;
        }
        Map<VirtualPath, Type> map = getByLaunch(launch);
        for (Entry<VirtualPath, Type> entry : map.entrySet()) {
            VirtualPath tmp = new VirtualPath(file);
            VirtualPath path = entry.getKey();
            Type type = entry.getValue();
            if (type == Type.FILE) {
                if (path.equals(tmp)) {
                    return true;
                }
            } else if (type == Type.FOLDER) {
                tmp.removeLastSegment();
                if (path.equals(tmp)) {
                    return true;
                }
            } else if (type == Type.RECURSIVE) {
                if (path.isPrefixOf(tmp)) {
                    return true;
                }
            }
        }
        return false;
    }

    public void launchesAdded(ILaunch[] launches) {
    }

    public void launchesChanged(ILaunch[] launches) {
    }

    public void launchesRemoved(ILaunch[] launches) {
        for (ILaunch l : launches) {
            blackListMap.remove(l);
        }
    }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;

public class TwoDColorChooser extends JFrame {

    private static final Color[][] COLORS = {
            {Color.RED, Color.GREEN, Color.BLUE},
            {Color.YELLOW, Color.CYAN, Color.MAGENTA},
            {Color.ORANGE, Color.PINK, Color.LIGHT_GRAY}
    };

    private JButton[][] colorButtons;
    private JPanel displayPanel;

    public TwoDColorChooser() {
        setTitle("Two-Dimensional Color Chooser");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        getContentPane().setLayout(new BorderLayout());

        gridPanel = new JPanel();
        gridPanel.setLayout(new GridLayout(COLORS.length, COLORS[0].length));
        colorButtons = new JButton[COLORS.length][COLORS[0].length];
        ColorButtonListener buttonListener = new ColorButtonListener();

        for (int i = 0; i < COLORS.length; i++) {
            for (int j = 0; j < COLORS[0].length; j++) {
                colorButtons[i][j] = new JButton();
                colorButtons[i][j].setBackground(COLORS[i][j]);
                colorButtons[i][j].setPreferredSize(new Dimension(50, 50));
                colorButtons[i][j].addActionListener(buttonListener);
                gridPanel.add(colorButtons[i][j]);
            }
        }

        displayPanel = new JPanel();
        displayPanel.setPreferredSize(new Dimension(200, 50));
        displayPanel.setBackground(Color.WHITE);

        getContentPane().add(gridPanel, BorderLayout.CENTER);
        getContentPane().add(displayPanel, BorderLayout.SOUTH);

        pack();
        setVisible(true);
    }

    private class ColorButtonListener implements ActionListener {
        @Override
        public void actionPerformed(ActionEvent e) {
            JButton clickedButton = (JButton) e.getSource();
            displayPanel.setBackground(clickedButton.getBackground());
        }
    }

    private JPanel gridPanel;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new TwoDColorChooser());
    }
}

