import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.CRC32;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

import com.google.common.base.Preconditions;
import com.google.common.io.ByteStreams;

public class ZipOutputFileProvider {
    private static final String DESUGAR_DEPS_FILENAME = "desugar_deps.txt";
    private final ZipOutputStream out;

    public ZipOutputFileProvider(OutputStream out) {
        this.out = new ZipOutputStream(out);
    }

    public void copyFrom(InputFileProvider input) throws IOException {
        try (InputStream in = input.open()) {
            write(in, input.getName());
        }
    }

    public void write(byte[] bytes, String path) throws IOException {
        writeStoredEntry(path, bytes);
    }

    public void close() throws IOException {
        out.close();
    }

    private void write(InputStream in, String path) throws IOException {
        if (path.endsWith(DESUGAR_DEPS_FILENAME)) {
            writeStoredEntry(path, ByteStreams.toByteArray(in));
        } else {
            // TODO: Optimize handling of resource files
            byte[] bytes = ByteStreams.toByteArray(in);
            writeStoredEntry(path, bytes);
        }
    }

    private void writeStoredEntry(String path, byte[] bytes) throws IOException {
        ZipEntry entry = new ZipEntry(path);
        entry.setTime(0); // Set timestamp to a stable value
        entry.setSize(bytes.length);
        entry.setCrc(calculateChecksum(bytes));
        entry.setMethod(ZipEntry.STORED);
        out.putNextEntry(entry);
        out.write(bytes);
        out.closeEntry();
    }

    private long calculateChecksum(byte[] bytes) {
        CRC32 crc = new CRC32();
        crc.update(bytes);
        return crc.getValue();
    }
}

import java.io.File;
import java.util.Properties;
import javax.activation.DataHandler;
import javax.activation.DataSource;
import javax.activation.FileDataSource;
import javax.mail.BodyPart;
import javax.mail.Message;
import javax.mail.MessagingException;
import javax.mail.Multipart;
import javax.mail.Session;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeBodyPart;
import javax.mail.internet.MimeMessage;
import javax.mail.internet.MimeMultipart;

public class EmailClient {
    public static void main(String[] args) {
        // recipient email address
        String to = "recipient@example.com";
        // sender email address
        String from = "sender@example.com";
        // email subject
        String subject = "Image Attachment";
        // email body
        String body = "Please find the attached image.";
        // image file to be attached
        String filePath = "path/to/image.jpg";

        // create properties object to set the host and port
        Properties properties = new Properties();
        properties.put("mail.smtp.host", "smtp.example.com");
        properties.put("mail.smtp.port", "587");

        // create a session with the properties
        Session session = Session.getDefaultInstance(properties);

        try {
            // create a new message
            Message message = new MimeMessage(session);
            message.setFrom(new InternetAddress(from));
            message.setRecipient(Message.RecipientType.TO, new InternetAddress(to));
            message.setSubject(subject);

            // create the body of the message
            BodyPart messageBodyPart = new MimeBodyPart();
            messageBodyPart.setText(body);

            // create a multipart message
            Multipart multipart = new MimeMultipart();
            multipart.addBodyPart(messageBodyPart);

            // add the file attachment
            messageBodyPart = new MimeBodyPart();
            DataSource source = new FileDataSource(filePath);
            messageBodyPart.setDataHandler(new DataHandler(source));
            messageBodyPart.setFileName("image.jpg");
            multipart.addBodyPart(messageBodyPart);

            // set the multipart message to the email message
            message.setContent(multipart);

            // send the message
            Transport.send(message);
            System.out.println("Email sent successfully with image attachment.");
        } catch (MessagingException e) {
            e.printStackTrace();
        }
    }
}

import org.apache.flink.annotation.Internal;
import org.apache.flink.util.Preconditions;

import org.apache.arrow.vector.TimeMicroVector;
import org.apache.arrow.vector.TimeMilliVector;
import org.apache.arrow.vector.TimeNanoVector;
import org.apache.arrow.vector.TimeSecVector;
import org.apache.arrow.vector.ValueVector;

import java.sql.Time;
import java.util.TimeZone;

/** {@link ArrowFieldReader} for Time. */
@Internal
public final class TimeFieldReader extends ArrowFieldReader<Time> {

    // The local time zone.
    private static final TimeZone LOCAL_TZ = TimeZone.getDefault();

    public TimeFieldReader(ValueVector valueVector) {
        super(valueVector);
        Preconditions.checkState(
                valueVector instanceof TimeSecVector
                        || valueVector instanceof TimeMilliVector
                        || valueVector instanceof TimeMicroVector
                        || valueVector instanceof TimeNanoVector);
    }

    @Override
    public Time read(int index) {
        ValueVector valueVector = getValueVector();
        if (valueVector.isNull(index)) {
            return null;
        } else {
            long timeMilli;
            if (valueVector instanceof TimeSecVector) {
                timeMilli = ((TimeSecVector) getValueVector()).get(index) * 1000;
            } else if (valueVector instanceof TimeMilliVector) {
                timeMilli = ((TimeMilliVector) getValueVector()).get(index);
            } else if (valueVector instanceof TimeMicroVector) {
                timeMilli = ((TimeMicroVector) getValueVector()).get(index) / 1000;
            } else {
                timeMilli = ((TimeNanoVector) getValueVector()).get(index) / 1000000;
            }
            return new Time(timeMilli - LOCAL_TZ.getOffset(timeMilli));
        }
    }
}

import it.unibas.lunatic.Scenario;
import it.unibas.lunatic.model.chase.chasede.operators.IReplaceDatabase;
import java.util.Iterator;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import speedy.model.algebra.operators.ITupleIterator;
import speedy.model.algebra.operators.mainmemory.MainMemoryInsertTuple;
import speedy.model.database.Cell;
import speedy.model.database.IDatabase;
import speedy.model.database.Tuple;
import speedy.model.database.mainmemory.MainMemoryDB;
import speedy.model.database.mainmemory.MainMemoryTable;
import speedy.model.database.mainmemory.MainMemoryVirtualDB;
import speedy.model.database.mainmemory.MainMemoryVirtualTable;

public class MainMemoryReplaceDatabase implements IReplaceDatabase {

    private final static Logger logger = LoggerFactory.getLogger(MainMemoryReplaceDatabase.class);
    private final static MainMemoryInsertTuple insert = new MainMemoryInsertTuple();

    public void replaceTargetDB(IDatabase newDatabase, Scenario scenario) {
        if (newDatabase instanceof MainMemoryDB) {
            scenario.setTarget(newDatabase);
            return;
        }
        MainMemoryVirtualDB virtualDB = (MainMemoryVirtualDB) newDatabase;
        if (logger.isDebugEnabled()) logger.debug("Copying virtual db\n" + newDatabase);
        MainMemoryDB mainMemoryDB = new MainMemoryDB(virtualDB.getDataSource());
        for (String tableName : mainMemoryDB.getTableNames()) {
            MainMemoryTable table = (MainMemoryTable) mainMemoryDB.getTable(tableName);
            emptyTable(table);
            insertAllTuples(table, (MainMemoryVirtualTable) virtualDB.getTable(tableName));
        }
        if (logger.isDebugEnabled()) logger.debug("New db\n" + mainMemoryDB);
        scenario.setTarget(mainMemoryDB);
    }

    private void emptyTable(MainMemoryTable table) {
        table.getDataSource().getInstances().get(0).getChildren().clear();
    }

    private void insertAllTuples(MainMemoryTable table, MainMemoryVirtualTable mainMemoryVirtualTable) {
        ITupleIterator it = mainMemoryVirtualTable.getTupleIterator();
        while (it.hasNext()) {
            Tuple tuple = it.next();
            removeOID(tuple);
            insert.execute(table, tuple, null, null);
        }
    }

    private void removeOID(Tuple tuple) {
        for (Iterator<Cell> it = tuple.getCells().iterator(); it.hasNext();) {
            Cell cell = it.next();
            if (cell.isOID()) {
                it.remove();
            }
        }
    }

}

import java.util.Random;

public class PetrolStationGenerator {
    private RandomIntegerGenerator randomIntegerGenerator;
    private RandomFloatGenerator randomFloatGenerator;
    private int minimalDistanceBetweenStations;
    private int maximumDistanceBetweenStations;
    private float minimalFuelPrice;
    private float maximumFuelPrice;

    public PetrolStationGenerator(RandomIntegerGenerator randomIntegerGenerator, RandomFloatGenerator randomFloatGenerator,
                                  int minimalDistanceBetweenStations, int maximumDistanceBetweenStations,
                                  float minimalFuelPrice, float maximumFuelPrice) {
        this.randomIntegerGenerator = randomIntegerGenerator;
        this.randomFloatGenerator = randomFloatGenerator;
        this.minimalDistanceBetweenStations = minimalDistanceBetweenStations;
        this.maximumDistanceBetweenStations = maximumDistanceBetweenStations;
        this.minimalFuelPrice = minimalFuelPrice;
        this.maximumFuelPrice = maximumFuelPrice;
    }

    public void generateStationsOnTheRoad(Road road) {
        int lastStationPosition = 0;
        while (lastStationPosition < road.getLength()) {
            int distanceToNextStation = randomIntegerGenerator.generateRandomInteger(minimalDistanceBetweenStations, maximumDistanceBetweenStations);
            if (lastStationPosition + distanceToNextStation > road.getLength()) {
                break;
            }
            PetrolStation station = generateStation(lastStationPosition + distanceToNextStation);
            road.addStation(station);
            lastStationPosition += distanceToNextStation;
        }
    }

    private PetrolStation generateStation(int positionOnRoad) {
        float fuelPrice = randomFloatGenerator.generateRandomFloat(minimalFuelPrice, maximumFuelPrice);
        return new PetrolStation(positionOnRoad, fuelPrice);
    }
}

class PetrolStation {
    private int positionOnRoad;
    private float fuelPrice;

    public PetrolStation(int positionOnRoad, float fuelPrice) {
        this.positionOnRoad = positionOnRoad;
        this.fuelPrice = fuelPrice;
    }

    public int getPositionOnRoad() {
        return positionOnRoad;
    }

    public float getFuelPrice() {
        return fuelPrice;
    }
}

